\section{Mean-field Iteration Equation of MLN Inference}
\label{app:meanfield}
\begin{proof}
The conditional probability distribution of MLN in the inference problem is defined as: 
\begin{equation}
p(\mathbf{v}|O) \propto \exp(\sum_{i} \phi_u(v_i) + \sum_{f\in F} w_f \sum_{g \in G_f} \phi_f(\textbf{v}_g))\,.
\end{equation}

$p(\mathbf{v}|O)$ is generally intractable since there is an exponential summation in the denominator.
Therefore, we propose to use a proxy variational distribution $Q(\mathbf{v})$ to approximate the $p(\mathbf{v}|O)$ by minimizing the KL divergence $D_{KL}(Q(\mathbf{v})||p(\mathbf{v}|O))$.
The proposed $Q(\mathbf{v})$ is an independent distribution over each variable, i.e., $Q(\mathbf{v})=\prod_i Q_i(v_i)$ where $\sum_{v_i\in \{0,1\}}Q_i(v_i)=1, Q_i(v_i) \ge 0$ is a proper probability.


Note that minimizing the KL divergence w.r.t. $Q(\mathbf{v})$ is equivalent to maximizing the evidence lower bound of $\log p(O)$: 
\begin{equation}
\begin{split}
D_{KL}(Q(\mathbf{v})||p(\mathbf{v}|O))&= \mathbb{E}_{Q(\mathbf{v})}\log \frac{Q(\mathbf{v})}{p(\mathbf{v}|O)} \\
&=\mathbb{E}_{Q(\mathbf{v})}\log {Q(\mathbf{v})} - \mathbb{E}_{Q(\mathbf{v})} {\log p(\mathbf{v}|O)} \\
&=\mathbb{E}_{Q(\mathbf{v})}\log {Q(\mathbf{v})} - \mathbb{E}_{Q(\mathbf{v})} {\log p(\mathbf{v}, O)} + \log p(O) \\
&=-(\mathbb{E}_{Q(\mathbf{v})} {\log p(\mathbf{v}, O)} - \mathbb{E}_{Q(\mathbf{v})}\log {Q(\mathbf{v})}) + \log p(O) \,,\\
\end{split}
\end{equation}
which is the negative evidence lower bound (ELBO) plus the log marginal probability of $O$ which is independent of $Q$.

Since $Q(\mathbf{v})=\prod_i Q_i(v_i)$, we have
\begin{equation}
 \mathbb{E}_{Q(\mathbf{v})}\log {Q(\mathbf{v})} = \sum_{i}\sum_{v_i} Q_i(v_i) \log Q_i(v_i)\,.
\end{equation}
and 
\begin{equation}
\begin{split}
\mathbb{E}_{Q(\mathbf{v})}\log {p(\mathbf{v}| O)} &=  \sum_{i, v_i} \phi_u(v_i)Q_i(v_i) + \sum_{f\in F} w_f\sum_{g\in G_f} \sum_{\textbf{v}_g} \phi_f(\textbf{v}_g) \prod_{i\in g} Q_i(v_i) - \log Z \,,
\end{split}
\end{equation}
where $Z$ is independent of $Q$.

We can therefore rewrite $D_{KL}(Q(\mathbf{v})||p(\mathbf{v}|O))$ with these two equations as
\begin{equation}
\mathcal{L} = \sum_{i, v_i} Q_i(v_i) \log Q_i(v_i)  - \sum_{i, v_i} \phi_u(v_i)Q_i(v_i) - \sum_{f\in F} w_f\sum_{g\in G_f} \sum_{\textbf{v}_g} \phi_f(\textbf{v}_g) \prod_{i\in g} Q_i(v_i) + \log Z \,.
\end{equation}

Considering it as a function of $Q_i({v}_i)$ and remove the irrelevant terms, we have
\begin{equation}
\begin{split}
\mathcal{L}_i &= \sum_{v_i} Q_i(v_i) \log Q_i(v_i) \\
& - \sum_{v_i} Q_i(v_i) [\phi_u(v_i) + \sum_{f\in F} w_f\sum_{g\in G_f(i)} \sum_{\textbf{v}_{g_{-i}}} \phi_f(v_i, \textbf{v}_{g_{-i}}) \prod_{j\in g_{-i}} Q_j(v_i)] \,, \\
\end{split}
\end{equation}
where $g_{-i}$ is the ground variables except $i$ in the grounding $g$, $G_f(i)$ is the groundings of formula $f$ that involve ground atom $i$,

By the Lagrange multiplication theorem with the constraint that $\sum_{v_i} Q_i(v_i) = 1$, the problem becomes
\begin{equation}
\begin{split}
\arg \min_{Q_i(v_i)} \mathcal{L}'_i &= \sum_{v_i} Q_i(v_i) \log Q_i(v_i)\\
&-\sum_{v_i} Q_i(v_i) [\phi_u(v_i) + \sum_{f\in F} w_f\sum_{g\in G_f(i)} \sum_{\textbf{v}_{g_{-i}}} \phi_f(v_i, \textbf{v}_{g_{-i}}) \prod_{j\in g_{-i}} Q_j(v_i)] \\
&+ \lambda (\sum_{v_i} Q_i(v_i) - 1) \,.
\end{split}
\end{equation}

Taking the derivative with respect to $Q_i(v_i)$, we have
\begin{equation}
\frac{d \mathcal{L}'_i}{d Q_i(v_i)}= 1 + \log Q_i(v_i) - [\phi_u(v_i) + \sum_{f\in F} w_f\sum_{g\in G_f(i)} \sum_{\textbf{v}_{g_{-i}}} \phi_f(v_i, \textbf{v}_{g_{-i}}) \prod_{j\in g_{-i}} Q_j(v_i)] + \lambda \,.
\end{equation}

Let the gradient be equal to 0, we then have
\begin{equation}
Q_i(v_i) = \exp(\phi_u(v_i) + \sum_{f\in F} w_f\sum_{g\in G_f(i)} \sum_{\textbf{v}_{g_{-i}}} \phi_f(v_i, \textbf{v}_{g_{-i}}) \prod_{j\in g_{-i}} Q_j(v_i) - 1 - \lambda ) \,.
\end{equation}

Taking $\lambda$ out from the equation, we have

\begin{equation}
\begin{aligned}
Q_i(v_i) &= \frac{1}{Z_i} \exp(\phi_u(v_i) + \sum_{f\in F} w_f \sum_{g\in G_f(i)} \sum_{\mathbf{v}_{g_{-i}}} \phi_f(v_i, \mathbf{v}_{g_{-i}})\prod_{j \in {g_{-i}}} Q_j(v_j))  \,,  \\
\end{aligned}
\end{equation}
where $Z_i$ is the partition function.

For clarity of presentation, we define the message of a single grounding (grounding message) as
\begin{equation}
\begin{aligned}
Q_i(v_i) &= \frac{1}{Z_i} \exp(\phi_u(v_i) + \sum_{f\in F} w_f \sum_{g\in G_f(i)} \hat{Q}_{i, g}(v_i))  \,, \\
\hat{Q}_{i, g}(v_i)&=\sum_{\mathbf{v}_{g_{-i}}} \phi_f(v_i, \mathbf{v}_{g_{-i}})\prod_{j \in {g_{-i}}} Q_j(v_j) \,.
\end{aligned}
\end{equation}

Then we have the conclusion.
\end{proof}


\section{Terminology}
\label{app:terminology}

\textbf{Literal.} 
In mathematical logic, a literal is an atomic formula (also known as an atom or prime formula) or its negation. Literals can be divided into two types: a positive literal is just an atom (e.g., $l$) and a negative literal is the negation of an atom (e.g., $\neg l$).

\textbf{Clause.} 
A clause is a formula formed from a finite disjunction of literals.
A clause is true whenever at least one of the literals that form it is true.
Clauses are usually written as $(l_1 \vee l_2 ...)$, where the symbols $l_{i}$ are literals, e.g., $\mathtt{S}(a) \wedge \mathtt{F}(a, b) \implies \mathtt{S}(b)$.

\textbf{Implication.}
Every nonempty clause is logically equivalent to an implication of a head from a body, where the head is an arbitrary literal of the clause and the body is the conjunction of the negations of the other literals.
The equivalent implications of $\mathtt{S}(a) \wedge \mathtt{F}(a, b) \implies \mathtt{S}(b)$ are (1)   $\mathtt{S}(a) \wedge \mathtt{F}(a, b) \implies \mathtt{S}(b)$,  (2) $\mathtt{S}(a) \wedge \neg\mathtt{S}(b) \implies \neg\mathtt{F}(a, b)$ and (3) $\mathtt{F}(a,b) \wedge \neg\mathtt{S}(b) \implies \neg\mathtt{S}(a)$

\textbf{Conjunctive Normal Form (CNF).}
A formula is in conjunctive normal form if it is a conjunction of one or more clauses, where a clause is a disjunction of literals.
The CNF is usually written as $(l_{1,1} \vee l_{1, 2} ...) \wedge (l_{2,1} \vee l_{2, 2} ...)\wedge...$, where the symbols $l_{i,j}$ are literals, e.g., $(\mathtt{S}(a) \implies \mathtt{C}(a)) \wedge (\mathtt{C}(a) \implies \mathtt{S}(a))$.

\textbf{First-order Logic (FOL).}
FOL uses quantified variables over a set of constants, and allows the use of sentences that contain variables, so that rather than propositions such as ``Tom is a father, hence Tom is a man'', one can have expressions in the form ``for all person $x$, if $x$ is a father then $x$ is a man'', where ``for all'' is a quantifier, while $x$ is an argument.
%A first-order logic can be converted to CNF. %~\cite{DBLP:books/aw/RN2020}.
In general, the clause and CNF are used for propositional logic which does not use quantifiers.
In this work, we denote the first-order clause and first-order CNF with universal quantifiers, respectively.

\textbf{Ground Expression.}
A ground term of a formal system is a term that does not contain any variables.
Similarly, a ground formula is a formula that does not contain any variables.
A ground expression is a ground term or ground formula.
In this paper, the grounding of a formula means assigning values to the variables in the formula with universal quantifiers.
% In this paper, the grounding of a formula denotes an assignment of constants to the arguments in the formula with universal quantifiers.

