\section{Proof of Theorem: Message of Clause Considers True Premise Only}
\label{app:theorem}

\begin{lemma}
(No message of clause for the false premise.)
When each formula $f(\cdot; \mathbf{n})$ is a clause, for a particular state $\mathbf{v}^*_{g_{-i}}$ of a grounding $g\in G_f(i)$ that  $\exists j \in g_{-i}, v^*_j = \neg n_j$, the MF iteration of \textcolor{cfcolor}{Eq. 2} is equivalent for $\hat{Q}_{i,g}(v_i)\gets \sum_{\mathbf{v}_{g_{-i}}{\neq \mathbf{v}^*_{g_{-i}}}} \phi_f(v_i, \mathbf{v}_{g_{-i}})\prod_{j \in {g_{-i}}} Q_j(v_j)$.
\label{lemma:premise}
\end{lemma}

\begin{proof}


Let us consider a grounding $g^*$ in $G_f(i)$ and a grounding message from ${g^*_{-i}}$ to $i$ and there is a particular state $\mathbf{v}^*_{g^*_{-i}}$ that $\exists j \in {g^*_{-i}}, v^*_j = \neg n_j$.
We explicitly extract the grounding message of state $\mathbf{v}^*_{g^*_{-i}}$ from the overall potential as below,
\begin{equation}
\begin{split}
Q_i(v_i) &= \frac{\exp(E_i(v_i))}{\sum_{v_i} \exp(E_i(v_i))}  \,, \\
E_i(v_i) &= \phi_f(v_i, \mathbf{v}^*_{g^*_{-i}}; \mathbf{n})\prod_{j \in {g^*_{-i}}} Q_j(v^*_j) + \Delta_i(v_i) \,,\\
\Delta_i(v_i) &= \phi_u(v_i)+ \sum_{\mathbf{v}_{g^*_{-i}}{\neq \mathbf{v}^*_{g^*_{-i}}}} \phi_f(v_i, \mathbf{v}_{g^*_{-i}}; \mathbf{n})\prod_{j \in {g^*_{-i}}} Q_j(v_j)  \\
&+ \sum_f w_f \sum_{g\in G_f(i)\backslash g^*} \sum_{\mathbf{v}_{g_{-i}}} \phi_f(v_i, \mathbf{v}_{g_{-i}}; \mathbf{n}^f)\prod_{j \in {g_{-i}}} Q_j(v_j)) \,. \\
\end{split}
\end{equation}

Since $\exists j \in {g^*_{-i}}, v^*_j = \neg n^f_j$, the clause will always be true regardless of $v_i$, i.e., $\forall v_i \in \{0, 1\}$, $\phi_f(v_i, \mathbf{v}^*_{g^*_{-i}})=1$.

Therefore, grounding message of state $\mathbf{v}^*_{g^*_{-i}}$ (i.e., $\phi_f(v_i, \mathbf{v}^*_{g^*_{-i}}; \mathbf{n}^f)\prod_{j \in {g^*_{-i}}} Q_j(v^*_j)$) is independent of $v_i$, then
\begin{equation}
E_i(v_i) = C +  \Delta_i(v_i) \,, C = w_f \prod_{j \in {g^*_{-i}}} Q_j(v^*_j) \,.
\end{equation}
The potential of $C$ is eliminated in the normalization step for $v_i=0$ and $v_i=1$.
We can apply the same logic to all the grounding messages and obtain the conclusion:
$Q_i(v_i) = \frac{1}{Z_i} \exp(\phi_u(v_i) + \sum_f w_f \sum_{g\in G_f(i)} \hat{Q}_{i,g}(v_i))$, where $\hat{Q}_{i,g}(v_i)=\sum_{\mathbf{v}_{g_{-i}}{\neq \mathbf{v}^*_{g_{-i}}}} \phi_f(v_i, \mathbf{v}_{g_{-i}})\prod_{j \in {g_{-i}}} Q_j(v_j) \,.$
\end{proof}


The proof of the theorem is simple by using this lemma.
\begin{proof}
By the lemma~\ref{lemma:premise}, only one remaining state needs to be considered, i.e., $\{v_j=n_j\}_{j \in {g_{-i}}}$.
The potential $\phi_f(\cdot)$ is 1 iff $v_i=\neg n_i$, otherwise $\hat{Q}_{i,g}(v_i) \gets 0$.
Then we derive the conclusion: $Q_i(v_i) \gets \frac{1}{Z_i} \exp(\phi_u(v_i) + \sum_f w_f \sum_{g\in G_f(i)} \hat{Q}_{i,g}(v_i))$, where $\hat{Q}_{i,g}(v_i) \gets \1_{v_i=\neg n^f_i} \prod_{j \in {g_{-i}}} Q_j(v_j=n^f_j)$.
\end{proof}

\section{Proof of Theorem: Message of CNF = $\sum$ Message of Clause}
\label{app:cnf}


\begin{proof}
%assume that the groundings of clauses have the same set of variables and
For convenience, let us consider a grounding $g^*$ in $G_{{f}}(i)$ where $f$ in CNF is the conjunction of several distinct clauses $f_k(\cdot; \mathbf{n}^{f_k})$:
\begin{equation}
\begin{split}
Q_i(v_i) &= \frac{\exp(E_i(v_i))}{\sum_{v_i} \exp(E_i(v_i))}  \,, \\
E_i(v_i) &= \sum_{\mathbf{v}_{g^*_{-i}}} \phi_{{f}}(v_i, \mathbf{v}_{g^*_{-i}})\prod_{j \in {g^*_{-i}}} Q_j(v_j) +  \Delta_i(v_i) \,,\\
\Delta_i(v_i) &= \phi_u(v_i) + \sum_f w_f \sum_{g\in G_f(i)\backslash g^*} \sum_{\mathbf{v}_{g_{-i}}} \phi_f(v_i, \mathbf{v}_{g_{-i}})\prod_{j \in {g^*_{-i}}} Q_j(v_j)) \,. \\
\end{split}
\end{equation}

Let $\mathbf{v}^k_{g^*_{-i}}$ be $\{n^{f_k}_j\}_{j \in {g^*_{-i}}}$, i.e., the corresponding true premises of clauses. 
We have
\begin{equation}
E_i(v_i) = \sum_{k} \phi_f(v_i, \mathbf{v}^k_{g^*_{-i}})\prod_{j\in \mathbf{v}^k_{g^*_{-i}}} Q_j(v^k_j) + \sum_{\mathbf{v}_{g^*_{-i}} \not \in \{\mathbf{v}^k_{g^*_{-i}}\}} \phi_{f}(v_i, \mathbf{v}_{g^*_{-i}})\prod_{j \in {g^*_{-i}}} Q_j(v_j)+\Delta_i(v_i) \,,
\end{equation}
where the second term can be directly eliminated as in the proof of Lemma~\ref{lemma:premise}.
We consider two cases that $\mathbf{v}^k_{g^*_{-i}}$ is unique or not for various $k$.
\begin{itemize}
\item Case 1: $\mathbf{v}^k_{g^*_{-i}}$ is unique: Since $\mathbf{v}^k_{g^*_{-i}}$ is unique, then $\phi_f(v_i, \mathbf{v}^k_{g^*_{-i}})= \1_{v_i=\neg n^{f_k}_i}$ and we can get the message by the same logic in \textcolor{cfcolor}{Theorem~\ref{theorem:premise}}, i.e., $ \1_{v_i=\neg n^{f_k}_i} \prod_{j \in {g^*_{-i}}} Q_j(v_j=n^{f_k}_j)$.
\item Case 2: $\mathbf{v}^k_{g^*_{-i}}$ is not unique: Let $\mathbf{v}^{k_1}_{g^*_{-i}}$ and $\mathbf{v}^{k_2}_{g^*_{-i}}$ be the same where $k_1$ and $k_2$ are two clauses in $f$. 
Since the clauses are unique, $n^{f_{k_1}}_i$ must be different with $n^{f_{k_2}}_i$.
The two potentials are eliminated, which is equivalent to the summation of distinct messages, i.e., $\sum_{k_1, k_2} \1_{v_i=\neg n^{f_k}_i} \prod_{j \in {g^*_{-i}}} Q_j(v_j=n^{f_k}_j)$.
%Since the clauses are distinct, the $n^{k_1}_i$ and $n^{k_2}_i$ must be either 0 or 1, which means $v_i$ makes no difference for this $v^{k_{1/2}}_{g_{-i}}$.
%We can see that using the proposed message is also correct by eliminating them.
\end{itemize}

We can apply this logic for all possible groundings and obtain:
$$Q_i(v_i) \gets \frac{1}{Z_i} \exp(\phi_u(v_i) + \sum_f w_f \sum_{g\in G_f(i)} \hat{Q}_{i,g}(v_i)),$$
where $\hat{Q}_{i,g}(v_i)\gets \sum_k \1_{v_i=\neg n^{f_k}_i} \prod_{j \in {g_{-i}}} Q_j(v_j=n^{f_k}_j)$, i.e., $\sum_{f_k} \1_{v_i=\neg n_i} \prod_{j \in {g_{-i}}}{Q_j(v_j=n_j)}$.
\end{proof}

This theorem directly leads to the following corollary.
\begin{corollary}
For the MLN, the mean-field update w.r.t. a CNF formula is equivalent to the mean-field update w.r.t. multiple clause formulas with the same rule weight.
\end{corollary}

\section{Extension of Multi-class Predicates}
\label{app:multiclass}
A typical MLN is defined over binary variables where the corresponding fact can be either true or false.
This is unusual in the modeling of common tasks, where the exclusive categories form a single multi-class classification.
For instance, a typical MLN will use several binary predicates to describe the category of a paper by checking whether the paper is of a certain category.
However, the categories are typically exclusive, and combining them can ease model learning.
Therefore, we extend LogicMP to model multi-class predicates.

Formally, let the predicates be multi-class classifications $r(\cdot): C \times ... \times C \to \{0, 1, ... \}$ with $\ge2$ categories, which is different with standard MLN.
The atom in the formula is then equipped with another configuration $\mathcal{Z}$ for the valid value of predicates.
For instance, a multi-class formula about ``RL paper cites RL paper'' can be expressed as
\begin{equation}
\mathtt{label}(x) \in  \{RL\} \vee \mathtt{cite}(x, y) \implies \mathtt{label}(y)\in \{RL\} \,,
\end{equation}
where $\mathtt{label}(x) \in RL$ means $x$ is a RL paper.
Sometimes the predicates in the formula appear more than one time, e.g., $\mathtt{label}(x)\in\{ML\} \vee \mathtt{label}(x)\in \{ RL\}...$.
We should aggregate them into a single literal $\mathtt{label}(x) \in \mathcal{Z}, \mathcal{Z}=\{RL, ML\}$.
A clause with multi-class predicates is then formulated as $... \vee (v_i \in \mathcal{Z}_i) \vee ...$ where $v_i$ is the variable associated with the atom $i$ in the clause and $\mathcal{Z}_i$ denotes the possible values the predicate can take.
With such notation, we rewrite the clauses with multi-class predicates as $f(\cdot; \mathcal{Z}^f)$ where $\mathcal{Z}^f=\{\mathcal{Z}_i\}_i$.
We show that the message of the multi-class clause can be derived by the following theorem.
\begin{theorem}
%With the multi-class clauses, for a grounding $g$ and a message $v_{g_{-i}} \rightarrow v_i$
When each formula with multi-class predicates $f(\cdot; \mathbf{\mathcal{Z}}^f)$ is a clause, the MF iteration of \textcolor{cfcolor}{Eq. 2} is equivalent for $\hat{Q}_i(v_i)= \1_{v_i \in \mathcal{Z}_i}\prod_{j \in {g_{-i}}}(1 - \sum_{v_j\in \mathcal{Z}_j}Q_j(v_j))$. %, where $\mathbb{1}$ returns 1 if $v_i \in \mathcal{Z}_i$.
\label{theorem:multiclass}
\end{theorem}
As the derivation is similar to that of binary predicates, we omit the detailed proof here. By setting $\mathcal{Z}=\{\neg n_i \}$ in the binary case, we can see that the message with multi-class predicates becomes the one with binary predicates. 
Similarly, when the formula is the CNF, the message can be calculated by aggregating the messages of clauses.


\section{Parallel Aggregation using Einstein Summation}
\label{app:parallel}

The virtue of parallel computation lies in the summation of the product, i.e., $\sum_{g\in G_f(i)}\prod_{j \in {g_{-i}}} Q_j(v_j=n_j)$ by \textcolor{cfcolor}{Theorem 3.1}, which indicates that the grounding message corresponds to the implication from the premise $g_{-i}$ to the hypothesis $i$. 
By the structure of MLN, many grounding messages belong to the same implication and have the calculation symmetries, so we group them by their corresponding implications. 
The aggregation of grounding messages w.r.t. an implication amounts to integrating some rule arguments and we can therefore formalize the aggregation into Einsum.
For instance, the aggregation w.r.t. the implication $\mathtt{S}(a) \wedge \mathtt{F}(a, b) \implies \mathtt{S}(b)$ can be expressed as $\mathtt{einsum}(\text{``}a,ab\to b\text{''}, {\mathbf{Q}}_{\mathtt{S}}(\mathbf{1}),{\mathbf{Q}}_{\mathtt{F}}(\mathbf{1}))$ where $\mathbf{Q}_{r}(\mathbf{v}_{r})$ denotes the collection of marginals w.r.t. predicate $r$, i.e.,  $\mathbf{Q}_{r}(\mathbf{v}_{r})=\{{Q}_{r(\mathcal{A}_{r})}(v_{r(\mathcal{A}_{r})})\}_{\mathcal{A}_{r}}$ ($\mathcal{A}_{r}$ is the arguments of $r$).
\textcolor{cfcolor}{Fig.~\ref{fig:applogicmp}} illustrates this process, where we initially group the variables by predicates and then use them to perform aggregation using parallel tensor operations.
The LogicMP layer on the right of \textcolor{cfcolor}{Fig.~\ref{fig:applogicmp}} gives a detailed depiction of the mechanism, where 3 clauses generate 7 implications and each first-order implication statement is transformed into an Einsum operation for parallel message computation.
Einsum also allows the computation for other complex formulae whose predicates have many arguments.


