\begin{figure}[t]
\begin{algorithm}[H]
    \caption{Obtaining normal state sequences from a golden simulation.}
    \label{alg_normal_seq}
    \begin{algorithmic}[1]
    \Function {acq\_normal\_seq}{$\GOLDENFIRINGRECORD$}
        \State $\mathit{prev\_state} \gets ""$
        \State $\mathit{normal\_seq} \gets []$
        \ForAll{$\mathit{element} \gets \mathit{golden\_firing\_record}$}
            \State $\mathit{state} \gets \mathit{element}$
            \State $\mathit{seq} \gets (\mathit{prev\_state}, \mathit{state})$
            \If {$\mathit{seq} \not \in \mathit{normal\_seq}$}
                \State $\mathbf{add}(\mathit{normal\_seq}, \mathit{seq})$
            \EndIf
            \State $\mathit{prev\_state} \gets \mathit{state}$
        \EndFor
        \State $\mathit{end\_trans} \gets \mathit{new\_trans}$
        \State \Return $\mathit{normal\_seq}, \mathit{end\_trans}$
    \EndFunction
    \end{algorithmic}
\end{algorithm}
%  \vspace*{-8mm}
\end{figure}

\begin{figure}[t]
\begin{algorithm}[H]
    %\caption{Calculate $y = x^n$}
    \caption{Error detection using normal state sequences.}
    \label{alg_detect_fault}
    \begin{algorithmic}[1]
    \Function {detection}{$\FIRINGRECORD, \NORMALSEQ, \ENDTRANS$}
        \State $\PREVTRANS \gets ""$
        \State $\FAULTDETECTED \gets \mathit{False}$
        \ForAll {$\ELEMENT \gets \FIRINGRECORD$}
            \State $\NEWTRANS \gets \ELEMENT$
            \State $\SEQ \gets (\PREVTRANS, new\_trans)$
            \If {$\SEQ \not \in \NORMALSEQ$}
                \State $\FAULTDETECTED \gets \mathit{True}$
            \EndIf
            \State $\PREVTRANS \gets \NEWTRANS$
        \EndFor
        \State $\LASTTRANS \gets \NEWTRANS$
        \If {$\LASTTRANS \neq \ENDTRANS$}
            \State $\FAULTDETECTED \gets \mathit{True}$
        \EndIf
        \State \Return $\FAULTDETECTED$
    \EndFunction
    \end{algorithmic}
\end{algorithm}
