    \centering
    \includegraphics[width=7.5cm]{figs/Hypervolume_mo-hopper-v4_5_4_25.eps}
    \caption{Evolution of the HV for the problem \texttt{mo-hopper-v4} with $n\_episodes=5$.}      
    \label{fig:RESULTS_CM_0_NEP_5}
