\section{SU-T: A MFT Baseline}
\subsection{Framework}

To address the unique challenges of MFT, we propose \textit{Scale-aware and Unscented Tracker} (SU-T), a specialized baseline following the SDE paradigm. As illustrated in Fig.~\ref{fig:baseline}, our framework comprises three primary components: a detector, an association module, and an optional Re-Identification (Re-ID) module. The processing pipeline begins with video frames being fed into the detector, which generates bounding boxes with corresponding confidence scores. These detections are then processed by the association module, where our specialized FishIoU metric calculates matching costs between detected boxes and predictions from the UKF. The Hungarian algorithm performs optimal assignment to update existing trajectories and establish new tracks when necessary. To address the challenge of visually similar fish, SU-T integrates an optional Re-ID module that extracts discriminative feature embeddings. These embeddings work synergistically with the FishIoU metric during association, significantly enhancing tracking accuracy by maintaining consistent identities even when fish exhibit nearly identical appearances.

\subsection{Unscented Kalman Filter}

\begin{figure}[tbp]
	\centering
	\includegraphics[width=0.95\linewidth]{figs/UKF.png}
	\caption{\textit{Unscented Kalman Filter} (UKF) motion model used in SU-T for predicting fish movement in complex underwater environments.}
	\label{fig:ukf}
\end{figure}

The \textit{Unscented Kalman Filter} (UKF) is particularly well-suited for tracking fish due to their non-linear motion patterns, as shown in Fig.~\ref{fig:ukf}. Unlike standard Kalman Filter, UKF uses a deterministic sampling technique to handle non-linearities. The three core mathematical components of our UKF implementation are as follows.

\subsubsection{Sigma Points Generation}
For state vector $\mathbf{x} \in \mathbb{R}^n$ with covariance $\mathbf{P}$, we generate $2n+1$ sigma points:

\begin{equation}
	\mathcal{X}_0 = \mathbf{x}
\end{equation}

\begin{equation}
	\mathcal{X}_i = \mathbf{x} + \left(\sqrt{(n+\lambda)\mathbf{P}}\right)_i, \quad i=1,\ldots,n
\end{equation}

\begin{equation}
	\mathcal{X}_{i+n} = \mathbf{x} - \left(\sqrt{(n+\lambda)\mathbf{P}}\right)_i, \quad i=1,\ldots,n
\end{equation}

\noindent where $\lambda = \alpha^2(n+\kappa)-n$ is a scaling parameter, $\alpha$ controls spread of points, $\kappa$ is a secondary parameter (typically 3-n), and $\left(\sqrt{(n+\lambda)\mathbf{P}}\right)_i$ is the $i$-th column of the matrix square root.

\subsubsection{Prediction Step}
Each sigma point is propagated through the non-linear state transition function $\mathbf{f}$:

\begin{equation}
	\mathcal{X}_{k|k-1}^i = \mathbf{f}(\mathcal{X}_{k-1}^i), \quad i=0,\ldots,2n
\end{equation}

\begin{equation}
	\hat{\mathbf{x}}_{k|k-1} = \sum_{i=0}^{2n} w_m^i \mathcal{X}_{k|k-1}^i
\end{equation}

\begin{equation}
	\mathbf{P}_{k|k-1} = \sum_{i=0}^{2n} w_c^i [\mathcal{X}_{k|k-1}^i - \hat{\mathbf{x}}_{k|k-1}][\mathcal{X}_{k|k-1}^i - \hat{\mathbf{x}}_{k|k-1}]^T + \mathbf{Q}_k
\end{equation}

\noindent where $w_m^i$ and $w_c^i$ are weight coefficients for mean and covariance, and $\mathbf{Q}_k$ is the process noise covariance.

\subsubsection{Measurement Update Step}
The predicted sigma points are transformed through the measurement function $\mathbf{h}$:

\begin{equation}
	\mathcal{Z}_{k|k-1}^i = \mathbf{h}(\mathcal{X}_{k|k-1}^i), \quad i=0,\ldots,2n
\end{equation}

\begin{equation}
	\hat{\mathbf{z}}_{k|k-1} = \sum_{i=0}^{2n} w_m^i \mathcal{Z}_{k|k-1}^i
\end{equation}

\begin{equation}
	\mathbf{P}_{zz} = \sum_{i=0}^{2n} w_c^i [\mathcal{Z}_{k|k-1}^i - \hat{\mathbf{z}}_{k|k-1}][\mathcal{Z}_{k|k-1}^i - \hat{\mathbf{z}}_{k|k-1}]^T + \mathbf{R}_k
\end{equation}

\begin{equation}
	\mathbf{P}_{xz} = \sum_{i=0}^{2n} w_c^i [\mathcal{X}_{k|k-1}^i - \hat{\mathbf{x}}_{k|k-1}][\mathcal{Z}_{k|k-1}^i - \hat{\mathbf{z}}_{k|k-1}]^T
\end{equation}

\begin{equation}
	\mathbf{K}_k = \mathbf{P}_{xz}\mathbf{P}_{zz}^{-1}
\end{equation}

\begin{equation}
	\hat{\mathbf{x}}_k = \hat{\mathbf{x}}_{k|k-1} + \mathbf{K}_k(\mathbf{z}_k - \hat{\mathbf{z}}_{k|k-1})
\end{equation}

\begin{equation}
	\mathbf{P}_k = \mathbf{P}_{k|k-1} - \mathbf{K}_k\mathbf{P}_{zz}\mathbf{K}_k^T
\end{equation}

\noindent where $\mathbf{z}_k$ is the actual measurement, $\mathbf{R}_k$ is the measurement noise covariance, and $\mathbf{K}_k$ is the Kalman gain.

\subsection{FishIoU: Scale-aware Association}

The unique morphology and movement patterns of fish present significant challenges for standard object association. We introduce \textit{Fish-Intersection-over-Union} (FishIoU), a specialized association IoU that accounts for the elongated body structure, erratic motion patterns, and size variations common in fish species.

Given two bounding boxes $B_1 = [x_1, y_1, x_2, y_2]$ and $B_2 = [x'_1, y'_1, x'_2, y'_2]$, we first compute the standard IoU as:

\begin{equation}
	\text{IoU} = \frac{|B_1 \cap B_2|}{|B_1 \cup B_2|}
\end{equation}

\noindent where $|B_1 \cap B_2|$ represents the intersection area and $|B_1 \cup B_2|$ the union area. Then, to account for fish morphology, we incorporate a center distance penalty:

\begin{equation}
	d_c = \frac{(c_x - c'_x)^2 + (c_y - c'_y)^2}{d_{\text{diag}}^2}
\end{equation}

\noindent where $(c_x, c_y)$ and $(c'_x, c'_y)$ are the centers of $B_1$ and $B_2$ respectively, and $d_{\text{diag}}^2$ is the squared diagonal length of the enclosing box. Considering fish bodies typically have an elongated structure with important features concentrated in the front, we define a central region for each box with asymmetric insets to emphasize this characteristic:

\begin{align}
	B_1^c &= [x_1 + \alpha w_1, y_1 + \beta h_1, x_2 - \gamma w_1, y_2 - \beta h_1] \\
	B_2^c &= [x'_1 + \alpha w_2, y'_1 + \beta h_2, x'_2 - \gamma w_2, y'_2 - \beta h_2]
\end{align}

\noindent where $w_1, h_1$ and $w_2, h_2$ are the width and height of $B_1$ and $B_2$ respectively, and $\alpha, \beta, \gamma$ are constant factors determined empirically based on fish morphological characteristics. By default, $\alpha = 0.15$, $\beta = 0.3$, and $\gamma = 0.25$. The central IoU is then calculated as:

\begin{equation}
	\text{cIoU} = \frac{|B_1^c \cap B_2^c|}{|B_1^c \cup B_2^c|}
\end{equation}

To account for consistent fish orientation, we consider the aspect ratio consistency:

\begin{equation}
	\alpha_r = \frac{\min(r_1, r_2)}{\max(r_1, r_2)}
\end{equation}

\noindent where $r_1 = \frac{w_1}{h_1}$ and $r_2 = \frac{w_2}{h_2}$ are the aspect ratios of the two boxes.

Additionally, we incorporate area ratio consistency, since the size of the fish does not change abruptly between frames:

\begin{equation}
	\alpha_a = \frac{\min(a_1, a_2)}{\max(a_1, a_2)}
\end{equation}

\noindent where $a_1 = w_1 \times h_1$ and $a_2 = w_2 \times h_2$ are the areas of the two boxes.

For small targets, we apply a scale factor to reduce the center distance penalty:

\begin{equation}
	s = 1 - e^{-\frac{\min(a_1, a_2)}{1000}}
\end{equation}

The final FishIoU metric combines these components with specific weights optimized for fish tracking:

\begin{equation}
	\text{FishIoU} = \omega_1 \cdot \text{IoU} + \omega_2 \cdot \text{cIoU} + \omega_3 \cdot \alpha_r + \omega_4 \cdot \alpha_a - \omega_5 \cdot s \cdot d_c
\end{equation}

\noindent where $\omega_1 = 1.0$, $\omega_2 = 0.3$, $\omega_3 = 0.1$, $\omega_4 = 0.2$, and $\omega_5 = 0.4$ are weights determined empirically through extensive experiments.

\subsection{Assocation}

Our association strategy employs progressive confidence-based processing that significantly reduces identity switches while maintaining computational efficiency. Algorithm \ref{alg:tracking} presents the complete multi-level cascade tracking process, which integrates our UKF motion prediction and FishIoU matching with a cascaded association strategy for aquatic environments.

Building upon frameworks from HybridSORT~\cite{yang2024hybrid}, we adopt dual-confidence matching of ByteTrack~\cite{zhang2022bytetrack} and heuristic observation-centric recovery of OC-SORT~\cite{cao2023observation}, and implements three association stages. In the first stage, high-confidence detections are matched with existing tracks using our specialized FishIoU, establishing reliable primary associations even when fish exhibit rapid direction changes. The second stage associates remaining tracks with low-confidence detections, effectively recovering temporarily occluded targets while filtering false positives induced by water turbidity and reflections. The final stage attempts to reconnect tracks with their historical appearances, addressing the frequent, abrupt directional changes and non-linear swimming patterns characteristic of fish locomotion.

For cost calculation, our framework integrates both spatial and appearance information when available. Spatially, the FishIoU outperforms standard IoU by incorporating fish-specific morphological features into the matching process. When enabled, the Re-ID module provides discriminative appearance embeddings that effectively differentiate between visually similar individuals swimming in close proximity.

\begin{algorithm}[tbp]
	\caption{Multi-Level Cascade Tracking}
	\label{alg:tracking}
	\SetAlgoLined

	\KwInput{Detections $\mathcal{D}$ with scores, Existing tracks $\mathcal{T}$}
	\KwOutput{Updated tracks $\mathcal{T}$}

	\textcolor{alogryellow}{/* Prediction */}\\
	\For{$T_j \in \mathcal{T}$}{
		\textcolor{alogrblue}{$\hat{B}_j, s_j \leftarrow$ UKF.predict($T_j$)} \textcolor{alogrgrey}{/* Predict box and score */}\\
	}

	\textcolor{alogryellow}{/* First Association: High-confidence */}\\
	$\mathcal{D}_{high} \leftarrow \{d_i \in \mathcal{D} : score(d_i) > \tau_{high}\}$\\
	\textcolor{alogrblue}{$\mathbf{C} \leftarrow$ FishIoU($\mathcal{D}_{high}$, $\{\hat{B}_j\}$)} \textcolor{alogrgrey}{/* Base cost */}\\
	\textcolor{alogrgreen}{\If{Use Re-ID}{$\mathbf{C} \leftarrow \omega_1 \mathbf{C} + \omega_2$ EmbeddingDistance($\mathcal{D}_{high}$, $\mathcal{T}$)}}
	$\mathcal{M}_1, \mathcal{U}_{\mathcal{D}}, \mathcal{U}_{\mathcal{T}} \leftarrow$ Hungarian($-\mathbf{C}$)\\

	\For{$(i,j) \in \mathcal{M}_1$}{$T_j$.update($d_i$)}

	\textcolor{alogryellow}{/* Second Association: Low-confidence */}\\
	$\mathcal{D}_{low} \leftarrow \{d_i \in \mathcal{D} : \tau_{low} < score(d_i) < \tau_{high}\}$\\
	\textcolor{alogrblue}{$\mathbf{C}_{iou} \leftarrow$ FishIoU($\mathcal{D}_{low}$, $\{\hat{B}_j : T_j \in \mathcal{U}_{\mathcal{T}}\}$)}\\
	\textcolor{alogrgreen}{\If{Use Re-ID}{$\mathbf{C}_{iou} \leftarrow \mathbf{C}_{iou} + \lambda \cdot$ EmbeddingDistance($\mathcal{D}_{low}$, $\{T_j \in \mathcal{U}_{\mathcal{T}}\}$)}}
	$\mathcal{M}_2 \leftarrow$ Hungarian($-\mathbf{C}_{iou}$)\\

	\For{$(i,j) \in \mathcal{M}_2$ where $\mathbf{C}_{iou}[i,j] > \tau_{iou}$}{
		$T_j$.update($\mathcal{D}_{low}[i]$) \textcolor{alogrgrey}{/* Update state */}\\
		$\mathcal{U}_{\mathcal{T}} \leftarrow \mathcal{U}_{\mathcal{T}} \setminus \{T_j\}$\\
	}

	\textcolor{alogryellow}{/* Third Association: Last-chance */}\\
	\textcolor{alogrblue}{$\mathbf{C}_{last} \leftarrow$ FishIoU($\mathcal{D}_{high}[\mathcal{U}_{\mathcal{D}}]$, $\{T_j.last\_observation : T_j \in \mathcal{U}_{\mathcal{T}}\}$)}\\
	\For{$(i,j) \in$ Hungarian($-\mathbf{C}_{last}$) where $\mathbf{C}_{last}[i,j] > \tau_{iou}$}{
		$T_j$.update($\mathcal{D}_{high}[\mathcal{U}_{\mathcal{D}}[i]]$)\\
		Remove $i$ from $\mathcal{U}_{\mathcal{D}}$, $T_j$ from $\mathcal{U}_{\mathcal{T}}$\\
	}

	\textcolor{alogryellow}{/* Finalize */}\\
	Update all $T_j \in \mathcal{U}_{\mathcal{T}}$ without observation\\
	Initialize new tracks from $\mathcal{D}_{high}[\mathcal{U}_{\mathcal{D}}]$\\
	Remove tracks with $time\_since\_update > max\_age$\\

	\Return $\mathcal{T}$
\end{algorithm}

