    Define $g(k):=\frac{k}{2N}$.  \\[5pt]
    %=\{u_1,u_2, ... u_{|E_1|}\}$, $E_2=\{u\in[N]: \t{gcd}(v,N) \t{ is even}\}=\{u'_1,u'_2, ... u'_{|E_2|}\}$, $F_1=\{u\in[N]: \t{gcd}(u,N) \t{ is divisible by}\}$
    For $i\in A$ consider the interval graphs $$I_{i}(v)=
     \begin{cases}
         [g(v),g(v)] & \text{ for } v\in F_{i,0,0} \\[5pt]
         [1+g(v),1+g(v)] & \text{ for } v\in F_{i,0,1} \\[5pt]
         [0,2] & \text{ for } v\in F_{i,1,1} \\[5pt]
         [1,2] & \text{ for } v\in F_{i,1,0} \\[5pt]
     \end{cases}$$
     and for $i\in B$ consider the interval graphs $$I_{i}(v)=
     \begin{cases}
         [g(v),g(v)] & \text{ for } v\in F_{i,0,0} \\[5pt]
         [1+g(v),1+g(v)] & \text{ for } v\in F_{i,0,1} \\[5pt]
         [2+g(v),2+g(v)] & \text{ for } v\in F_{i,1,0} \\[5pt]
         [1,2] & \text{ for } v\in F_{i,2,0} \\[5pt]
         [1.5,3] & \text{ for } v\in F_{i,1,1} \\[5pt]
         [0,3] & \text{ for } v\in F_{i,2,1} \\[5pt]
     \end{cases}$$
      Note that the graphs so constructed are indexed as $I_2,I_3, \cdots, I_a$ as discussed above.

   It can be easily verified by inspection that these graphs satisfy the requirements $1$ and $2$.\\
We will show that $E(\gz)= E(I_2) \cdots \cap E(I_a)$. Indeed if distinct vertices $u,v\in V(\gz)$ are adjacent in $\gz$ then $N$ divides $uv$. Consequently, for each $1\leq i\leq a$, $p_i^{n_i}$ divides $uv$. It follows that $f(p_i,\gcd(u,N))+f(p_i,\t{gcd}(v,N))\geq n_i$ for every $1\leq i\leq a$. By conditions $1(a)$ and $2(a)$ above, $u$ and $v$ are adjacent in each $I_i$. Therefore, these graphs are supergraphs of $\gz$.\\
Now suppose $u,v\in V(\gz)$ be distinct vertices that are not adjacent. Then there is a prime factor $p_i$ of $N$ for which \( f(p_i,\t{gcd}(u,N))+ f(p_i,\t{gcd}(v,N))<n_i\). 
\begin{itemize}
    \item Suppose $p_i\neq 2$, i.e. $i\neq 1$. 
    \begin{itemize}
        \item If $i\in A$, then \( f(p_i,\t{gcd}(u,N))+ f(p_i,\t{gcd}(v,N))<1\), i.e. $j_u+j_v<1$. It follows that both $1(a)$ and $1(b)$ are violated for $I_i$. By construction, $u,v$ are not adjacent in $I_i$.
        \item If $i\in B$, then \( f(p_i,\t{gcd}(u,N))+ f(p_i,\t{gcd}(v,N))<2\), i.e. $j_u+j_v<2$. It follows that both $2(a)$ and $2(b)$ are violated for $I_i$. By construction, $u,v$ are not adjacent in $I_i$.
    \end{itemize}
    \item Suppose $p_i= 2$, i.e. $i=1$. Here $k_u+k_v<1$. Then condition $1(a)$ or $2(a)$ is violated for each interval graph $I_l$ depending on whether $l\in A$ or $l\in B$. If for any $l\in A$, $1(b)$ is violated by $u,v$ in $I_l$ then $u,v$ would not be adjacent in $I_l$. Similarly, if for any $l\in B$, $2(b)$ is violated by $u,v $ in $I_l$ then $u,v$ would not be adjacent in $I_l$. Therefore, we can assume that $u,v\in F_l(1,0)$ for all $l\in A$ and $u,v\in F_l(2,0)$ for all $l\in B$. This means that for $x=u,v$, we have $f(p_l,\gcd(x,N))=1$ when $l\in A$ and $f(p_l,\gcd(x,N))=2$ when $l\in B$. It follows that 
    $$u=k_1\cdot \prod_{l\in A}^ap_l\prod_{l'\in B}^ap_{l'}^2 \t{ and }v=k_2\cdot \prod_{l\in A}^ap_l\prod_{l'\in B}^ap_{l'}^2 \t{ for some $k_1,k_2\in \mathbb{Z}^+$}$$
    Recalling that $n_l=1$ for $l\in A$ and $n_l=2$ for $l\in B$, we get: $$u=k_1\cdot \prod_{l=2}^ap_l^{n_l} \t{ and }v=k_2\cdot \prod_{l=2}^ap_l^{n_l} \t{ where $k_1,k_2\in \mathbb{Z}^+$}.$$ Since $u$ and $v$ are smaller than $N$, we must have $k_1<2$ and $k_2<2$. This forces $k_1=k_2=1$ which contradicts the fact that $u$ and $v$ are distinct numbers. Hence, $\exists $ $l$ such that $u,v$ are not adjacent in $I_l$.
\end{itemize}

   It follows that $E(\gz)=E(I_2)\cap E(I_3) \cdots \cap E(I_a)$ as claimed. (Note that the index starts from $2$). Hence, by theorem \ref{Roberts}, $box(\gz)\leq a-1$. 
\end{proof}
The following theorem follows directly as a consequence of lemmas \ref{lower},\ref{thmgz}, \ref{boximprov}. 
\begin{theorem}\label{box}
    Suppose $N=\Pi_{i=1}^a p_i^{n_i}$, where $n_i>0$ and $a\geq 2$, be the prime factorization of $N$ with $p_1<p_2< \cdots < p_a$. Then, $$box(\Gamma(\mathbb{Z}_N))=\begin{cases}
        a-1 & \text{if } N\equiv 2\pmod 4 \t{ and } n_i\leq 2 \text{ for }2\leq i\leq a\\
        a & \text{otherwise }
    \end{cases}$$
\end{theorem}
 \begin{remark}
         In \cite{TK}, it was incorrectly shown that $box(\gz)=1$ if and only if $N=p^n$ for $n\geq 3$ and some prime $p$ or $N=2p$ for some odd prime $p$. Only one direction of this statement is true and an easy counterexample for the other direction is when $N=18$. It is not hard to verify that in this case $box(\gz)=1$ but $N$ is of the form $2p^2$ for $p=3$. Our result captures this fact. 
     \end{remark}
The following theorem follows from lemma \ref{thmgz} and the fact that for any graph $G$, we have \\$\dimt(G)\geq box(G)$.
\begin{theorem}\label{th}
    Suppose $N=\Pi_{i=1}^a p_i^{n_i}$ be the prime factorization of $N$. Then,  $$a-1\leq \dimt(\gz)\leq a$$
\end{theorem}

\begin{corollary}\label{cubi}
   Suppose $N=\Pi_{i=1}^a p_i^{n_i}$ be the prime factorization of $N$ with $p_1<p_2< \cdots < p_a$ and $a\geq 2$. Then $$\frac{\log (\lfloor \sqrt{N/p_1^2}\rfloor-1)}{2}\leq cub(\Gamma(\mathbb{Z}_N))\leq  a\left\lceil{\log N}\right\rceil$$
\end{corollary}
\begin{proof}


The upper bound follows from lemma \ref{thmgz} and theorem \ref{cub} and observing that $|V(\gz)|<N$.\\[2pt] For the lower bound, observe that $\alpha(\gz)\geq \lfloor \sqrt{N/p_1^2}\rfloor-1$ since for every pair of distinct positive\\[2pt] integers $u,v<\sqrt{N/p_1^2}$, we have $uv<N/p_1^2$. Therefore, the set $\{p_1u: u<\sqrt{N/p_1^2}\}$ forms an\\[2pt] independent set of size at least $\lfloor \sqrt{N/p_1^2}\rfloor-1$.
    It is folklore that for any graph $G$, $cub(G)\geq \frac{\log(\alpha(G))}{\log(d+1)}$,\\[2pt] where $\alpha(G)$ is the independence number of $G$ and $d$ is the diameter. In \cite{anderson2011zero} it was proved that for any \\[2pt] zero divisor graph, the diameter is less than or equal to 3.  The lower bound follows. 
\end{proof}
\begin{corollary}\label{corgzc}
    Let $N=\Pi_{i=1}^a p_i^{n_i}.$ Then, $$ \dimc(\Gamma(\mathbb{Z}_N))\leq a.$$
\end{corollary}
\begin{proof}
    The corollary follows from observing that threshold graphs are cographs and theorem \ref{th}.
\end{proof}
\subsection{Results on \texorpdfstring{$\gr$}{gr} for a reduced ring \texorpdfstring{$R$}{R}}
A reduced ring $R$ is a ring for which $x\in R$, $x^2=0\implies x=0$. In this section, we will consider the case when $R$ is a non-zero finite commutative ring with identity with the extra property that it is also a reduced ring. \\
 We can define an equivalence relation $\sim_E$ on any graph $G$ such that for $x,y\in V(G),$ we have $ x\sim_E y$ if and only if $N(x)=N(y)$. If $G$ is a simple graph then it has no self loops and so $\sim_E$ partitions $V(G)$ into equivalence classes $P=\{[x_1],[x_2],\cdots [x_k]\}$ for some $k$ such that $[x_i]$ induces an independent set in $G$ for every $1\leq i\leq k$.   \begin{definition}\label{redgrap}
    The reduced graph $G_E$ of a graph $G$ is defined as the graph with $V(G_E)=P$ and $E(G_E)=\{[x][y]\t{ }|\t{ }xy\in E(G)\}$. 
\end{definition} 
\noindent Following the above notation, we will denote the reduced graph of $\gr$ as $\Gamma_E(R)$.\\
\textit{Notational comment: Reduced rings should not be confused with the reduced zero divisor graphs of a ring.}\\ Since we will be working with reduced rings $R$, for every $x\in R$ we have $x^2\neq 0$ and therefore $\gr$ does not have self loops. Therefore, the equivalence classes of $\gr$ under $\sim_E$ are all independent sets. In fact, it is not hard to see that for distinct vertices $u,v\in V(\gr),$ $uv\in E(\gr)$ if and only if $[u][v]\in E(\gre)$. 

\begin{theorem}\label{thm:redring}
    Let $R$ be a non-zero finite commutative ring with identity which is also a reduced ring. Then $$\lfloor k/2\rfloor\leq box(\Gamma(R))\leq\dimt(\gr)\leq  k,$$ where $k$ is the number of minimal prime ideals of $R$. 
\end{theorem}
\begin{proof}

 From \cite{ANDERSON20121626} we know that there exists an isomorphism $\phi:\Gamma_E(R) \rightarrow \Gamma(R')$, where $R' = \mathbb{Z}_2^k = \mathbb{Z}_2 \times \mathbb{Z}_2 \times ... \times \mathbb{Z}_2$ ($k$-copies). Note that, $V(\Gamma(R'))=(\Pi_{i=1}^k\mathbb{Z}_2) \setminus \{\mathbb{1},\mathbb{0}\}$ where $\mathbb{1},\mathbb{0}$ are the all ones and all zeroes vectors. This isomorphism allows us to view $V(\gre)$ as vectors consisting of $0$s and $1$s such that distinct vertices $x,y\in V(\gre)$ are adjacent in $\gre$ if and only if the point-wise product of the corresponding vectors $\phi(x)$ and $\phi(y)$ equals the zero vector.  \\
    Let $\pi_i:\Gamma(R')\rightarrow\mathbb{Z}_2$ be the function that returns the $i$th coordinate. Using $\pi_i$, we can rewrite the above observation as follows: for vertices $x,y\in V(\gre)$,  $xy\notin E(\Gamma_E(R))$  if and only if $\exists$ $i$ such that $\pi_i\circ\phi(x)=\pi_i\circ\phi(y)=1$, i.e. for both the vectors the $i$th component is $1$.\\ Define the sets $A_{i}=\{x\in \gre: \pi_i\circ\phi(x)=1 \}$. Then the induced graph on the vertices of $A_i$ is an independent set in $\gre$ for each $1\leq i\leq k$. Thus by the above discussion $xy\notin E(\gre)$ if and only if $\exists $ $i$ such that $x,y\in A_i$\\ 
 Fix an injective function $g:\gr\rightarrow [0,1]$. For each $i$, define the graph $I_i$ on $V(\gr)$ as follows: 
 $$I_i(v)=\begin{cases}
    [g(v),g(v)] &\t{ if }  [v]\in A_i\\
    [0,1] & \t{otherwise }
 \end{cases}$$
  The following claim is easy to see:\vspace{5pt}
 \begin{claim}5
     For two distinct vertices $u,v\in V(\gr)$, $uv\notin E(I_i)$ if and only if both $[u],[v]\in A_i$.
 \end{claim} $\blacksquare$ \\[5pt]
 We will show that $E(\gr)=E(I_1)\cap E(I_2) \cdots \cap E(I_k)$.\\
 Fix $u,v\in \gr$. It is easy to verify the following chain of equivalences:
 \begin{align}
     uv\in E(\gr) &\iff [u][v]\in E(\gre)\\& \iff \phi([u])\phi([v])\in E(\Gamma(R'))\\& \iff \forall \t{ } 1\leq i\leq k,\t{ } \pi_i(\phi([u]))\cdot \pi_i(\phi([u]))=0\\& \iff \forall \t{ } 1\leq i\leq k, \t{ } \t{at least one of }[u] \t{ or }[v] \t{ belongs to } A_i^c.
 \end{align}
 By claim 5 and implication (4), it follows that if $uv\in E(\gr)$ then $uv\in E(I_i)$ $\forall$ $ 1\leq i\leq k$ and if $uv\notin E(\gr)$ then $\exists$ $i$ such that $uv\notin E(I_i)$. Therefore, $E(\gr)=E(I_1)\cap E(I_2) \cdots \cap E(I_k)$.\\ Each interval graph $I_i$ is also a threshold graph. To see this, assign the vertex $v$ the weight $a_v=0$ if $[v]\in A_i$ and $a_v=1$ otherwise. By claim 5, $u$ and $v$ are adjacent in $I_i$ if and only if $a_u+a_v\geq 1$. By definition \ref{thresholddef}, $I_i$ are threshold graphs. This proves the upper bound.\\ 
  Finally, suppose $e_j$ be the $j$th standard basis vector, i.e the vector with $1$ at the $j$th position and $0$ everywhere else. Define the set $B_i=\{e_{2i-1},e_{2i-1}+e_{2i}\}$ for $1 \leq i\leq \floor{k/2}$. \\ Observe that $\bigsqcup_{i=1}^{\floor{k/2}}B_i$ induces the Robert's graph $\overline{\floor{k/2}K_2}$ in $\Gamma(R')$. This is easy to see since $B_i$ induces an independent set for each $i\in [\floor{k/2}]$ and for $i\neq j$ all edges are present between $B_i$ and $B_j$. So $box(\gr)\geq box(\gre)=box(\Gamma(R'))\geq  \lfloor k/2\rfloor$. This gives the lower bound. 
\end{proof}
\begin{remark}\label{err}
    In \cite{TK}, it was shown that $box(\gr)\geq k$. The proof for the lower bound assumed a fact which is not always true. The proof goes as follows:\\ They begin with the fact that $\gre\cong\Gamma(R')$, where $R'\cong\Z_2\times\Z_2\cdots \Z_2$($k$ times). Recall that the vertices of $\gre$ are equivalence classes of vertices of $\gr$ under the equivalence relation $u\sim_Ev$ if $N(u)=N(v)$. Suppose the isomorphism between $\gre$ and $\Gamma(R')$ is given by $\phi$. Let $e_i$ be the vector consisting of $1$ at the $i$th position and $0$ elsewhere. For $1\leq i\leq k$, consider the subgraphs $G_i$ induced by the equivalence classes $[\phi^{-1}(e_i)]$ in $\gr$. Note that for $1\leq i\leq k$, $G_i$ is a graph with no edges, i.e. it is an independent set in $\gr$. The mistake in the proof comes from assuming that for these graphs $G_i$, $box(G_i)=1$. With this incorrect assumption, they argue that the graph induced by the set $V(G_1)\cup V(G_2) \cdots \cup V(G_k)$ has boxicity $k$. Since this graph exists as an induced subgraph of $\gr$, they argue that $box(\gr)\geq k$. \\
    We provide a counterexample for the assumption that $box(G_i)=1$ for all $1\leq i\leq k$. Observe that this is true only when $|V(G_i)|>1$. Consequently, it suffices to show that there exist graphs $\gr$ such that for some $1\leq i\leq k$, $|V(G_i)|=1$.\\ Take $ N=2\times \Pi_{i=2}^{k} p_i$ and $R=\Z_N$. Note that $R$ is a reduced graph as every $u\in \gz$ has at least one prime factor missing and so $u^2\not\equiv 0\pmod N$. The elements of $\gre$ are all the divisors of $N$(see \cite{TK} for a proof). Therefore the elements of $\gre$ are of the form $2^{\alpha_1}\times \Pi_{i=2}^{k} p_i^{\alpha_i}$ where $\alpha_i\in \{0,1\}$ for $1\leq i\leq k$. Define $\phi:\gre\rightarrow \Gamma(R')$ given by $\phi(2^{\alpha_1}\times \Pi_{i=2}^{k} p_i^{\alpha_i})=(1-\alpha_1, 1-\alpha_2, \cdots , 1-\alpha_k)$. It is easy to verify that the map $\phi$ is an isomorphism. Observe that $\phi^{-1}(e_i)=\frac{N}{p_i}$. Therefore, the equivalence class $[\phi^{-1}(e_i)]$ is the set $\left\{\frac{N}{p_i}, \frac{2N}{p_i}, \cdots , \frac{tN}{p_i}\right\}$ where $t=p_i-1$. In particular, the equivalence class $[\phi^{-1}(e_1)]=\left\{\frac{N}{2}\right\}$ is a singleton set. It follows that the graph $G_1$ induced by $[\phi^{-1}(e_1)]$ is an isolated vertex and hence $box(G_1)=0$. This contradicts that $box(G_i)=1$ for $1\leq i\leq k$.
    %In the following theorem, we improve the upper bound. 
\end{remark}



\begin{corollary}
        Let $R$ be a non-zero finite reduced commutative ring with identity. Then, $$\dimc(\Gamma(R))\leq k,$$ where $k$ is the number of minimal prime ideals of $R$.
\end{corollary}
\section{Conclusion} 

In this paper, we have exactly determined the boxicity of $\gz$. In corollary \ref{cubi} we have shown that $\frac{\log (\lfloor \sqrt{N/p_1^2}\rfloor-1)}{2}\leq cub(\Gamma(\mathbb{Z}_N))\leq  a\ceil{\log N}$. In \cite{adiga2009cubicity}, it was shown that for an interval graph $G$, we have\\[2pt] $cub(G)\leq \ceil{\log(\alpha(G))}$ where $\alpha(G)$ is the size of the largest independent set in $G$. Using this result and with a little more work, it can be shown that $$cub(\gz)\leq a \log N+ \sum_{j=1}^a\left\{\log\left(1-\prod_{i=1}^a\left(1-\frac{1}{p_i}\right)-\frac{1}{p_j^{\ceil{n_j/2}}}\right),\right\}$$ by finding the largest independent set of every interval graph defined in the proof of lemma \ref{thmgz}. We omit the proof since it is not a significant improvement. Note that the second term in the upper bound is negative. Similarly, the lower bound can be improved to $$cub(\gz)\geq \frac{1}{2}\log N+\frac{1}{2}\max_{j\in [a]}\log\left(1-\prod_{i=1}^a\left(1-\frac{1}{p_i}\right)-\frac{1}{p_j^{\ceil{n_j/2}}}\right)$$ by the same kind of argument as in corollary \ref{cubi}. It is an interesting open problem to find the exact cubicity of this graph. More precisely, we pose the following problem,
\begin{question}
    Is it possible to show $\Omega(\log N)\leq cub(\gz)\leq O(a+\log N).$
\end{question} 
In this paper, we have provided bounds for $box(\gr)$. When $R$ is a non-zero commutative ring with identity that is also a reduced ring and taking $k$ to be the size of the set of minimal prime ideals of $R$, we have showed that $\floor{\frac{k}{2}}\leq box(\gr)\leq \dimt(\gz)\leq k$. 
It is an interesting question to ask if the gap between the lower bound and the upper bound can be closed.  \\
We also wonder whether any lower bounds for cograph dimension can be obtained for both $\gz$ and $\gr$. 
