\section{Hermite basis and Mehler's formula\label{app:hermite}}
Recall the Hermite expansion of the activation:
\begin{equation}
    \sigma(x) = \sum_{\ell = 0}^{\infty} \frac{\mu_\ell}{\ell !}\He_\ell (x).
    \label{eq:sigma_hermite}
\end{equation}
We are expressing it on the basis of the probabilist's Hermite polynomials, generated through
\begin{equation}
    \He_\ell(z) = \frac{\diff^\ell}{{\diff t}^\ell} \exp\big(t z - t^2/2 \big)\big|_{t=0}.
    \label{eq:hermite_G}
\end{equation}
The Hermite basis has the property of being orthogonal with respect to the standard Gaussian measure, which is the distribution of the input data:
\begin{equation}
    \int Dz\, \He_k(z) \He_\ell(z) = \ell!\,\delta_{k\ell} ,
\end{equation}
where $Dz := \diff z \exp(-z^2/2)/\sqrt{2\pi} $. By orthogonality, the coefficients of the expansions can be obtained as
\begin{equation}
    \mu_\ell = \int Dz \He_\ell(z)\sigma(z).
\end{equation}
Moreover,
\begin{equation}
    \label{eq:avg_sigma}
    \E[\sigma(z)^2] = \int D z\, \sigma(z)^2 = \sum_{\ell=0}^{\infty} \frac{\mu_\ell^2}{\ell!}.
\end{equation}
These coefficients for some popular choices of $\sigma$ are reported in Table~\ref{tab:Hermite} for reference.
%
\begin{table}[b]
    \caption{First Hermite coefficients of some activation functions reported in the figues. $\theta$ is the Heaviside step function.}
    \label{tab:Hermite}
    \vskip 0.15in
    \begin{center}
    \begin{small}
    \begin{tabular}{l|ccccccc}
