        $\relu(z) = z \theta(z)$ & $1/\sqrt{2 \pi }$ & $1/2$ & $1/\sqrt{2 \pi }$  & 0 & $-1/\sqrt{2 \pi }$& $\cdots$ & 1/2 \\
        $\elu(z) = z\theta(z) + (e^{z} - 1)\theta(-z) $ & 0.16052 & 0.76158 & 0.26158 & -0.13736 & -0.13736 & $\cdots$ & 0.64494 \\
%       $\tanh(z)$  & 0 & 0.60571 & 0 & -0.36359 & 0 & $\cdots$ & 0.39429 \\
