\section{Multi-dimensional problems}\label{sec:multiD}
In this section, we extend the one-dimensional DG scheme to multi-dimensional problems. The stability analysis and a priori error estimate are also provided. 


\subsection{The OF-EDG scheme in 2D}
We consider the model problem in a bounded domain $\mathbf{x}=(x,y)\in\Omega$ in $\mathbb{R}^2$,
\begin{equation}\label{eq:wave_2D}
    u_{tt} = \Delta u, \quad (\mathbf{x},t)\in \Omega\times(0,T ],
\end{equation}
with initial conditions
$$u(\mathbf{x},0) = u_0(\mathbf{x}),\qquad u_t(\mathbf{x},0) = u_1(\mathbf{x}).$$
We again consider periodic boundary conditions in each direction, and introduce the time derivative as a new variable $v = \dfrac{\partial u}{\partial t}$. The equation is rewritten as 
\begin{equation}
    \begin{cases}
        u_t = v,\\
        v_t = \Delta u,\\
    \end{cases} \quad (\mathbf{x},t)\in \Omega\times(0,T].
\end{equation}

For simplicity, we only present the formula for two-dimensional problems on a rectangular domain. We define   
$$K_{ij} = [x_{i-1/2},x_{i+1/2}]\times[y_{j-1/2},y_{j+1/2}],\qquad i = 1,\cdots,N_x, \, j = 1,\cdots,N_y,$$
with
$$h^x_i = x_{i+1/2} - x_{i-1/2},\quad 
h^y_j = y_{j+1/2} - y_{j-1/2}, $$
$$ h_{ij} = \sqrt{(h_i^x)^2 + (h_j^y)^2}, \quad h=\max h_{ij}.$$


Thus, the partition $\Gamma_h$ of $\Omega$ is 
\begin{equation}
\Gamma_h = \{K_{ij}\in\Omega,\, i=1, \ldots, N_x, j=1, \ldots, N_y\}.
\end{equation}
{We also define $\Gamma_e$ as the collection of the edges
\begin{equation}
\Gamma_e = \{e\in \partial K_{ij}, \,i=1, \ldots, N_x, j=1, \ldots, N_y \},
\end{equation}}
and define the discontinuous finite element space as 
\begin{equation}
V_h^k(\Omega) = \{w\in L^2(\Omega):w|_{K_{ij}}\in P^k(K_{ij}),\forall K_{ij}\in \Gamma_h \}.
\end{equation}

Following the idea in one dimension, we state the OF-EDG scheme in 2D as follows: find $u_h\in V^p_h(\Omega)$ and $v_h\in V^q_h(\Omega)$, such that for any $\phi^{(u)}(\mathbf{x})\in V^p_h(\Omega)$, $\phi^{(v)}(\mathbf{x})\in V^q_h(\Omega)$, $K_{ij}\in\Gamma_h$, 
\begin{equation}\label{eq:DG_2D}
    \begin{cases}
        \displaystyle
        \int_{K_{ij}}((u_h)_t-v_h)d\mathbf{x}&=0,\\
        \displaystyle
        \int_{K_{ij}}\nabla((u_h)_t-v_h)\cdot\nabla\phi^{(u)} d\mathbf{x}
        &=\displaystyle\int_{\partial K_{ij}} (\widehat{v} - v^-_h) (\nabla\phi^{(u),-} \cdot{\mathbf{n}})dS 
        + \dfrac{c}{h^2}\int_{\partial K_{ij}}([\![u_h]\!]\cdot\mathbf{n}) \phi^{(u),-} dS\\
         &\displaystyle\quad - \sum\limits_{l=1}^p\dfrac{\sigma_{ij}^l}{h_{ij}} \int_{K_{ij}} (\nabla u_h - \mathbb{P}^{l-1}\nabla u_h) \cdot\nabla\phi^{(u)} d\mathbf{x},   \\
        \displaystyle\int_{K_{ij}}((v_h)_t\phi^{(v)} + \nabla u_h\cdot\nabla\phi^{(v)})d\mathbf{x}
        &=\displaystyle\int_{\partial K_{ij}} ( \widehat{\nabla u}\cdot{\mathbf{n}}) \phi^{(v),-} dS 
        - \sum\limits_{l=0}^q\dfrac{\tilde{\sigma}_{ij}^l}{h_{ij}}\int_{K_{ij}}(v_h - \mathbb{P}^{l-1}v_h)\phi^{(v)} d\mathbf{x},
    \end{cases}
\end{equation}
where $\mathbf{n}$ represents the outward pointing normal of the element $K_{ij}$. 
The superscripts ``+" and ``-'' refer to traces of data from outside and inside the element, respectively. We define the jumps at the cell interface for a given function $w\in V^k_h$ as
\begin{equation}
    [\![w]\!] = w^+\mathbf{n}^+ + w^-\mathbf{n}^- \in \mathbb{R}^2, \qquad 
    {[\![\nabla w]\!] =\nabla w^+\cdot \mathbf{n}^+ + \nabla w^- \cdot \mathbf{n}^-} \in \mathbb{R} 
\end{equation}
{with $\bm{n}^-=\bm{n}$ and $\bm{n}^+=-\bm{n}$.}
As for the numerical fluxes $\widehat{\nabla u}$ and $\widehat{v}$, we again consider a general parameterization with $\alpha\in[0,1]$ and $\tau, \beta \geq0$. 
Using $\boldsymbol{\zeta} = (\alpha - \dfrac{1}{2},\alpha - \dfrac{1}{2})^T$, the numerical flux can be defined as follows,
\begin{equation}
    \begin{aligned}
     \widehat{\nabla u} &= \dfrac{\nabla u_h^+ + \nabla u_h^-}{2} - \left((\boldsymbol{\zeta}\cdot\mathbf{n}^+)\nabla u_h^+ + (\boldsymbol{\zeta}\cdot\mathbf{n}^-)\nabla u_h^-\right)-\beta[\![v_h]\!],\\
    \widehat{v} &= \dfrac{v_h^+ + v_h^-}{2} + \boldsymbol{\zeta}\cdot(v_h^+\mathbf{n}^+ + v_h^-\mathbf{n}^-) -\tau[\![\nabla u_h]\!]. \label{eq:flux_2D}
\end{aligned}
\end{equation}
It is easy to verify that with the following special parameters, the numerical fluxes are equivalent to those in 1D \eqref{eq:numerical_flux} along the horizontal or vertical cell-interface,
\begin{align}
\begin{array}{lll}
    & \text{Central flux (C-flux)}: & \alpha = \dfrac{1}{2}, \quad \beta = \tau = 0.\\
    & \text{Alternating flux (A-flux)}:& \alpha = 0 \,\, \text{or} \,\, 1, \quad \beta = \tau = 0.\\
    & \text{Sommerfeld flux (S-flux)}: & \alpha = \dfrac{1}{2}, \quad \beta = \dfrac{1}{2s}, \quad \tau = \dfrac{s}{2},\,\, s>0.
\end{array}
\end{align}

\begin{figure}[htbp]
    \centering
    \begin{tikzpicture}[scale = 1.2]
        \draw[dashed] (0, 0) grid (4, 4);
        \node at (1.5, 1.5) {$K_{i-1,j}$};
        \node at (2.5, 2.5) {$K_{i,j+1}$};
        \node at (1.7, 2.3) {$\mathbf{v}$};
        \node at (2.5, 1.5) {$K_{ij}$};
        \fill[red] (2, 2) circle (3pt);
    \end{tikzpicture}
    \caption{Illustration of the jump term in (\ref{jump_v}), where the red solid point represents a vertex $\mathbf{v}$ of $K_{ij}$, and the jumps on the faces $K_{ij}\cap K_{i-1,j}$ and $K_{ij}\cap K_{i,j+1}$ are used in the definition.}
    \label{fig:2D}
\end{figure}

\noindent
Following the idea in \cite{lu2021oscillation}, the damping coefficients $\sigma_{ij}^l$ and $\tilde{\sigma}_{ij}^l$ depend on the jumps at the vertices of $K_{ij}$. Let $[\![w]\!]|_{\mathbf{v}}$ denote the jump of $w$ on element $K_{ij}$ and its adjacent elements at vertex $\mathbf{v}$. 
As illustrated in Figure \ref{fig:2D}, at vertex $\mathbf{v}=(x_{i-1/2}, y_{j+1/2})$ in $K_{ij}$, the term $[\![w]\!]|_{\mathbf{v}}$  takes into account only jumps across faces that contain this vertex. More precisely, we define
\begin{equation}\label{jump_v}
    [\![w]\!]|_{\mathbf{v}}^2 = \left( w|_{K_{ij}}(\mathbf{v})-w|_{K_{i-1,j}}(\mathbf{v}) \right)^2 + \left( w|_{K_{ij}}(\mathbf{v})-w|_{K_{i,j+1}}(\mathbf{v}) \right)^2.
\end{equation}
Additionally, the coefficients of the damping term $\sigma_{ij}^l \geq 0, \tilde{\sigma}_{ij}^l \geq 0$ are taken as follows,
\begin{equation}\label{jump}
    \begin{aligned}
        \sigma_{ij}^l &= \dfrac{2(2l+1)}{(2p-1)}\dfrac{h_{ij}^l}{l!} \sum\limits_{|\boldsymbol{\alpha}|=l} \left( \dfrac{1}{4} \sum\limits_{\mathbf{v}\in K_{ij}} ([\![\partial^{\boldsymbol{\alpha}}u_h]\!]|_\mathbf{v})^2 \right)^{1/2},
        \quad l\geq 1, \\
        \tilde{\sigma}_{ij}^l & = \dfrac{2(2l+1)}{(2q-1)}\dfrac{h_{ij}^{l+1}}{(l+1)!} \sum\limits_{|\boldsymbol{\alpha}|=l} \left( \dfrac{1}{4} \sum\limits_{\mathbf{v}\in K_{ij}} ([\![\partial^{\boldsymbol{\alpha}}v_h]\!]|_\mathbf{v})^2 \right)^{1/2},
        \quad l\geq 0.
    \end{aligned}
\end{equation}
Here, the vector $\boldsymbol{\alpha} = (\alpha_1,\alpha_2)$
is the multi-index order with
$|\boldsymbol{\alpha}| = \alpha_1+\alpha_2,$
and $\partial^{\boldsymbol{\alpha}}w$ is defined as
\begin{equation*}
\partial^{\boldsymbol{\alpha}}w = \dfrac{\partial^{|\boldsymbol{\alpha}|}w}{\partial x^{\alpha_1} \partial y^{\alpha_2}}.
\end{equation*}
The operator $\mathbb{P}^l$ is the standard $L^2$ projection onto $V^l_h$, that for any function $w$ construct $\mathbb{P}^{l}w \in V^l_h$ such that
\begin{equation}
    \int_{K_{ij}}(\mathbb{P}^{l}w - w)\, \phi d\mathbf{x} = 0, 
    \quad \forall \, \phi(\mathbf{x})\in V^l_h.
\end{equation}
And we use the convention $\mathbb{P}^{-1} = \mathbb{P}^0$ as well. 



