\subsection{Stability analysis}
In this subsection, we establish a stability proof for the multi-dimension problems with general numerical fluxes. 

\begin{theorem}[Semi-discrete stability]
    Under the assumption of periodic boundary condition in each direction, for any positive integers $p$ and $q$, the semi-discrete DG scheme \eqref{eq:DG_2D} with the numerical fluxes \eqref{eq:flux_2D} satisfies 
    \begin{equation}
    \dfrac{d\mathbb{E}_h}{dt}\leq 0,
    \end{equation} 
    as long as the parameters $c$, $\tau$, and $\beta$ are not less than 0,
    and the semi-discrete energy $\mathbb{E}_h$ is defined as,
    \begin{equation}
        \mathbb{E}_h = \int_{\Omega} \left( \nabla u_h\cdot\nabla u_h + v_h^2 \right) d\mathbf{x}.
    \end{equation}
\end{theorem}

\begin{proof}
    Taking test function $(\phi^{(u)}(\mathbf{x}),\phi^{(v)}(\mathbf{x})) = (u_h,v_h)$ and summing over all $K_{ij}$, we  can obtain
    \begin{equation*}
        \begin{aligned}
             \dfrac{1}{2}\dfrac{d}{dt}& \int_{\Omega} \left( \nabla u_h\cdot\nabla u_h + v_h^2 \right) d\mathbf{x} \\
             =&
    \sum\limits_{K_{ij}\in\Gamma_h} \int_{K_{ij}} \left( \nabla(u_h)_t\cdot\nabla u_h + (v_h)_tv_h \right)d\mathbf{x}\\
     =& \sum\limits_{K_{ij}\in\Gamma_h} \int_{\partial K_{ij}}(\widehat{v} - v_h^-)(\nabla u_h^{-}\cdot\mathbf{n})dS +\sum\limits_{K_{ij}\in\Gamma_h} \int_{\partial K_{ij}}(\widehat{\nabla u}\cdot\mathbf{n})\, v_h^- dS\\
    &+\sum\limits_{K_{ij}\in\Gamma_h} \dfrac{c}{h^2} \int_{\partial K_{ij}}([\![u_h]\!]\cdot\mathbf{n}) u_h^- dS 
    -\sum\limits_{K_{ij}\in\Gamma_h}\sum\limits_{l=1}^p\dfrac{\sigma_{ij}^l}{h_{ij}} \int_{K_{ij}}(\nabla u_h - \mathbb{P}^{l-1}\nabla u_h)\cdot\nabla u_h d\mathbf{x} \\
    &-\sum\limits_{K_{ij}\in\Gamma_h}\sum\limits_{l=0}^q\dfrac{\tilde{\sigma}_{ij}^l}{h_{ij}} \int_{K_{ij}}(v_h - \mathbb{P}^{l-1}v_h)v_h d\mathbf{x}. 
        \end{aligned}
    \end{equation*}
    Plugging in the numerical fluxes and using the periodic boundary condition yields
    \begin{align*}
        \dfrac{1}{2}\dfrac{d}{dt}& \int_{\Omega} (\nabla u_h\cdot\nabla u_h + v_h^2) d\mathbf{x} \\
        = &    -\tau\sum_{e\in \Gamma_e} \int_{e}[\![\nabla u_h]\!]^2 dS
        -\beta\sum_{e}\int_{e\in \Gamma_e}\Vert[\![v_h]\!]\Vert^2 dS
        - \dfrac{c}{h^2}\sum_{e\in \Gamma_e} \int_e \Vert[\![u_h]\!]\Vert^2 dS\\ 
    &-\sum\limits_{K_{ij}\in\Gamma_h} \sum\limits_{l=0}^q \dfrac{\tilde{\sigma}_{ij}^l}{h_{ij}}\int_{K}(v_h - \mathbb{P}^{l-1}v_h)^2d\mathbf{x}\\
    &- \sum\limits_{K_{ij}\in\Gamma_h}\sum\limits_{l=1}^p 
 \dfrac{\sigma_{ij}^l}{h_{ij}} \int_{K_{ij}}(\nabla u_h - \mathbb{P}^{l-1}\nabla u_h)^T(\nabla u_h - \mathbb{P}^{l-1}\nabla u_h)d\mathbf{x},
        \end{align*}
        where $\Vert\cdot\Vert$ represents the $L_2$ norm.
    Utilizing the fact that these parameters $c\geq 0$, $\tau\geq 0$, $\beta \geq 0$, we obtain the desired energy estimate.
\end{proof}


\subsection{A prior error estimate }
\begin{theorem}[Error estimate]
    Assume the exact solutions $u\in H^{p+1}(\Omega)$ and $v\in H^{q+1}(\Omega)$
    with periodic boundary condition in each direction.     If $p-2\leq q\leq p$, then  
    \begin{equation}\label{eq:error_2D}
        \Vert\nabla(u-u_h)\Vert^2_{L^2(\Omega)} + \Vert v-v_h\Vert_{L^2(\Omega)}^2 \lesssim h^{2\gamma}\left( |u|^2_{H^{p+1}(\Omega)} +|v|^2_{H^{q+1}(\Omega)} \right),
    \end{equation}
    where $\gamma=\min(p', q')$, and
    \begin{equation}
    p' = 
    \begin{cases} 
    p-1, & \tau=0 , \\
    p-1/2, &\tau> 0,
    \end{cases} \qquad
    q' = 
    \begin{cases} 
    q, & \beta=0, \\
    q+1/2, &\beta> 0.
    \end{cases}
    \end{equation}
\end{theorem}


\begin{proof}
    We denote $V^{p,q}=V_h^p\times V_h^q$ to be the set of all functions $U_h = (u_h,v_h)$,  
$U = (u,v)$ is the exact solution, and $\Phi = (\phi^{(u)},\phi^{(v)})\in V^{p,q}$ is the test function. Similar to one dimensional case, we define
\begin{equation*}
\begin{aligned}
    D_{u}(u_h, \phi^{(u)}) = \sum_{K_{ij}\in\Gamma_h} D_{u,K_{ij}}(u_h, \phi^{(u)}), \quad 
    D_{u,K_{ij}}(u_h, \phi^{(u)}) = & \sum_{l=1}^{p} \frac{\sigma_{{ij}}^l}{h} \int_{K_{ij}} \left(\nabla u_h - \mathbb{P}^{l-1}\nabla u_h\right)\cdot\nabla\phi^{(u)} d\mathbf{x},\\
     D_{v}(v_h, \phi^{(v)}) = \sum_{K_{ij}\in\Gamma_h} D_{v,K_{ij}}(v_h, \phi^{(v)}), \quad 
     D_{v,K_{ij}}(v_h, \phi^{(v)}) = & \sum_{l=0}^{q} \frac{\tilde{\sigma}_{{ij}}^l}{h} \int_{K_{ij}} \left(v_h - \mathbb{P}^{l-1}v_h \right) \phi^{(v)} d\mathbf{x},\\
     P_{u}(u_h,\phi^{(u)}) = \sum_{K_{ij}\in\Gamma_h} P_{u,K_{ij}}(u_h,\phi^{(u)}), \quad 
     P_{u,K_{ij}}(u_h,\phi^{(u)})=&- \dfrac{c}{h^2}\int_{\partial K_{ij}}([\![u_h]\!]\cdot\mathbf{n}) \phi^{(v),-}(\mathbf{x})dS.
\end{aligned}
\end{equation*}
We also define the error between exact and numerical solution
\begin{align*}
    e_u = u-u_h,\quad e_v=v-v_h,\quad D_h =(e_u,e_v),
\end{align*}
and split the error into $e_u=\tilde{e}_u-\delta_u$  and $e_v=\tilde{e}_v-\delta_v$ with  
\begin{equation*}
\begin{aligned}
    & \tilde{e}_u=\tilde{u}_h-u_h,\quad \tilde{e}_v=\tilde{v}_h-v_h,\quad \tilde{D}_h=(\tilde{e}_u,\tilde{e}_v)\in V^{p,q},\\
    & \delta_u=\tilde{u}_h-u,\quad\,\,\, \delta_v = \tilde{v}_h-v,\quad\,\,\, \Delta_h = (\delta_u,\delta_v),
\end{aligned}
\end{equation*}
where $\tilde{v}_h=\mathbb{P}^q v \in V_h^q$ is the $L^2$ projection of $v$, 
and $\tilde{u}_h\in V^p_h$ is obtained via a Ritz-type projection in multi-dimensions 
\begin{equation*}
\begin{cases}
    \displaystyle\int_{K_{ij}} \nabla(u-\tilde{u}_h)\cdot\nabla\phi^{(u)}d\mathbf{x} = 0 , \quad \forall \,\phi^{(u)}\in V^{p}_h,\\
    \displaystyle\int_{K_{ij}} (u - \tilde{u}_h)d\mathbf{x} = 0.
\end{cases}
\end{equation*}
The properties \eqref{eq:prop_add1}-\eqref{eq:inverse} also hold in 2D. 



Moreover, choosing $\Phi = \tilde{D}_h$ and summing up over $K\in\Gamma_h$, we  obtain 
\begin{equation*}\label{Eh_2D}
\begin{aligned}
    \dfrac{1}{2} \dfrac{d}{dt} & \sum_j\int_{K_{ij}} \left( \nabla\tilde{e}_u\cdot\nabla\tilde{e}_u + \tilde{e}_v^2 \right) d\mathbf{x}\\
    =& -\sum_{e\in\Gamma_e}\int_{e} \left( [\![\nabla\tilde{e}_u]\!] \, \widehat{\delta_v} + [\![\tilde{e}_v]\!]\cdot\widehat{\nabla\delta_u} +  \beta [\![\tilde{e}_v]\!]^2+\tau [\![\nabla\tilde{e}_u]\!]^2 
     \right) dS\\
    &+D_u(u_h,\tilde{e}_u) +D_v(v_h,\tilde{e}_v) +P_u(u_h,\tilde{e}_u).
\end{aligned}
\end{equation*}


Similar to the 1D error estimate, the first term on the right-hand side  can also be estimated using the properties \eqref{eq:prop_add1}-\eqref{eq:inverse}. Consequently, we have



\begin{equation}\label{eq:case_2D}
    \begin{aligned}
        -\sum_{e\in\Gamma_e}\int_{e} & \left( [\![\nabla\tilde{e}_u]\!] \, \widehat{\delta_v} + [\![\tilde{e}_v]\!]\cdot\widehat{\nabla\delta_u} +  \beta [\![\tilde{e}_v]\!]^2+\tau [\![\nabla\tilde{e}_u]\!]^2 
     \right) dS \\
     & \lesssim \left(\Vert\nabla\tilde{e}_u\Vert^2_{L^2(\Omega)} + \Vert\tilde{e}_v\Vert^2_{L^2(\Omega)}\right) + h^{2p^\prime}|u|^2_{H^{p+1}(\Omega)} + h^{2q^\prime}|v|^2_{H^{q+1}(\Omega)},
    \end{aligned}
\end{equation}
where $p', q'$ are given as
    \begin{equation*}
    p' = 
    \begin{cases} 
    p-1, & \tau=0 , \\
    p-1/2, &\tau> 0,
    \end{cases} \qquad
    q' = 
    \begin{cases} 
    q, & \beta=0, \\
    q+1/2, &\beta> 0.
    \end{cases}
    \end{equation*}

With the definition of $\sigma_{ij}^l$, by inverse inequality \eqref{eq:inverse} and the approximation properties of projection, we have
\begin{equation*}
    \begin{aligned}
        \sum_{K_{ij}\in\Gamma_h}(\sigma_{ij}^l)^2 =& \sum_{K_{ij}\in\Gamma_h}\dfrac{4(2l+1)^2}{(2p-1)^2} \dfrac{h_{ij}^{2l}}{(l!)^2} \sum_{|\boldsymbol{\alpha}| = l}\left(\dfrac{1}{4}\sum\limits_{\mathbf{v}\in K_{ij}}([\![\partial^{\boldsymbol{\alpha}}u_h-\partial^{\boldsymbol{\alpha}}u]\!]|_{v})^2 \right)\\
        \lesssim& \sum_{K_{ij}\in\Gamma_h} \sum_{|\boldsymbol{\alpha}|=l} h_{ij}^{2l} \sum\limits_{\mathbf{v}\in K_{ij}} \left([\![\partial^{\boldsymbol{\alpha}}\tilde{e}_u]\!]^2|_{\mathbf{v}} + [\![\partial^{\boldsymbol{\alpha}}\delta_u]\!]^2|_{\mathbf{v}}\right)\\
         \lesssim& \Vert\nabla\tilde{e}_u\Vert_{L^2(\Omega)}^2 + h^{2p}|u|^2_{H^{p+1}(\Omega)}.
    \end{aligned}
\end{equation*}
On the other hand, 
\begin{equation*}
    \begin{aligned}
        &\Vert\nabla\tilde{u}_h-\mathbb{P}^{l-1}\nabla\tilde{u}_h\Vert_{L^2(K_{ij})}\\
        &\leq\Vert\nabla(\tilde{u}_h-u)\Vert_{L^2(K_{ij})}+\Vert (\nabla u-\mathbb{P}^{l-1}\nabla u)\Vert_{L^2(K_{ij})}+\Vert\mathbb{P}^{l-1}\nabla(u-\tilde{u}_h)\Vert_{L^2(K_{ij})}\\
        &\lesssim h_{ij}^p|u|_{H^{p+1}(K_{ij})} + h_{ij}^{\max(1,l)}|\nabla u|_{H^{\max(1,l)}(K_{ij})} + h_{ij}^p|u|_{H^{p+1}(K_{ij})}\\
        &\lesssim h_{ij}^{\max(1,l)}|u|_{H^{\max(1,l)+1}(K_{ij})}\\
        &\lesssim h_{ij}^{\max(1,l)}\left(\sum_{|\boldsymbol{\alpha}| = \max(1,l)+ 1} \int_{K_{ij}} |\partial^{\boldsymbol{\alpha}}u|^2dxdy\right)^{1/2}\\
        &\lesssim h_{ij}^{\max(1,l)+1}\sum_{|\boldsymbol{\alpha}| = \max(1,l)+ 1}|\partial^{\boldsymbol{\alpha}}u|_{\infty}\\
        &{\lesssim h^{\max(1,l)+1}}, \qquad l=0,1,\ldots,p.
    \end{aligned}
\end{equation*}
Hence, we obtain
\begin{equation}\label{Damping_u_error_2D}
    \begin{aligned}
        D_u(u_h,\tilde{e}_u)
        =&-\sum_{K_{ij}\in\Gamma_h}\sum_{l=1}^p\dfrac{\sigma_{ij}^l}{h_{ij}}\int_{K_{ij}}\left((\nabla\tilde{e}_u-\mathbb{P}^{l-1}\nabla\tilde{e}_u)^2 + (\nabla\tilde{u}_h-\mathbb{P}^{l-1}\nabla\tilde{u}_h)\nabla\tilde{e}_u \right)d\Omega\\
        \leq &\sum_{K_{ij}\in\Gamma_h}\sum_{l=1}^p\dfrac{\sigma_{ij}^l}{h_{ij}}\Vert\nabla\tilde{u}_h-\mathbb{P}^{l-1}\nabla\tilde{u}_h\Vert_{L^2(K_{ij})}\Vert\nabla\tilde{e}_u\Vert_{L^2(K_{ij})}\\
        \lesssim& \sum_{K_{ij}\in\Gamma_h}\sum_{l=1}^p\dfrac{(\sigma_{ij}^l)^2}{h_{ij}^2}\Vert\nabla\tilde{u}_h-\mathbb{P}^{l-1}\nabla\tilde{u}_h\Vert_{L^2(K_{ij})}^2 +\Vert\nabla\tilde{e}_u\Vert^2_{L^2(\Omega)}\\
        \lesssim& \sum_{K_{ij}\in\Gamma_h}\sum_{l=1}^p\dfrac{(\sigma_{{ij}}^l)^2}{h_{ij}^2}h^{2\max(1,l) + 2} + \Vert\nabla\tilde{e}_u\Vert^2_{L^2(\Omega)}\\
        \lesssim& \Vert\nabla\tilde{e}_u\Vert^2_{L^2(\Omega)} + h^{2p+2}|u|^2_{H^{p+1}(\Omega)}.
    \end{aligned}
\end{equation}
For the term $D_v(v_h,\tilde{e}_v)$,
 we have,
\begin{equation}\label{Damping_v_error_2D}
    \begin{aligned}
        D_v(v_h,\tilde{e}_v)\leq &\sum_{K_{ij}\in\Gamma_h}\sum_{l=1}^q \dfrac{\tilde{\sigma}_{{ij}}^l}{h_{ij}} \Vert\tilde{v}_h-\mathbb{P}^{l-1}\tilde{v}_h\Vert_{L^2(K_{ij})} \Vert\tilde{e}_v\Vert_{L^2(K_{ij})}\\
        \lesssim&{\Vert\tilde{e}_v\Vert^2+h^{2q+2}|v|^2_{H^{q+1}(\Omega)}}.
    \end{aligned}
\end{equation}
Finally, we consider the term $P_u(u_h,\tilde{e}_u)$,
\begin{equation}\label{Penalty_u_2D}
    \begin{aligned}
        P_{u}(u_h,\tilde{e}_u)
        =&-\sum_{K_{ij}\in\Gamma_h} \dfrac{c}{h^2} \int_{\partial K_{ij}} ([\![u_h]\!] \cdot\mathbf{n}^-)\tilde{e}^-_udS\\
        = &-\dfrac{c}{h^2} \sum_{e\in\Gamma_e}\int_{e} \left([\![u_h - u]\!] \cdot [\![\tilde{e}_u]\!]\right)dS\\
        =& \dfrac{c}{h^2} \sum_{e\in\Gamma_e}\int_{e} \left(-\Vert[\![\tilde{e}_u ]\!]\Vert^2 + [\![\delta_u]\!] \cdot [\![\tilde{e}_u]\!]\right) dS \\
        \lesssim& \dfrac{c}{h^2} \sum_{e\in\Gamma_e} \int_{e} \left(-\Vert[\![\tilde{e}_u ]\!]\Vert^2 + \dfrac{1}{4}\Vert[\![\delta_u]\!]\Vert^2 +  \Vert[\![\tilde{e}_u ]\!]\Vert^2  \right) dS \\
        \lesssim& \dfrac{c}{h^2}\sum_{e\in\Gamma_e}\int_{e} \Vert[\![\delta_u]\!]\Vert^2  dS \\
        \lesssim& h^{2p-1}|u|^2_{H^{p+1}(\Omega)}.
    \end{aligned}
\end{equation}
Therefore, by combining inequalities \eqref{eq:case_2D}-\eqref{Penalty_u_2D}, we  obtain 
\begin{equation*}
    \begin{aligned}
    \dfrac{d}{dt} \int_{\Omega}\left( \nabla\tilde{e}_u\cdot\nabla\tilde{e}_u + (\tilde{e}_v)^2 \right) d\mathbf{x}
    \lesssim &\int_{\Omega}\left( \nabla\tilde{e}_u\cdot\nabla\tilde{e}_u + (\tilde{e}_v)^2 \right) d\mathbf{x} + h^{2\gamma} \left( |u|^2_{H^{p+1}(\Omega)} + |v|^2_{H^{q+1}(\Omega)} \right),
    \end{aligned}
\end{equation*}
where $\gamma=\min(p', q')$. Then, using Gronwall's inequality yields 
\begin{equation*}
    \int_{\Omega}\left( \nabla\tilde{e}_u\cdot\nabla\tilde{e}_u + (\tilde{e}_v)^2 \right) d\mathbf{x}
    \lesssim h^{2\gamma} \left( |u|^2_{H^{p+1}(\Omega)} + |v|^2_{H^{q+1}(\Omega)} \right).
\end{equation*}
We complete the proof by using the triangle inequality.
\end{proof}




