\section{Preliminaries}
\label{sec:preliminaries}

%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Notation}
\label{subsec:notation}
%
Bold letters $\bm{x}=(x_1,\dots,x_{\ddim})^T$ refer to column vectors.
Let $\bm{1}_\ddim$ be the $\ddim$-dimensional all-ones vector and $I_\ddim$ be the $\ddim\times\ddim$ identity matrix.
%The determinant of the $d\times d$ matrix $Q$ is $|Q|$.
Let $\bm{x}\circ\bm{y}$ be the Hadamard (entry-by-entry) product of $\bm{x}$ and $\bm{y}$. Define the vector modulo operator
\begin{align}
    \bm{x}\ \textrm{mod}\ \bm{A} = \bm{x} - \bm{k} \circ\bm{A} 
\end{align}
where $\bm{A}$ has positive entries and $k_i$ is the unique integer for which $x_i-k_i A_i \in [-A_i/2,A_i/2)$ for $i=1,\dots,\ddim$.

Upper- and lowercase letters usually refer to random variables (RVs) and their realizations, e.g., $X$ is an RV, and $x$ is its realization. $P_X$ and $p_X$ are a probability mass function and density, respectively. We remove subscripts if the argument is the lowercase of the RV, e.g., $p(x)=p_X(x)$.
$\E{\bm{X}}$ and the random vector $\E{\bm{X}|\bm{Y}}$ are the expectations of $\bm{X}$ without and with conditioning on $\bm{Y}$, respectively. The corresponding covariance matrices are
\begin{align}
    Q_{\bm{X}} & = \E{(\bm{X}-\E{\bm{X}})(\bm{X}-\E{\bm{X}})^T} 
    \label{eq:cov-matrix} \\
    Q_{\bm{X}|\bm{Y}}
    & = \E{(\bm{X}-\E{\bm{X}|\bm{Y}})(\bm{X}-\E{\bm{X}|\bm{Y}})^T} .
    \label{eq:cond-cov-matrix}
\end{align}
For scalars, we write 
\eqref{eq:cov-matrix} and \eqref{eq:cond-cov-matrix} as $\sigma_x^2$ and  $\sigma_{x|y}^2$.
The notation $h(\bm{X})$, $I(\bm{X};\bm{Y})$, $I(\bm{X};\bm{Y}|\bm{Z})$ refers to the differential entropy of $\bm{X}$ and the mutual information of $\bm{X}$ and $\bm{Y}$ without and with conditioning on $\bm{Z}$, respectively. We write $\Eq{f(X)}:=\int_{\mathbb R} q(x) f(x)\, dx$ and $h_q(X):=\Eq{-\log q(X)}$.

%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Gaussian Vectors}
\label{subsec:Gaussian-vectors}
%
We study jointly Gaussian $\bm{X},\bm{Y}$, perhaps with different dimensions, and with zero mean and joint covariance matrix $Q_{\bm{X},\bm{Y}}$. The conditional mean of $\bm{X}$ given $\bm{Y}$ is
\begin{align}
    \E{\bm{X}|\bm{Y}}
    & = \E{\bm{X}\bm{Y}^T} Q_{\bm{Y}}^{-1} \bm{Y}
    \label{eq:EXgY}
\end{align}
assuming $Q_{\bm{Y}}$ is invertible. One may write
\begin{align}
    \bm{X} = \E{\bm{X}|\bm{Y}} + \bm{Z}
    \label{eq:vec-Y-to-X-model}
\end{align}
where $\bm{Z}$ is independent of $\bm{Y}$ and
\begin{align}
    Q_{\bm{Z}} = Q_{\bm{X}|\bm{Y}}
    = Q_{\bm{X}} - \E{\bm{X}\bm{Y}^T} Q_{\bm{Y}}^{-1} \E{\bm{Y}\bm{X}^T} .
    \label{eq:QXgY}
\end{align}
Alternatively, we have
\begin{align}
    \bm{Y} = \E{\bm{Y}|\bm{X}} + {\bf \hat{Z}}
    \label{eq:vec-X-to-Y-model}
\end{align}
where ${\bf \hat{Z}}$ is independent of $\bm{X}$ and (see~\eqref{eq:QXgY})
\begin{align}
%    \E{\bm{Y}|\bm{X}}
%    & = \E{\bm{Y}\bm{X}^T} Q_{\bm{X}}^{-1} \bm{X}
%    \label{eq:EYgX} \\
    Q_{{\bf \hat{Z}}}
    & = Q_{\bm{Y}|\bm{X}}
    = Q_{\bm{Y}} - \E{\bm{Y}\bm{X}^T} Q_{\bm{X}}^{-1} \E{\bm{X}\bm{Y}^T}
    \label{eq:QYgX}
\end{align}
assuming $Q_{\bm{X}}$ is invertible.

%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Rate-Distortion Theory}
\label{subsec:RD=theory}
%
Consider a source that outputs a string $X^n=X_1,\dots,X_n$ of independent and identically distributed (i.i.d.) symbols. The lossy source coding problem has a non-negative real-valued distortion function $d(.)$, an encoder mapping $X^n$ to $nR$ bits $W$, where $R$ is the rate, and a decoder mapping $W$ to a reconstruction $\hat X^n=\hat X_1,\dots,\hat X_n$. The goal is to design the encoder and decoder so the (random) empirical distortion
\begin{align}
    \Delta := \frac{1}{n} \sum\nolimits_{i=1}^n d(X_i,\hat{X}_i)
\end{align}
satisfies $\E{\Delta}\le\mathcal D$. We also study $\Prob{\Delta>\mathcal D}$, i.e., the probability of excess distortion for a specified $\mathcal D$.

The RD function is the infimum of $R$ as a function of $\mathcal D$. Shannon~\cite{Shannon-48,Shannon-59} showed that this function is
\begin{align}
    R(\mathcal D) = \min_{\E{d(X,\hat{X})}\le \mathcal D} I(X;\hat X).
\end{align}
For example, if $X$ is Gaussian and $d(x,\hat x) = (x-\hat x)^2$, then
\begin{align}
    R(\mathcal D) = \left\{ 
    \begin{array}{ll}
    \frac{1}{2}\log(\sigma_x^2\, \big/ \mathcal{D}), & 0< \mathcal{D} < \sigma_x^2 \\
    0, & \mathcal{D} \ge \sigma_x^2 .
    \end{array} \right.
\end{align}
For $0<\mathcal{D}<\sigma_x^2$, the optimal ``reverse'' channel is
\begin{align}
    X = \hat X + Z
    \label{eq:reverse-channel}
\end{align}
where $\hat X$ and $Z$ are independent and Gaussian with variances $\sigma_x^2-\mathcal{D}$ and $\mathcal{D}$, respectively. Applying \eqref{eq:vec-X-to-Y-model}-\eqref{eq:QYgX}, we have
\begin{align}
    \hat X = \left\{ 
    \begin{array}{ll}
    (1-\mathcal{D}/\sigma_x^2) X + \hat Z, & 0< \mathcal{D} < \sigma_x^2 \\
    0, & \mathcal{D} \ge \sigma_x^2
    \end{array} \right.
    \label{eq:forward-channel}
\end{align}
where $\hat Z$ is independent of $X$ and $\sigma_{\hat z}^2=(1-\mathcal{D}/\sigma_x^2) \mathcal{D}$.

%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Conditional Rate-Distortion Theory}
\label{subsec:conditional-RD=theory}
%
Suppose the encoder and decoder have the side information $Y^n=Y_1,\dots,Y_n$ of i.i.d. symbols, i.e., the pairs $(X_i,Y_i)$ are i.i.d. for $i=1,\dots,n$. The conditional RD function is
\begin{align}
    R_{X|Y}(\mathcal D) = \min_{\E{d(X,\hat{X})}\le \mathcal D} I(X ; \hat X | Y).
    \label{eq:cond-RD-function}
\end{align}
For example, if $X,Y$ are jointly Gaussian and the distortion function is $d(x,\hat x)=(x-\hat x)^2$, then
\begin{align}
    R_{X|Y}(\mathcal D) = \left\{ 
    \begin{array}{ll}
    \frac{1}{2}\log(\sigma_{x|y}^2\, \big/ \mathcal D),
    & 0< \mathcal D < \sigma_{x|y}^2 \\
    0, & \mathcal D \ge \sigma_{x|y}^2 \;.
    \end{array} \right. 
\end{align}

More generally, suppose $\bm{X}$ and $\bm{Y}$ are jointly Gaussian and $d(\bm{x},\hat{\bm{x}})=\|\bm{x}-\hat{\bm{x}}\|^2$. Let $Q_{\bm{X}|\bm{Y}}=V \Lambda V^T$ be the eigenvalue decomposition of $Q_{\bm{X}|\bm{Y}}$, where $V$ is an orthogonal matrix and $\Lambda$ is non-negative with diagonal entries $\lambda_i$, $i=1,\dots,\ddim$, where $\ddim$ is the dimension of $\bm{X}$. Then, if $\mathcal D \ge \sum_{i=1}^\ddim \lambda_i$, we have $R_{\bm{X}|\bm{Y}}(\mathcal D)=0$. Otherwise, we have (see \cite[Ch.~10.3.3]{Cover06})
\begin{align}
    R_{\bm{X}|\bm{Y}}(\mathcal D) = 
    \sum\nolimits_{i: \lambda < \lambda_i} \frac{1}{2}\log(\lambda_i\, \big/ \lambda)
\end{align}
where the reverse-waterfilling level $\lambda>0$ is chosen so
\begin{align}
    \mathcal D = \sum\nolimits_{i=1}^\ddim \min(\lambda_i,\lambda).
\end{align}
The idea is that $i$-th encoder quantizes the $i$-th entry of 
\begin{align}
  \bm{X}_V=V^T (\bm{X} - \E{\bm{X}|\bm{Y}})
  \label{eq:XV}
\end{align}
of variance $\lambda_i$; observe that
\begin{align}
    Q_{\bm{X}_V} = V^T Q_{\bm{X}|\bm{Y}} V =\Lambda
    \label{eq:QXV}
\end{align}
so the entries of $\bm{X}_V$ are uncorrelated, and hence independent. If $\lambda_i$ is large, one transmits information about $X_{V,i}$; if $\lambda_i$ is small, one transmits no information. Reverse waterfilling states that the boundary between ``large'' and ``small'' is $\lambda$, and the best descriptions have distortion $\lambda$ if $\lambda<\lambda_i$. The reconstructions are as in \eqref{eq:forward-channel}, namely
\begin{align}
    \hat{X}_{V,i} = \left\{ 
    \begin{array}{ll}
    (1-\lambda/\lambda_i) X_{V,i} + \hat{Z}_i, & 0< \lambda < \lambda_i \\
    0, & \lambda \ge \lambda_i
    \end{array} \right.
    \label{eq:forward-channel-i}
\end{align}
where the $\hat{Z}_i$, $i=1,\dots,\ddim$, and $\bm{X}_V$ are mutually independent and
$\sigma_{\hat{z}_i}^2=(1-\lambda/\lambda_i) \lambda$. The output is $\hat{\bm{X}}=V \hat{\bm{X}}_V + \E{\bm{X}|\bm{Y}}$.

%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Wyner-Ziv Rates}
\label{subsec:WZ-rates}
%
The WZ extension of RD theory assumes the decoder, but not the encoder, has access to $\bm{Y}$. The RD function is now
\begin{align}
    R_{\text{WZ}}(\mathcal D) = \min_{\E{d(\bm{X},\hat{\bm{X}})}\le \mathcal D} \left( I(\bm{U};\bm{X}) - I(\bm{U};\bm{Y}) \right )
    \label{eq:WZ-RD-function}
\end{align}
where the minimization is over all $\bm{U}$ such that $\bm{U}\leftrightarrow \bm{X}\leftrightarrow \bm{Y}$ forms a Markov chain, and all functions $f(\cdot)$ such that $\hat{\bm{X}} = f(\bm{U},\bm{Y})$. The Markov chain relation gives
\begin{align}
    I(\bm{U};\bm{X}) - I(\bm{U};\bm{Y})
    = I(\bm{U} ; \bm{X} | \bm{Y}).
    \label{eq:R-diff-cond}
\end{align}

Remarkably, $R_{\text{WZ}}(\mathcal D)=R_{\bm{X}|\bm{Y}}(\mathcal D)$ if $\bm{X},\bm{Y}$ are jointly Gaussian and $d(\bm{x},\hat{\bm{x}})=\|\bm{x}-\hat{\bm{x}}\|^2$, i.e., the RD function is the same as if the encoder also has $\bm{Y}$. For example, consider the scalar problem and choose $U=X+\check{Z}$ where $\check{Z}$ is independent of $(X,Y)$. The best estimate of $X$ is
\begin{align}
    \hat{X} = \E{X|U,Y}
    = \frac{\sigma_{x|y}^2\, U + \sigma_{\check{z}}^2\, \E{X|Y}}{\sigma_{x|y}^2+\sigma_{\check{z}}^2}.
    \label{eq:WZ-estimate}
\end{align}
If $0<\mathcal{D}< \sigma_{x|y}^2$, choose the description noise variance as
\begin{align}
    \sigma_{\check{z}}^2
    = \frac{\sigma_{x|y}^2 \mathcal D}{\sigma_{x|y}^2 - \mathcal D} 
    \implies
    \mathcal{D} = \frac{\sigma_{x|y}^2 \sigma_{\check{z}}^2}{\sigma_{x|y}^2 + \sigma_{\check{z}}^2}
    \label{eq:WZ-variances}
\end{align}
This choice gives $\E{(X-\hat{X})^2}=\mathcal{D}$ and
\begin{align}
    I(U;X) - I(U;Y)
    %& = \frac{1}{2} \log \frac{\sigma_x^2+\sigma_{\check{z}}^2}{\sigma_{\check{z}}^2} - \frac{1}{2}\log \frac{\sigma_x^2+\sigma_{\check{z}}^2}{\sigma_{x|y}^2+\sigma_{\check{z}}^2} \nonumber \\
    %& = h(U|Y) - h(U|X) \nonumber \\
    & = \frac{1}{2}\log(\sigma_{x|y}^2\, \big/ \mathcal D).
    \label{eq:WZ-rate-scalar}
\end{align}

