\section{Scalar Models and Quantization}
\label{sec:scalar-models}
%

\begin{figure}[!t]
\centering
\input{system_model}
\caption{WZ coding with a modulo operator and dithering.}
\label{fig:DPC-lattice}
\end{figure}

Consider $X=Y+Z$ where $Z$ is Gaussian and independent of $Y$, i.e., we have $\sigma_{x|y}^2=\sigma_z^2$. Fig.~\ref{fig:DPC-lattice} shows the WZ coding structure of \cite[Sec.~IV.A]{zamir2002nested} but with scalar operations. The encoder and decoder share a dither $D$ statistically independent of $(X,Z)$ and uniformly distributed in $[-A/2, A/2)$. The inflation factor is $\alpha=\sqrt{1-\sigma_d^2/\sigma_z^2}$, where $\sigma_d^2$ is a target distortion; cf. \cite[p.~1260]{zamir2002nested}.

%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Model in a Finite Interval}
\label{subsec:derived-model}
%
We derive a model for the interval $[-A/2,A/2)$ by modifying steps in \cite{zamir2002nested,Sener-CL21,Sener-CL24,Sener-ISIT24}. The derived source is
\begin{align}
    (X',Y')^T = \left( \alpha\, (X,Y)^T + D\cdot\bm{1}_2 \right)\ \textrm{mod}\ A\cdot\bm{1}_2 .
    \label{eq:derived-source}
\end{align}
The dither makes $X'$ uniform over $[-A/2, A/2)$ and independent of $X$, and similarly for $Y'$ and $Y$. The source $X'$ is quantized via $U$ with discrete alphabet $\mathcal{U}$. Using standard theory, the decoder can recover $U$ if the rate satisfies
\begin{align}
    R = I(U;X') - I(U;Y')
    \label{eq:WZ-rate}
\end{align}
where $U\leftrightarrow X'\leftrightarrow Y'$ forms a Markov chain; see \eqref{eq:WZ-RD-function}.

Let $\sigma_d^2$ be a distortion parameter satisfying $0 < \sigma_d^2 < \sigma_z^2$.
Define the encoder and decoder noise
\begin{align}
    \tilde{Z} & = (U - X')\ \textrm{mod}\ A
    \label{eq:Ztilde} \\
    Z' & = (U - Y')\ \textrm{mod}\ A
    = \big( \tilde Z  + \alpha Z \big)\ \textrm{mod}\ A
   \label{eq:Zprime}
\end{align}
where $U$ is selected based on $X'$ only; see Sec.~\ref{subsec:lattices-and-shaping} below. Thus, $U\leftrightarrow X'\leftrightarrow Y'$ forms a Markov chain, as required.

The decoder puts out the reconstruction
\begin{align}
    \hat{X} = Y + \alpha Z'
    \label{eq:reconstruction}
\end{align}
Observe that $\hat{X} = \E{X|Y,Z'}$ if $Z'=\tilde Z + \alpha Z$ is Gaussian and $\tilde Z$ is independent of $(Y,Z)$ and has variance $\sigma_d^2$. Also, $\hat X$ is a function of $U$ and $Y$, as required.

%-------------------------------
\subsection{Scalar Lattices and Probabilistic Shaping} 
\label{subsec:lattices-and-shaping}

Consider the equally spaced scalar quantizer with alphabet
\begin{equation}
 \mathcal{U} = \big\{-A/2 + (2k+1)\kappa\ \big\}_{k=0}^{M-1}
 \label{eq:constellation}
\end{equation}
where $A\ge0$ and $\kappa = A/(2M)$.
We call this alphabet $M$-ASK to match \cite{Sener-CL21,Sener-CL24,Sener-ISIT24}.
%Observe that $\mathcal{U}$ is a subset of the scalar lattice $\mathbb{Z} \cdot A/M$ if $M$ is odd and $(2\mathbb{Z}+1) \cdot A/(2M)$ if $M$ is even.
%
Let $q(\tilde z)$ be a density on $\tilde{z} \in [-A/2,A/2)$ and apply the probabilistic shaping
\begin{equation}
    P(u|x') = \frac{q\big((u-x')\ \text{mod}\ A\big)}{\sum_{v\in\mathcal U} q\big((v-x')\ \text{mod}\ A\big)}, \quad u \in \mathcal U .
\label{eq:q_shaping}
\end{equation}
Observe that $X'$, $\tilde Z$ play the roles of $S'$, $X$ in \cite{Sener-CL24}, e.g.,
the continuously uniform $X'$ induces a discrete uniform $U$. To see this, define $\tilde{x}=(u-x')\ \textrm{mod}\ A$ and
\begin{align}
    d(x) = 2 \kappa \sum\nolimits_{k=0}^{M-1} q((x + 2 k \kappa)\ \text{mod}\ A).
\end{align}
We then have
\begin{align}
    P(u)
    = \int_{-A/2}^{A/2} \frac{1}{A}\, P(u|x')\, dx'
    = \int_{-A/2}^{A/2} \frac{1}{M}\, \frac{q(\tilde x)}{d(\tilde x)} \, d\tilde x
    \label{eq:Pu}
\end{align}
and $P(u)=1/M$ for all $u$ since \eqref{eq:Pu} does not depend on $u$.

We claim $U,\tilde{Z},Z$ are mutually statistically independent and
\begin{align}
    p(\tilde z) = q(\tilde z)/d(\tilde z),
    \;\; \tilde z \in [-A/2,A/2).
    \label{eq:pz}
\end{align}
To see this, let $x'=(u-\tilde z)\ \textrm{mod}\ A$. We have
\begin{align}
    p(\tilde z,z|u)
    & = p(x',z|u) \nonumber \\
    %& \overset{(a)}{=} p(x'|u)\, p(z) \nonumber \\
    & \overset{(a)}{=} \left( p(x') P(u|x') / P(u) \right) \, p(z) \nonumber \\
    & \overset{(b)}{=} \frac{q(\tilde z)}{d(\tilde z)}\, p(z)
\end{align}
where step $(a)$ follows because $(X',U)$ and $Z$ are independent, and step $(b)$ follows by $p(x')=1/A$ and $P(u)=1/M$.

%-------------------------------
\subsection{Truncated Gaussian Shaping} 
%
We use truncated Gaussian shaping with (see~\cite[eq.~(12)]{Sener-CL24})
\begin{equation}
q(\tilde{z}) = \frac{e^{-\tilde{z}^2 / (2\sigma_d^2)}}{c \cdot \sqrt{2\pi\sigma_d^2}}, \quad \tilde{z} \in [-A/2,A/2)
\label{eq:TG-shaping}
\end{equation}
where $c=1-2Q(A/(2\sigma_d))$. We compute (see~\cite[eq.~(16)]{Sener-CL24})
\begin{align}
    P_{q,\tilde Z} := \Eq{\tilde{Z}^2}
    = \sigma_d^2 \left[ 1 - \frac{A e^{-A^2/(8\sigma_d^2)}}{c \sqrt{2 \pi \sigma_d^2}} \right]
    \label{eq:Ztilde-variance}
\end{align}
and (see~\cite[eq.~(17)]{Sener-CL24})
\begin{align}
    h_q(\tilde Z )
    = \frac{1}{2} \log\left(2 \pi e \sigma_d^2 c^2 \right) - \frac{1}{2} \left( 1 - \frac{P_{q,\tilde Z}}{\sigma_d^2} \right).
    \label{eq:Ztilde-entropy}
\end{align}
Since $q(.)$ is symmetric unimodal, by
\cite[eq.~(20)]{Sener-ISIT24} we have
$d_\textrm{min} \le d(x) \le d_\textrm{max}$ where 
\begin{align}
    d_\textrm{min} = 1 - \frac{A}{M} q(0), \quad 
    d_\textrm{max} = 1 + \frac{A}{M} q(0).
\label{eq:D-extrema}
\end{align}

%-------------------------------
\subsection{Distortion} 
\label{subsec:distortion-scalar}
%
To bound the distortion, consider
 \begin{align}
    X - \hat{X}
    & = Z - \alpha Z'. %\nonumber \\
    %& = Z - \alpha \left( (\tilde Z  + \alpha Z)\ \textrm{mod}\ A \right)
\end{align}
The modulo operator cannot increase the second moment, so
\begin{align}
    \E{(Z')^2}
    & \le \E{\big({\tilde Z} + \alpha Z\big)^2}  \nonumber \\
    & \overset{(a)}{\le} \frac{1}{d_\textrm{min}} \Eq{{\tilde Z}^2}
    + \alpha^2 \sigma_z^2 \nonumber \\
    & = \sigma_z^2 + \big(P_{q,\tilde Z} \big/ d_\textrm{min} - \sigma_d^2 \big)
    \label{eq:Zprime-variance-bound2}
\end{align}
where step $(a)$ follows by $p(\tilde z)\le q(\tilde z)/d_\textrm{min}$ if $M$ is sufficiently large so $d_\textrm{min}>0$; see \eqref{eq:pz} and \eqref{eq:D-extrema}. We further have
\begin{align}
    \E{ Z Z'}
    & = \E{ Z \big( \tilde Z + \alpha Z - I A \big)} \nonumber \\
    & = \alpha\, \sigma_z^2 - A\, \E{I Z}
    \label{eq:cross-correlation}
\end{align}
where we used the independence of $Z$ and $\tilde Z$, and $I$ is the RV taking on the modulo shift values $i$. We thus have
\begin{align}
    & \E{\big(X - \hat X\big)^2}
    = \sigma_z^2
    - 2 \alpha\, \E{Z Z'}
    + \alpha^2\,\E{(Z')^2} \nonumber \\
    & \overset{(a)}{\le}
    %\left(1-\alpha^2\right) \sigma_z^2
    %+ 2 \alpha A \, \E{iZ} 
    %+ \alpha^2 \left(P_{q,\tilde Z} \big/ d_\textrm{min} - %\sigma_d^2 \right)
    %\nonumber \\ & =
    \sigma_d^2
    + 2 \alpha A \, \E{I Z}
    + \alpha^2 \big(P_{q,\tilde Z} \big/ d_\textrm{min} - \sigma_d^2 \big)
    \label{eq:distortion}
\end{align}
where step $(a)$ follows by \eqref{eq:Zprime-variance-bound2} and \eqref{eq:cross-correlation}.

We bound the term $2 \alpha A\,\E{I Z}$. Define the intervals
\begin{align}
   \mathcal I_k = \left[ kA - A/2, kA + A/2 \right), \;\; k\in\mathbb Z
   \label{eq:intervals}
\end{align}
and let $Z''=\tilde Z + \alpha Z$. By symmetry, we have
\begin{align}
    \E{Z \big| Z''\in\mathcal I_{(-k)} }
    = -\E{Z \big| Z''\in\mathcal I_k }.
\end{align}
The law of total expectation thus gives
\begin{align}
    2 \alpha A\,\E{I Z} & = 4 \alpha \sum\nolimits_{k\ge 1} \Prob{Z''\in\mathcal I_k}\, k A\,
    \underbrace{\E{Z \big| Z''\in\mathcal I_k }}_{\displaystyle \le kA/\alpha} \nonumber \\
    %& \le 4 \sum\nolimits_{k\ge 1} \Prob{Z''\in\mathcal I_k}\, (kA)^2 \nonumber \\
    & \le 4 \int_{A/2}^\infty p_{Z''}(x) \cdot (x+A/2)^2\, dx
    \label{eq:EiZ-bound}
\end{align}
where
\begin{align}
    p_{Z''}(x) & = p_{\tilde Z}*p_{\alpha Z}(x) %\nonumber \\
    %& 
    = \int_{-A/2}^{A/2} \frac{q(y)}{d(y)}\, p_{\alpha Z}(x-y)\, dy \nonumber \\
    & \overset{(a)}{\le} \frac{e^{-x^2/(2\sigma_z^2)}}{c\,d_{\textrm{min}}\cdot \sqrt{2 \pi \sigma_z^2}}
\end{align}
and where step $(a)$ follows by extending the domain of $q(\cdot)$ in \eqref{eq:TG-shaping} to all reals. We may thus bound \eqref{eq:EiZ-bound} as
\begin{align}
    & 2 \alpha A\, \E{I Z}
    \le \frac{4}{c\,d_{\textrm{min}}} \int_{A/2}^\infty \frac{e^{-x^2/(2\sigma_z^2)}}{\sqrt{2 \pi \sigma_z^2}} \cdot (x+A/2)^2\, dx \nonumber \\
    & = \frac{4}{c\,d_{\textrm{min}}} \left[  \frac{3A\,\sigma_z^2}{2} \cdot \frac{e^{-A^2/(8\sigma_z^2)}}{\sqrt{2\pi\sigma_z^2}} + \left(\sigma_z^2 + \frac{A^2}{4}\right) Q\left(\frac{A}{2\sigma_z}\right) \right] .
    \label{eq:EiZ-bound2}
\end{align}
\begin{comment}
where we used
\begin{align}
    %\int_x^\infty y\, e^{-y^2/2}\, dy & = e^{-x^2/2} \\
    \int_x^\infty y^2\, e^{-y^2/2}\, dy & = x\, e^{-x^2/2} + \sqrt{2\pi}\, Q(x).
\end{align}
\end{comment}
The right-hand side of \eqref{eq:EiZ-bound2} vanishes as $A\rightarrow\infty$.

%-------------------------------
\subsection{Source Coding Rate} 
%
For the rate $R$, similar to \cite{Sener-CL24}, we have
\begin{align}
   I(U;X') & = h(X') - h(\tilde Z|U) = \log A - h(\tilde Z)
   \label{eq:message-and-shaping-rate}
   \\
   I(U;Y') & = h(Y') - h(Z'|U) = \log A - h(Z')
   \label{eq:shaping-rate}
\end{align}
where we used the independence of $U$, $\tilde Z$, $Z$. We may use \cite[eq.~(25)]{Sener-ISIT24} to lower bound $h(\tilde Z)$ and \eqref{eq:Zprime-variance-bound2} gives
\begin{align}
    h(Z')\le \frac{1}{2}\log\left(2\pi e \big(\sigma_z^2 + P_{q,\tilde Z} \big/ d_\textrm{min}-\sigma_d^2\big)\right) .
    \label{eq:hZprime-bound}
\end{align}
We proceed as in \cite{Sener-CL24,Sener-ISIT24} and first take the limit $M\rightarrow\infty$ to obtain $d(\tilde z)\rightarrow 1$ and $p(\tilde z)\rightarrow q(\tilde z)$ for $\tilde z \in [-A/2,A/2)$. We next take the limit $A\rightarrow \infty$ to obtain $p(\tilde z) \rightarrow \mathcal N(0;\sigma_d^2)$ and $p(z') \rightarrow \mathcal N(0;\sigma_z^2)$. We therefore
\begin{comment}
have
\begin{align}
    & \lim_{A\rightarrow\infty} \lim_{M\rightarrow\infty} h(\tilde Z) \rightarrow \frac{1}{2} \log(2 \pi e \sigma_d^2) \\
    & \lim_{A\rightarrow\infty} \lim_{M\rightarrow\infty} h(Z') \rightarrow \frac{1}{2} \log(2 \pi e \sigma_z^2)
\end{align}
and
\end{comment}
obtain the WZ rate.

%-------------------------------
\subsection{Simulations with Short Polar Codes}
\label{subsec:scalar-simulations}
%
Fig.~\ref{fig:rates} shows RD curves for $M=4,8,16,32$. The 4-ASK curves have $A=10,8,6$ for $\sigma_y^2=0,1,3/2$, respectively. The 8-ASK and 16-ASK curves have $A=12,10,10$, and the 32-ASK curves have $A=14,12,10$. The figure illustrates that increasing $M$ and $A$ achieves the WZ curve.

\begin{figure}[!t]
\centering
\input{rates}
\caption{RD curves for $(\sigma_y^2,\sigma_z^2)=(0,2)$, $(1,1)$, $(3/2,1/2)$ and $\sigma_x^2=2$. The target rates are $R=\frac{1}{2}\log(\sigma_z^2/\mathcal D)$.
}
\label{fig:rates}
\end{figure}

Consider $R=1$ and 8-ASK with natural labeling. We use multilevel coding with $L=\log_2 M$ levels, where levels 1 to $L$ carry successively more significant bits. Each level has one 5G NR polar code of length 256. The encoder and decoder use successive cancellation list decoding \cite{Tal-Vardy-IT15} with list size 8 and list passing across levels \cite{Prinz-Yuan-ISTC18,Karakchieva-SCC19}. The most reliable polar subchannels of each level are assigned shaping bits, the next most reliable information bits, and the rest frozen bits. We optimized $A$, $\sigma_d^2$, and the numbers of message and shaping bits across the polar subchannels to minimize $\E{\mathcal D}$.
%For example, PCQmod with 8-ASK has the following (message,shaping,frozen) bit numbers: level 1 has (19,0,237); level 2 has (176,19,61); level 3 has (61,195,0).
%

We study two sources; Fig.~\ref{fig:CDFplot} plots $\Prob{\Delta>\mathcal D}$.
\vspace{-0.1cm}
\begin{itemize}[leftmargin=*]
\item Source 1: $\sigma_y^2=0$, $\sigma_z^2=\sigma_x^2=2$, $\E{\Delta}\ge 0.5$
    \begin{itemize} \itemsep 0pt
    \item one-bit scalar quantizer: $\E{\Delta}=0.727$
    \item PCQ: $\E{\Delta}=0.614$
    for ASK spacing $0.6$
    %; 16-ASK, $\E{\Delta}=0.733$
    \item PCQmod: $\E{\Delta}=0.713$ for $A/M=1.5$
    %\item \textcolor{red}{PCQmod and 16-ASK: $\E{\Delta}=0.???$ for $A/M=?.??$}
    \end{itemize}
\item Source 2: $\sigma_y^2=\sigma_z^2=1$, $\E{\Delta}\ge 0.25$
    \begin{itemize} \itemsep 0pt
    \item one-bit scalar quantizer: $\E{\Delta}=0.519$
    \item PCQ: $\E{\Delta}=0.351$
    for ASK spacing $0.8$
    %; 16-ASK, $\E{\Delta}=0.358$
    \item PCQmod: $\E{\Delta}=0.357$ for $A/M=1.25$
    \end{itemize}
\end{itemize}
\vspace{0.1cm}
Fig.~\ref{fig:CDFplot} shows PCQ outperforms PCQmod, notably for $\sigma_y^2=0$ where PCQ can use a (relatively) fine ASK spacing with few shaping bits. PCQmod requires coarser ASK spacing and more shaping bits because $A$ must be sufficiently large to limit the number of modulo shifts, while the dither makes $I(U;Y')$ grow as $\log A$ even if $Y=0$; see~\eqref{eq:shaping-rate}. Fig.~\ref{fig:CDFplot} also shows PCQ and PCQmod perform similarly as $\sigma_y^2$ increases; this is because WZ coding requires shaping bits for both methods, as represented by $I(U;Y)$ for PCQ and $I(U;Y')$ for PCQmod. We remark dithering benefits quantization and secrecy by making $(X',M)$ independent of $X$ \cite[Ch.~4]{zamir14}.

