\section{Vector Models and Quantization}
\label{sec:vector-models}
%
Consider the vectors $\bm{X},\bm{Y}$. We re-define (see \eqref{eq:XV})
\begin{align}
    \bm{X}_V := V^T \bm{X} = V^T \E{\bm{X}|\bm{Y}} + V^T \bm{Z}
    \label{eq:vector-source-transformed}
\end{align}
because the encoder does not have $\bm{Y}$. Let $\bm{Y}_V = V^T \E{\bm{X}|\bm{Y}}$ so we have (see \eqref{eq:QXV})
\begin{align}
    Q_{\bm{X}_V|\bm{Y}}
    = Q_{\bm{X}_V|\bm{Y}_V}
    = Q_{\bm{V}^T \bm{Z}} = \Lambda .
\end{align}
Thus, the $X_{V,1},\dots,X_{V,\ddim}$ are independent given $\bm{Y}$ or $\bm{Y}_V$ . Moreover, if $\bm{v}_i^T$ is the $i$-th row of $V^T$, we have
\begin{align}
    \E{X_{V,i}|\bm{Y}}
    & = \bm{v}_i^T \E{\bm{X} \bm{Y}^T} Q_{\bm{Y}}^{-1} \bm{Y}
    = Y_{V,i} %\nonumber \\
    %\E{X_{V,i}|Y_{V,i}}
    %& = \frac{\E{X_{V,i} Y_{V,i}}}{\E{Y_{V,i}^2}} Y_{V,i}
    %= Y_{V,i} 
\end{align}
and therefore $X_{V,i}\leftrightarrow Y_{V,i}\leftrightarrow \bm{Y}$ forms a Markov chain.

For coding, mimic \eqref{eq:WZ-estimate}--\eqref{eq:WZ-rate-scalar} and choose
\begin{align}
    U_i=X_{V,i}+\check{Z}_i, \quad i=1,\dots,\ddim
\end{align}
where $\check{Z}_1,\dots,\check{Z}_n$, $(\bm{X},\bm{Y})$ are mutually independent. We have the Markov chains $U_i\leftrightarrow
X_{V,i}\leftrightarrow Y_{V,i} \leftrightarrow\bm{Y}$ and \eqref{eq:R-diff-cond} gives
\begin{align}
    R = I(\bm{U};\bm{X}|\bm{Y})
    %& = I(\bm{U};\bm{X}_V|\bm{Y}_V) \nonumber \\
    & = \sum\nolimits_{i=1}^\ddim I(U_i;X_{V,i}|Y_{V,i})
    \label{eq:WZ-sum}
\end{align}
where $X_{V,i} -\E{X_{V,i}|Y_{V,i}}$ has variance $\lambda_i$. We describe $X_{V,i}$ with the reverse waterfilling level $\lambda$ as in Sec.~\ref{subsec:WZ-rates} to obtain the $\hat{X}_{V,i}$ in \eqref{eq:forward-channel-i}. Thus, the distortions for $i=1,\dots,\ddim$ are $\min(\lambda_i,\lambda)$ and the sub-channel rates are
\begin{align}
    R_i = I(U_i;X_{V,i}|Y_{V,i}) = \left\{
    \begin{array}{ll}
    \frac{1}{2}\log(\lambda_i/\lambda), & \lambda < \lambda_i \\
    0, & \lambda \ge \lambda_i
    \end{array} \right. .
\end{align}

