\section{The Proof of Lemma \ref{Lem:D-RIP}}

Inspired by Zhang and Li's work \cite{ZL18}, we provide the proof of Lemma \ref{Lem:D-RIP} as follows.

\begin{proof}[Proof of Lemma \ref{Lem:D-RIP}]
First, we assume that $tk$ is an integer. Let $h=\hat{x}-x_0$, and let $T_0$ and $S_0$ be the index sets of the $k$ largest entries in absolute value of $D^*x_0$ and $D^*h$, respectively. Without loss of generality, we assume that $S_0:=[1,k]$.
Since
\begin{equation*}
\|D^*x_0\|_q^q\ge\|D^*\hat{x}\|_q^q,
\end{equation*}
we have
\begin{eqnarray}
\|D_{T_0}^*x_0\|_q^q+\|D_{T_0^c}^*x_0\|_q^q&=&\|D^*x_0\|_q^q\nonumber\\
&\ge&\|D^*x_0+D^*{h}\|_q^q\nonumber\\
&=&\|D_{T_0}^*x_0+D_{T_0}^*{h}\|_q^q+\|D_{T_0^c}^*x_0+D_{T_0^c}^*{h}\|_q^q\nonumber\\
&\ge&\|D_{T_0}^*x_0\|_q^q-\|D_{T_0}^*{h}\|_q^q+\|D_{T_0^c}^*{h}\|_q^q-\|D_{T_0^c}^*x_0\|_q^q.\label{lem:D1}
\end{eqnarray}
Rewrite the above inequality (\ref{lem:D1}), and we get
\begin{eqnarray}
\|D_{T_0^c}^*{h}\|_q^q&\le&\|D_{T_0}^*{h}\|_q^q+2\|D_{T_0^c}^*{x_0}\|_q^q\nonumber\\
&=&\|D_{T_0}^*{h}\|_q^q+2\sigma_k(D^*{x_0})_q^q.\label{lem:D2}
\end{eqnarray}
Thus, it is obtained that
\begin{eqnarray}
\|D_{S_0^c}^*{h}\|_q^q&\le&\|D_{T_0^c}^*{h}\|_q^q\le\|D_{T_0}^*{h}\|_q^q+2\sigma_k(D^*{x_0})_q^q\nonumber\\
&\le&\|D_{S_0}^*{h}\|_q^q+2\sigma_k(D^*{x_0})_q^q.\label{lem:D3}
\end{eqnarray}
Assume that $\|D_{S_0^c}^*h\|_0=r\ge k$. Choose
\begin{equation}
\alpha^q:=\frac{\|D_{S_0}^*{h}\|_q^q+2\sigma_k(D^*{x_0})_q^q}{k}.\label{lem:Aa1}
\end{equation}
Let $a$ and $b$ be two positive integers satisfying $a+b=tk$ and $b\le a\le k$. Set all the possible index sets $T_i$,\;$S_j\subset S_0=[1:k]$, which satisfy $|T_i|=a\;(i\in I),|S_j|=b\;(j\in J)$ with $|I|=\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)$,
$|J|=\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)$,
respectively.
Note that
\[
\|D_{S_0^c}^*{h}\|_q^q\le\|D_{S_0}^*{h}\|_q^q+2\sigma_k(D^*{x_0})_q^q=k\alpha^q=b\cdot \left(\sqrt[q]{\frac{k}{b}}\alpha\right)^q.
\]
Then, we can derive
\begin{equation*}
\|D_{S_0^c}^*{h}\|_{\infty}^q\le\frac{\|D_{S_0}^*{h}\|_q^q}{k}\le\frac{k\alpha^q}{k}=\alpha^q,
\end{equation*}
namely,
\[
\|D_{S_0^c}^*{h}\|_{\infty}\le\alpha\le\sqrt[q]{\frac{k}{b}}\alpha.
\]
Thus, it follows from Lemma \ref{lem2} that $D_{S_0^c}^*{h}$ can be decomposed as
\[
D_{S_0^c}^*{h}=\sum_{l}\lambda_lu_l,
\]
where $u_l$ is $b$-sparse, and
\begin{equation}\label{lem:dd}
\sum_{l}\lambda_l\|u_l\|_2^2\le\frac{k}{b}\alpha^q\|D_{S_0^c}^*{h}\|_{2-q}^{2-q}.
\end{equation}
Similarly, $D_{S_0^c}^*{h}$ can also be represented by
\[
D_{S_0^c}^*{h}=\sum_{l}\lambda_l^\prime v_l,\;D_{S_0^c}^*{h}=\sum_{l}\lambda_l^{\prime\prime} w_l,
\]
where $v_l$ is $a$-sparse, $w_l$ is $(t-1)k$-sparse (for $t>1$), and
\begin{eqnarray}
\sum_{l}\lambda_l^\prime\|v_l\|_2^2\le\frac{k}{a}\alpha^q\|D_{S_0^c}^*{h}\|_{2-q}^{2-q},\;\sum_{l}\lambda_l^{\prime\prime}\|w_l\|_2^2\le\frac{1}{t-1}\alpha^q\|D_{S_0^c}^*{h}\|_{2-q}^{2-q}.\label{lem:D4}
\end{eqnarray}
Note that
\begin{equation}\label{lem:D5}
\|Ah\|_2=\|A\hat{x}-Ax_0\|_2\le\epsilon.
\end{equation}
We have
\begin{eqnarray}\label{lem:D6}
|\langle ADD_{S_0}^*h,Ah\rangle|^2&\le&\|ADD_{S_0}^*h\|_2^2\|Ah\|_2^2\nonumber\\
&\le&\epsilon^2(1+\delta_k)\|DD_{S_0}^*h\|_2^2\nonumber\\
&\le&\epsilon^2(1+\delta_{tk})\|D_{S_0}^*h\|_2^2
\end{eqnarray}
for $t\in[1,\frac{4}{3})$, where we use the fact that if $k\le k_1$, $\delta_k\le\delta_{k_1}$ in the last step;
\begin{eqnarray}\label{lem:D7}
|\langle ADD_{S_0}^*h,Ah\rangle|^2&\le&\epsilon^2(1+\delta_k)\|DD_{S_0}^*h\|_2^2\nonumber\\
&\le&\epsilon^2\left[1+\left(\frac{2}{t}-1\right)\delta_{tk}\right]\|D_{S_0}^*h\|_2^2\nonumber\\
&\le&\frac{(1+\delta_{tk})\epsilon^2}{t}\|D_{S_0}^*h\|_2^2
\end{eqnarray}
for $t\in(0,1)$, where we use Lemma 4.1 proposed in \cite{CZ13} in the last two steps.
Set
\begin{align}
Y_{a,b}&:=\frac{k-b}{a\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{i\in I,l}\lambda_l\bigg[a^2\|AD\left(D_{T_i}^*h+\frac{b}{k}u_l\right)\|_2^2+a^2\|D^{\bot}\left(D_{T_i}^*h+\frac{b}{k}u_l\right)\|_2^2\nonumber\\
    &\quad-b^2\|AD\left(D_{T_i}^*h-\frac{a}{k}u_l\right)\|_2^2-b^2\|D^{\bot}\left(D_{T_i}^*h-\frac{a}{k}u_l\right)\|_2^2\bigg]\nonumber\\
    &\quad\quad+\frac{k-a}{b\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{j\in J,l}\lambda^{\prime}_l\bigg[b^2\|AD\left(D_{S_j}^*h+\frac{a}{k}v_l\right)\|_2^2+b^2\|D^{\bot}\left(D_{S_j}^*h+\frac{a}{k}v_l\right)\|_2^2\nonumber\\
     &\quad\quad\quad-a^2\|AD\left(D_{S_j}^*h-\frac{b}{k}v_l\right)\|_2^2-a^2\|D^{\bot}\left(D_{S_j}^*h-\frac{b}{k}v_l\right)\|_2^2\bigg].\label{lem:D8}
\end{align}
For $1\le t<\frac{4}{3}$, we can obtain
\begin{align}
&(4-3t)Y_{a,b}-2t^3[ab-(t-1)k^2]\langle ADD_{S_0}^*h,Ah\rangle\nonumber\\
=&C_{t,a,b}\sum_{l}\lambda_l^{\prime\prime}\bigg[\|AD(D_{S_0}^*h+(t-1)w_l)\|_2^2+\|D^{\bot}(D_{S_0}^*h+(t-1)w_l)\|_2^2\nonumber\\
 &\quad-(t-1)^2\|AD(D_{S_0}^*h-w_l)\|_2^2-(t-1)^2\|D^{\bot}(D_{S_0}^*h-w_l)\|_2^2\bigg],\label{lem:D9}
\end{align}
and for $0<t<1$, we can derive
\begin{align}
&tY_{a,b}-2t^2(2-t)ab\langle ADD_{S_0}^*h,Ah\rangle\nonumber\\
=&\frac{C_{t,a,b}}{\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)
                                                                                           \left(
                                                                                             \begin{array}{c}
                                                                                               k-a \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{T_i\cap S_j=\emptyset}\bigg[\|AD\left(D_{T_i}^*h+D_{S_j}^*h\right)\|_2^2+\|D^{\bot}\left(D_{T_i}^*h+D_{S_j}^*h\right)\|_2^2\nonumber\\
&\quad-\frac{1-t}{ab}\|AD\left(bD_{T_i}^*h-aD_{S_j}^*h\right)\|_2^2-\frac{1-t}{ab}\|D^{\bot}\left(bD_{T_i}^*h-aD_{S_j}^*h\right)\|_2^2\bigg],\label{lem:D10}
\end{align}
where it is due to the fact that $\langle D^{\bot}D_{S_0}^*h,D^{\bot}D^*h\rangle=0$ and $C_{t,a,b}:=(a-b)^2-2(2-t)ab$. The proofs of the above two inequalities are similar to those of (14) and (15) in \cite{ZL18}, and therefore, we leave out all the details for simplicity. When $tk$ is even, let $a=b=\frac{tk}{2}$; when $tk$ is odd, let $a=b+1=\frac{tk+1}{2}$. We can easily prove $C_{t,a,b}<0$ for both cases.

Since $D_{T_i}^*,\;v_l$ are $a$-sparse, $D_{S_j}^*,\;u_l$ are $b$-sparse with $a+b=tk$, we can apply the D-RIP of order $tk$ to $Y_{a,b}$, which yields
\begin{align}
&Y_{a,b}\nonumber\\
\ge&\frac{k-b}{a\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{i\in I,l}\lambda_l\bigg[a^2(1-\delta_{tk})\|D_{T_i}^*h+\frac{b}{k}u_l\|_2^2-b^2(1+\delta_{tk})\|D_{T_i}^*h-\frac{a}{k}u_l\|_2^2\bigg]\nonumber\\
&\quad+\frac{k-a}{b\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{j\in J,l}\lambda^{\prime}_l\bigg[b^2(1-\delta_{tk})\|D_{S_j}^*h+\frac{a}{k}v_l\|_2^2-a^2(1+\delta_{tk})\|D_{S_j}^*h-\frac{b}{k}v_l\|_2^2\bigg]\nonumber\\
=&\frac{k-b}{a\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{i\in I,l}\lambda_l\bigg[a^2(1-\delta_{tk})\bigg(\|D_{T_i}^*h\|_2^2+\frac{b^2}{k^2}\|u_l\|_2^2\bigg)-b^2(1+\delta_{tk})\bigg(\|D_{T_i}^*h\|_2^2+\frac{a^2}{k^2}\|u_l\|_2^2\bigg)\bigg]\nonumber\\
&\quad+\frac{k-a}{b\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{j\in J,l}\lambda^{\prime}_l\bigg[b^2(1-\delta_{tk})\bigg(\|D_{S_j}^*h\|_2^2+\frac{a^2}{k^2}\|v_l\|_2^2\bigg)\nonumber\\
&\quad\quad-a^2(1+\delta_{tk})\bigg(\|D_{S_j}^*h\|_2^2+\frac{b^2}{k^2}\|v_l\|_2^2\bigg)\bigg]\nonumber\\
=&(a^2-b^2)\Bigg[\frac{k-b}{a\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{i\in I}\|D_{T_i}^*h\|_2^2-\frac{k-a}{b\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{j\in J}\|D_{S_j}^*h\|_2^2\Bigg]\nonumber\\
&\quad-(a^2+b^2)\delta_{tk}\Bigg[\frac{k-b}{a\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{i\in I}\|D_{T_i}^*h\|_2^2
+\frac{k-a}{b\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{j\in J}\|D_{S_j}^*h\|_2^2\Bigg]\nonumber\\
&\quad\quad-\frac{2\delta_{tk}ab}{k^2}\bigg[b(k-b)\sum_{l}\lambda_l\|u_l\|_2^2+a(k-a)\sum_{l}\lambda_l^{\prime}\|v_l\|_2^2\bigg]\nonumber\\
\ge&(a^2-b^2)\Bigg[\frac{k-b}{a\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)}
\left(
                                                                                             \begin{array}{c}
                                                                                               k-1 \\
                                                                                               a-1 \\
                                                                                             \end{array}
                                                                                           \right)
\|D_{S_0}^*h\|_2^2-\frac{k-a}{b\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)}
                                                                                           \left(
                                                                                             \begin{array}{c}
                                                                                               k-1 \\
                                                                                               b-1 \\
                                                                                             \end{array}
                                                                                           \right)
\|D_{S_0}^*h\|_2^2\Bigg]\nonumber\\
&\quad-(a^2+b^2)\delta_{tk}\Bigg[\frac{k-b}{a\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)}
                                                                                           \left(
                                                                                             \begin{array}{c}
                                                                                               k-1 \\
                                                                                               a-1 \\
                                                                                             \end{array}
                                                                                           \right)
\|D_{S_0}^*h\|_2^2-\frac{k-a}{b\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)}
                                                                                           \left(
                                                                                             \begin{array}{c}
                                                                                               k-1 \\
                                                                                               b-1 \\
                                                                                             \end{array}
                                                                                           \right)
\|D_{S_0}^*h\|_2^2\Bigg]\nonumber\\
&\quad\quad-\frac{2\delta_{tk}ab}{k^2}\bigg[b(k-b)\frac{k}{b}\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}+a(k-a)\frac{k}{a}\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}\bigg]\nonumber\\
%&=[t(a-b)^2-(2-t)(a^2+b^2)\delta_{tk}]\|D_{S_0}^*h\|_2^2-\frac{2\delta_{tk}ab}{k}(2k-a-b)\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}\nonumber\\
=&[t(a-b)^2-(2-t)(a^2+b^2)\delta_{tk}]\|D_{S_0}^*h\|_2^2-2(2-t)\delta_{tk}ab\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q},\label{lem:D11}
\end{align}
where we use (\ref{lem1:1}), (\ref{lem:dd}) and (\ref{lem:D4}) in the penultimate step.
By the H\"{o}lder's inequality, (\ref{lem:D3}) and (\ref{lem:Aa1}), we have
\begin{eqnarray}
\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}
&=&\alpha^q\sum_{i\in S_0^c}|D^*h(i)|^{\frac{2(2-2q)}{2-q}}|D^*h(i)|^{\frac{q^2}{2-q}}\nonumber\\
&\le&\alpha^q\left(\sum_{i\in S_0^c}|D^*h(i)|^{2}\right)^{\frac{2-2q}{2-q}}\left(\sum_{i\in S_0^c}|D^*h(i)|^q\right)^{\frac{q}{2-q}}\nonumber\\
&=&\alpha^q\left(\|D_{S_0^c}^*h\|_{2}^2\right)^{\frac{2-2q}{2-q}}\left(\|D_{S_0^c}^*h\|_{q}^q\right)^{\frac{q}{2-q}}\nonumber\\
&\le&\alpha^q\left(\|D_{S_0^c}^*h\|_{2}^2\right)^{\frac{2-2q}{2-q}}(k\alpha^q)^{\frac{q}{2-q}}\nonumber\\
&=&\left(\|D_{S_0^c}^*h\|_{2}^2\right)^{\frac{2-2q}{2-q}}\left(\frac{k\alpha^q}{k^{1-\frac{q}{2}}}\right)^{\frac{2}{2-q}}\nonumber\\
&=&\left(\|D_{S_0^c}^*h\|_{2}^2\right)^{\frac{2-2q}{2-q}}\left(\frac{\|D_{S_0}^*{h}\|_q^q+2\sigma_k(D^*{x_0})_q^q}{k^{1-\frac{q}{2}}}\right)^{\frac{2}{2-q}}\nonumber\\
&\le&\left(\|D_{S_0^c}^*h\|_{2}^2\right)^{\frac{2-2q}{2-q}}\left(\|D_{S_0}^*{h}\|_2^q+\frac{2\sigma_k(D^*{x_0})_q^q}{k^{1-\frac{q}{2}}}\right)^{\frac{2}{2-q}}.\label{lem:D12}
\end{eqnarray}
Combining (\ref{lem:D3}) and Lemma~\ref{Lem:Add1}, we derive
\begin{eqnarray}
\|D_{S_0^c}^*h\|_{2}^2&\le& k\left[\left(\frac{\|D_{S_0}^*{h}\|_2^2}{k}\right)^{\frac{q}{2}}+\frac{2\sigma_k(D^*{x_0})_q^q}{k}\right]^{\frac{2}{q}}\nonumber\\
&=&\left(\|D_{S_0}^*{h}\|_2^q+\frac{2\sigma_k(D^*{x_0})_q^q}{k^{1-\frac{q}{2}}}\right)^{\frac{2}{q}}.\label{lem:A12}
\end{eqnarray}
Substituting (\ref{lem:A12}) into (\ref{lem:D12}), we obtain
\begin{eqnarray}
\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}
&\le&\left(\|D_{S_0}^*{h}\|_2^q+\frac{2\sigma_k(D^*{x_0})_q^q}{k^{1-\frac{q}{2}}}\right)^{\frac{2}{q}}\nonumber\\
&\le&\left[2^{\frac{1}{q}-1}\bigg(\|D_{S_0}^*h\|_2+\frac{2^{\frac{1}{q}}\sigma_k(D^*x_0)_q}{k^{\frac{1}{q}-\frac{1}{2}}}\bigg)\right]^2\nonumber\\
&=&2^{\frac{2}{q}-2}\|D_{S_0}^*h\|_2^2+2^{\frac{3}{q}-1}\|D_{S_0}^*h\|_2R+2^{\frac{4}{q}-2}R^2,\label{lem:A13}
\end{eqnarray}
where $$R:=\frac{\sigma_k(D^*{x_0})_q}{k^{\frac{1}{q}-\frac{1}{2}}}.$$
%Substituting (\ref{lem:D12}) into (\ref{lem:D11}), we get
%\begin{equation}\label{lem:D13}
%Y_{a,b}\ge[t(a-b)^2-(2-t)(a^2+b^2)\delta_{tk}]\|D_{S_0}^*h\|_2^2-2(2-t)\delta_{tk}ab\left(\|D_{S_0^c}^*h\|_{2}^2\right)^{\frac{2-2q}{2-q}}\left(\|D_{S_0}^*{h}\|_2^q
%  +\frac{2\sigma_k(D^*{x_0})_q^q}{k^{1-\frac{q}{2}}}\right)^{\frac{2}{2-q}}.
%\end{equation}
For brevity, set
\begin{eqnarray*}
\mathcal{A}&:=&(4-3t)Y_{a,b}-2t^3\big[ab-(t-1)k^2\big]\langle ADD_{S_0}^*h,Ah\rangle,\nonumber\\
\mathcal{B}&:=&C_{t,a,b}\sum_{l}\lambda_l^{\prime\prime}\bigg[\|AD(D_{S_0}^*h+(t-1)w_l)\|_2^2+\|D^{\bot}(D_{S_0}^*h+(t-1)w_l)\|_2^2{}\nonumber\\
{}&&\quad-(t-1)^2\|AD(D_{S_0}^*h-w_l)\|_2^2-(t-1)^2\|D^{\bot}(D_{S_0}^*h-w_l)\|_2^2\bigg],\nonumber\\
\mathcal{C}&:=&tY_{a,b}-2t^2(2-t)ab\langle ADD_{S_0}^*h,Ah\rangle,\nonumber\\
\mathcal{D}&:=&\frac{C_{t,a,b}}{\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)
                                                                                           \left(
                                                                                             \begin{array}{c}
                                                                                               k-a \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{T_i\cap S_j=\emptyset}\bigg[\|AD\left(D_{T_i}^*h+D_{S_j}^*h\right)\|_2^2+\|D^{\bot}\left(D_{T_i}^*h+D_{S_j}^*h\right)\|_2^2{}\nonumber\\
{}&&-\frac{1-t}{ab}\|AD\left(bD_{T_i}^*h-aD_{S_j}^*h\right)\|_2^2-\frac{1-t}{ab}\|D^{\bot}\left(bD_{T_i}^*h-aD_{S_j}^*h\right)\|_2^2\bigg].\nonumber\\
\end{eqnarray*}

When $t\in[1,\frac{4}{3})$, combining (\ref{lem:D6}) and (\ref{lem:D11}), we get
\begin{align}
\mathcal{A}\ge&(4-3t)\Big\{\big[t(a-b)^2-(2-t)(a^2+b^2)\delta_{tk}\big]\|D_{S_0}^*h\|_2^2-2(2-t)\delta_{tk}ab\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}\Big\}{}\nonumber\\
&-2t^3\big[ab-(t-1)k^2\big]\cdot\epsilon\sqrt{1+\delta_{tk}}\|D_{S_0}^*h\|_2.\label{lem:D15}
\end{align}
Since $D_{S_0}^*h$ is $k$-sparse and $w_l$ is $(t-1)k$-sparse, applying the D-RIP of order $tk$, we obtain
\begin{eqnarray}
\mathcal{B}&\le& C_{t,a,b}\sum_{l}\lambda_l^{\prime\prime}\Big[(1-\delta_{tk})\|D_{S_0}^*h+(t-1)w_l\|_2^2-(t-1)^2(1+\delta_{tk})\|D_{S_0}^*h-w_l\|_2^2\Big]\nonumber\\
&\le&C_{t,a,b}\Big\{\big[1-\delta_{tk}-(t-1)^2(1+\delta_{tk})\big]\|D_{S_0}^*h\|_2^2-2(t-1)^2\delta_{tk}\sum_{l}\lambda_l^{\prime\prime}\|w_l\|_2^2\Big\}\nonumber\\
&\le&C_{t,a,b}\Big\{\big[1-\delta_{tk}-(t-1)^2(1+\delta_{tk})\big]\|D_{S_0}^*h\|_2^2-2(t-1)\delta_{tk}\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}\Big\},\label{lem:D14}
\end{eqnarray}
where we use (\ref{lem:D4}) in the last step.
Thus, combining (\ref{lem:A13}), (\ref{lem:D15}) and (\ref{lem:D14}), we have
\begin{eqnarray*}
0&\ge&(4-3t)\Big\{\big[t(a-b)^2-(2-t)(a^2+b^2)\delta_{tk}\big]\|D_{S_0}^*h\|_2^2-2(2-t)\delta_{tk}ab\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}\Big\}{}\nonumber\\
{}&&-2t^3[ab-(t-1)k^2\big]\epsilon\sqrt{1+\delta_{tk}}\|D_{S_0}^*h\|_2{}\nonumber\\
{}&&\quad-C_{t,a,b}\Big\{\big[1-\delta_{tk}-(t-1)^2(1+\delta_{tk})\big]\|D_{S_0}^*h\|_2^2
-2(t-1)\delta_{tk}\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}\Big\}\nonumber\\
&=&2t^2[ab-(t-1)k^2\big]\left\{\big[t-(3-t)\delta_{tk}\big]\|D_{S_0}^*h\|_2^2-\delta_{tk}\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}\right\}{}\nonumber\\
{}&&-2t^3\big[ab-(t-1)k^2\big]\epsilon\sqrt{1+\delta_{tk}}\|D_{S_0}^*h\|_2\nonumber\\
&\ge&2t^2\big[ab-(t-1)k^2\big]\left\{\big[t-(3-t)\delta_{tk}\big]\|D_{S_0}^*h\|_2^2-\delta_{tk}\Big(2^{\frac{2}{q}-2}\|D_{S_0}^*h\|_2^2\right.{}\nonumber\\
{}&&\left.+2^{\frac{3}{q}-1}\|D_{S_0}^*h\|_2R+2^{\frac{4}{q}-2}R^2\Big)\right\}
-2t^3\big[ab-(t-1)k^2\big]\epsilon\sqrt{1+\delta_{tk}}\|D_{S_0}^*h\|_2\nonumber\\
&=&2t^2\big[ab-(t-1)k^2\big]\left\{\big[t-(3+2^{\frac{2}{q}-2}-t)\delta_{tk}\big]\|D_{S_0}^*h\|_2^2-\Big(2^{\frac{3}{q}-1}\delta_{tk}R
\right.{}\nonumber\\
{}&&\left.+t\epsilon\sqrt{1+\delta_{tk}}\Big)\|D_{S_0}^*h\|_2-2^{\frac{4}{q}-2}\delta_{tk}R^2\right\},%\label{lem:D16}
\end{eqnarray*}
which is a second-order inequality for $\|D_{S_0}^*h\|_2$.
Notice that $ab\ge\frac{(tk)^2-1}{4}=\frac{(2-t)^2k^2}{4}-\frac{1}{4}+(t-1)k^2>(t-1)k^2$. Since $\delta_{tk}<\frac{t}{3+2^{\frac{2}{q}-2}-t}$, we can derive
\begin{align}
&\|D_{S_0}^*h\|_2\nonumber\\
\le&\frac{2^{\frac{3}{q}-1}\delta_{tk}R+t\epsilon\sqrt{1+\delta_{tk}}}{2\Big[t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}\Big]}\nonumber\\
&\quad+\frac{\sqrt{\Big(2^{\frac{3}{q}-1}\delta_{tk}R+t\epsilon\sqrt{1+\delta_{tk}}\Big)^2
   +4\Big[t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}\Big]2^{\frac{4}{q}-2}\delta_{tk}R^2}}{2\Big[t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}\Big]}\nonumber\\
\le&\frac{t\sqrt{1+\delta_{tk}}}{t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}}\epsilon+\frac{2^{\frac{3}{q}-1}\delta_{tk}+2^{\frac{2}{q}-1}
   \sqrt{\Big[t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}\Big]\delta_{tk}}}{t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}}R.
   \label{lem:D17}
\end{align}

When $t\in(0,1)$, combining (\ref{lem:D7}) and (\ref{lem:D11}), we obtain
\begin{eqnarray}\label{lem:D19}
\mathcal{C}&\ge& t\left\{\big[t(a-b)^2-(2-t)(a^2+b^2)\delta_{tk}\big]\|D_{S_0}^*h\|_2^2-2(2-t)\delta_{tk}ab\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}\right\}{}\nonumber\\
{}&&-2t(2-t)ab\epsilon\sqrt{(1+\delta_{tk})t}\|D_{S_0}^*h\|_{2}.
\end{eqnarray}
Since $D_{T_i}^*h$ is $a$-sparse and $D_{S_j}^*h$ is $b$-sparse, applying the D-RIP of order $tk$ and (\ref{lem1:1}), we have
\begin{align}
\mathcal{D}
\le&\frac{C_{t,a,b}}{\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)
                                                                                           \left(
                                                                                             \begin{array}{c}
                                                                                               k-a \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)}
\sum_{T_i\cap S_j=\emptyset}\bigg[(1-\delta_{tk})\|D_{T_i}^*h+D_{S_j}^*h\|_2^2\nonumber\\
&\quad-\frac{1-t}{ab}(1+\delta_{tk})\|bD_{T_i}^*h-aD_{S_j}^*h\|_2^2\bigg]\nonumber\\
=&\frac{C_{t,a,b}}{\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)
                                                                                           \left(
                                                                                             \begin{array}{c}
                                                                                               k-a \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)}
\bigg[(1-\delta_{tk})\sum_{T_i\cap S_j=\emptyset}(\|D_{T_i}^*h\|_2^2+\|D_{S_j}^*h\|_2^2)\nonumber\\
&\quad-\frac{1-t}{ab}(1+\delta_{tk})\sum_{T_i\cap S_j=\emptyset}(b^2\|D_{T_i}^*h\|_2^2+a^2\|D_{S_j}^*h\|_2^2)\bigg]\nonumber\\
=&\frac{C_{t,a,b}}{\left(
                                                                                             \begin{array}{c}
                                                                                               k \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)
                                                                                           \left(
                                                                                             \begin{array}{c}
                                                                                               k-a \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)}
\Bigg\{(1-\delta_{tk})\bigg[\left(
                                                                                             \begin{array}{c}
                                                                                               k-a \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)
                                                                                           \left(
                                                                                             \begin{array}{c}
                                                                                               k-1 \\
                                                                                               a-1 \\
                                                                                             \end{array}
                                                                                           \right)
\|D_{S_0}^*h\|_2^2\nonumber\\
&\quad+\left(
                                                                                             \begin{array}{c}
                                                                                              k-b \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)
                                                                                           \left(
                                                                                             \begin{array}{c}
                                                                                               k-1 \\
                                                                                               b-1 \\
                                                                                             \end{array}
                                                                                           \right)
\|D_{S_0}^*h\|_2^2\bigg]-\frac{1-t}{ab}(1+\delta_{tk})\bigg[b^2\left(
                                                                                             \begin{array}{c}
                                                                                               k-a \\
                                                                                               b \\
                                                                                             \end{array}
                                                                                           \right)
                                                                                           \left(
