                                                                                               k-1 \\
                                                                                               a-1 \\
                                                                                             \end{array}
                                                                                           \right)\nonumber\\
&\quad\quad\times\|D_{S_0}^*h\|_2^2
+a^2\left(
                                                                                             \begin{array}{c}
                                                                                               k-b \\
                                                                                               a \\
                                                                                             \end{array}
                                                                                           \right)
                                                                                           \left(
                                                                                             \begin{array}{c}
                                                                                               k-1 \\
                                                                                               b-1 \\
                                                                                             \end{array}
                                                                                           \right)
\|D_{S_0}^*h\|_2^2\bigg]\Bigg\}\nonumber\\
\le& C_{t,a,b}t\big[t-(2-t)\delta_{tk}\big]\|D_{S_0}^*h\|_2^2.\label{lem:D18}
\end{align}
Therefore, combining (\ref{lem:A13}), (\ref{lem:D19}), and (\ref{lem:D18}), we have
\begin{eqnarray}
0&\ge&t\left\{\big[t(a-b)^2-(2-t)(a^2+b^2)\delta_{tk}\big]\|D_{S_0}^*h\|_2^2-2(2-t)\delta_{tk}ab\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}\right\}{}\nonumber\\
{}&&-2t(2-t)ab\epsilon\sqrt{(1+\delta_{tk})t}\|D_{S_0}^*h\|_{2}-C_{t,a,b}t\big[t-(2-t)\delta_{tk}\big]\|D_{S_0}^*h\|_2^2\nonumber\\
&=&2t(2-t)ab\left\{\big[t-(3-t)\delta_{tk}\big]\|D_{S_0}^*h\|_2^2-\delta_{tk}\alpha^q\|D_{S_0^c}^*h\|_{2-q}^{2-q}-\epsilon\sqrt{(1+\delta_{tk})t}\|D_{S_0}^*h\|_{2}\right\}\nonumber\\
&\ge&2t(2-t)ab\Big\{\big[t-(3-t)\delta_{tk}\big]\|D_{S_0}^*h\|_2^2-\delta_{tk}\Big(2^{\frac{2}{q}-2}\|D_{S_0}^*h\|_2^2+2^{\frac{3}{q}-1}\|D_{S_0}^*h\|_2R{}\nonumber\\
{}&&+2^{\frac{4}{q}-2}R^2\Big)-\epsilon\sqrt{(1+\delta_{tk})t}\|D_{S_0}^*h\|_{2}\Big\}\nonumber\\
&=&2t(2-t)ab\left\{\big[t-(3+2^{\frac{2}{q}-2}-t)\delta_{tk}\big]\|D_{S_0}^*h\|_2^2-\big[\epsilon\sqrt{(1+\delta_{tk})t}+2^{\frac{3}{q}-1}\delta_{tk}R\big]\|D_{S_0}^*h\|_2\right.{}\nonumber\\
{}&&\left.-\delta_{tk}2^{\frac{4}{q}-2}R^2\right\}.\label{lem:D20}
\end{eqnarray}
Since $\delta_{tk}<\frac{t}{3+2^{\frac{2}{q}-2}-t}$, we have
\begin{align}
&\|D_{S_0}^*h\|_2\nonumber\\
\le&\frac{\epsilon\sqrt{(1+\delta_{tk})t}+2^{\frac{3}{q}-1}\delta_{tk}R}{2\Big[t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}\Big]}\nonumber\\
&\quad+\frac{\sqrt{\Big[\epsilon\sqrt{(1+\delta_{tk})t}+2^{\frac{3}{q}-1}\delta_{tk}R\Big]^2
+4\Big[t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}\Big]\delta_{tk}2^{\frac{4}{q}-2}R^2}}{2\Big[t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}\Big]}\nonumber\\
\le&\frac{\sqrt{(1+\delta_{tk})t}}{t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}}\epsilon+\frac{2^{\frac{3}{q}-1}\delta_{tk}
+2^{\frac{2}{q}-1}\sqrt{\Big[t-(3+2^{\frac{2}{q}-2}-t)\delta_{tk}\Big]\delta_{tk}}}{t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}}R.\label{lem:D21}
\end{align}
Combining (\ref{lem:D17}) and (\ref{lem:D21}), we know that
\begin{equation}\label{lem:D22}
\|D_{S_0}^*h\|_2
\le\frac{\tilde{t}\sqrt{1+\delta_{tk}}}{t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}}\epsilon+\frac{2^{\frac{3}{q}-1}\delta_{tk}
+2^{\frac{2}{q}-1}\sqrt{\Big[t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}\Big]\delta_{tk}}}{t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}}R,
\end{equation}
where $\tilde{t}=\max\{t,\sqrt{t}\}$.
Using (\ref{lem:A12}) and (\ref{lem:D22}), we obtain
\begin{align}
&\|h\|_2=\|D^*h\|_2\le\|D_{S_0}^*h\|_2+\|D_{S_0^c}^*h\|_2\nonumber\\
\le&(1+2^{\frac{1}{q}-1})\|D_{S_0}^*h\|_2+2^{\frac{2}{q}-1}R\nonumber\\
\le&\frac{(1+2^{\frac{1}{q}-1})\tilde{t}\sqrt{1+\delta_{tk}}}{t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}}\epsilon
   +\left(\frac{(1+2^{\frac{1}{q}-1})\left\{2^{\frac{1}{q}}\delta_{tk}+\sqrt{\left[t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}\right]\delta_{tk}}\right\}}{t-\big(3+2^{\frac{2}{q}-2}-t\big)\delta_{tk}}
     +1\right)\nonumber\\
&\quad\times\frac{2^{\frac{2}{q}-1}\sigma_{k}(D^*x_0)_q}{k^{\frac{1}{q}-\frac{1}{2}}}.
\end{align}

If $tk$ is not an integer, set $t^{\prime}:=\frac{\lceil tk\rceil}{k}$, and then we can prove the above result by working on $\delta_{t^{\prime}k}$.

\end{proof}
\end{appendix}

