	The goal of this Section is to prove the following theorem.

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\ThmCertifProductPrimes*
	%%%%%%%%%%%%%%%%%%%%%%%%%%

	Before proving Theorem~\ref{thm:certif_product_primes}, let us show the following result:

	\begin{lemma}
		\label{lem:certif_modulo}
		Let $m, t \in \mathbb{N}$ and $m \geqslant 2$. Certifying that the length a path on~$n$ vertices satisfies \mbox{$n \equiv t \mod m$} can be done with certificates of size $O(\log m)$.
	\end{lemma}

	\begin{proof}
		The certificate given by the prover to the vertices consists in two parts. For each vertex~$u$, we denote the first part of its certificate by $\textsf{Orientation}[u]$, and the second part by $\textsf{Distance}[u]$. The prover chooses an endpoint of the path, and for each vertex $u$, we denote by $d_u$ its distance to this endpoint. In $\textsf{Orientation}[u]$, the prover writes $d_u \mod 3$. In $\textsf{Orientation}[u]$, the prover writes $d_u \mod m$. This certificate has size $O(\log m)$.

		To check the correctness of the certificates, each vertex first checks the correctness of the part $\textsf{Orientation}$. To do so, if $u$ has degree~$2$, it simply checks that it has a neighbor~$v$ such that $\textsf{Orientation}[v] = \textsf{Orientation}[u]+1 \mod 3$, and a neighbor $w$ such that $\textsf{Orientation}[w] = \textsf{Orientation}[u]-1 \mod 3$. And if $u$ has degree~$1$ and has a neighbor $v$, it checks that either $\textsf{Orientation}[u] = 0$ and $\textsf{Orientation}[v]=1$ (in this case we say that $u$ is the \emph{beginning endpoint}), or $\textsf{Orientation}[v] = \textsf{Orientation}[u]-1$ (in this case we say that $u$ is the \emph{final endpoint}). This part of the certificates gives an orientation of the path to the vertices: for two neighbors~$u$ and~$v$, we say that $u$ is a~\emph{predecessor} of~$v$ (resp. a \emph{successor}) if $\textsf{Orientation}[u]=\textsf{Orientation}[v]-1 \mod 3$ (resp. $\textsf{Orientation}[u]=\textsf{Orientation}[v]+1 \mod 3$). Then, to check the correctness of the part $\textsf{Distance}$, each degree-$2$ vertex checks that its predecessor~$v$ satisfies $\textsf{Distance}[v] = \textsf{Distance}[u]-1 \mod m$, and its successor~$w$ satisfies $\textsf{Distance}[w] = \textsf{Distance}[u]+1 \mod m$. If $u$ is the beginning endpoint, it checks that $\textsf{Distance}[u] = 0$. If $u$ is the final endpoint and has a predecessor~$v$, it checks that $\textsf{Distance}[u] = \textsf{Distance}[v] + 1 \mod m$, and that $\textsf{Distance}[u] = t$.
	\end{proof}

	\begin{remark}
		\label{rem:certif_modulo}
		For every $m, t \in \mathbb{N}$ with $m \geqslant 2$, we can also certify that the length~$n$ of a path satisfies $n \not\equiv t \mod m$ with certificates of size $O(\log m)$, with the same proof (just by replacing $\textsf{Distance}[u] = t$ by $\textsf{Distance}[u] \neq t$ at the end). In particular, with certificates of size $O(\log m)$, we can certify that~$m$ divides~$n$, or that~$m$ does not divide~$n$.
	\end{remark}


	Finally, let us introduce some notations and give some useful properties.
	For every $k \geqslant 1$, let us denote by $p_k$ the $k$-th prime number (i.e. $p_1 = 2, p_2 = 3, p_3 = 5$...), and let $a_k$ be the product of the $k$ first prime numbers:
	$a_k := \prod_{i=1}^{k}p_i$. Let $S \subseteq \mathbb{N}$ be the set $\{a_k \; | \; k \geqslant 1\}$.

	\begin{lemma}{\cite{HardyW79}}
		\label{lem:bound}
		We have $p_k = \Theta(k \log k)$ and $a_k = 2^{k \log k (1 + o(1))}$.
	\end{lemma}

	\begin{lemma}
		\label{lem:small_prime_certif}
		There exists $c > 0$ such that, for every even integer $n \geqslant 2$, there exists $k \leqslant c \log n$ such that $p_k$ divides~$n$ and $p_{k+1}$ does not divide~$n$.
	\end{lemma}

	\begin{proof}
		Let $n$ be an even integer and let $k$ be the smallest integer such that $p_k$ divides $n$ and $p_{k+1}$ does not divide $n$ (which exists because $n$ is divisible by~$p_1 = 2$). Then, $n$ is divisible by $a_k$, so $a_k \leqslant n$. Using Claim~\ref{lem:bound}, we get $2^{k \log k (1 + o(1))} \leqslant n$, so $k \log k (1+o(1)) \leqslant \log n$, and the result follows.
	\end{proof}

	\begin{lemma}
		\label{lem:not_equiv}
		Let $1 \leqslant s < t$. There exists $m \leqslant \lceil \log t \rceil$ such that $s \not\equiv t \mod m$.
	\end{lemma}

	\begin{proof}
		By contradiction, assume that for all $m \leqslant \lceil \log t \rceil$, we have $s \equiv t \mod m$. Then, by the Chinese remainder theorem, we get $s \equiv t \mod p$, where $p$ is the least common multiple of $1, 2, \ldots, \lceil \log t \rceil$. It is well-known that this least common multiple is at least~$t$, so we have $1 \leqslant s < t \leqslant p$. Together with $s \equiv t \mod p$, this implies $s = t$, which contradicts the assumption $s < t$.
	\end{proof}

	\begin{proposition}
		\label{prop:main}
		Let $n \geqslant 1$, and $c$ be the constant of Lemma~\ref{lem:small_prime_certif}. Then, $n \notin S$ if and only if at least one of the three following conditions is satisfied:
		\begin{enumerate}
			\item n is odd, or
			\item there exists $1 \leqslant \ell < k \leqslant c \log n$ such that $p_\ell$ does not divide~$n$ and $p_k$ divides~$n$, or
			\item there exists $1 \leqslant k \leqslant c \log n$ and $1 \leqslant m \leqslant \lceil \log n \rceil$ such that $p_k$ divides~$n$, $p_{k+1}$ does not divide~$n$ and $n \not\equiv a_k \mod m$.
		\end{enumerate}
	\end{proposition}

	\begin{proof}
		First, assume that one of the three conditions is satisfied. If condition~1. holds, $n$ is odd, so $n \notin S$ because $S$ contains only even integers. If condition~2. holds, then $n \notin S$ because all the integers in~$S$ which are divisible by~$p_k$ are also divisible by $p_\ell$ for all $\ell \leqslant k$. If condition~3. holds, then $n \notin S$, because the only integer in $S$ which is divisible by~$p_k$ and not by~$p_{k+1}$ is~$a_k$.

		Conversely, assume that $n \notin S$, and let us show that at least one of the three conditions is satisfied. Assume that conditions~1. and~2. are not satisfied, and let us show that condition~3. holds. Since condition~1. is not satisfied, $n$ is even, so by Lemma~\ref{lem:small_prime_certif}, there exists $k \leqslant c \log n$ such that $p_k$ divides~$n$ and $p_{k+1}$ does not divide~$n$. Since condition~2. is not satisfied, $n$ is divisible by~$a_k$, so $a_k < n$ (this inequality is strict because, by assumption, $n \notin S$). Finally, by Lemma~\ref{lem:not_equiv}, there exists $m \leqslant \lceil \log n \rceil$ such that $n \not\equiv a_k \mod m$, so condition~3. is satisfied. 
	\end{proof}

	We are now able to prove Theorem~\ref{thm:certif_product_primes}.

	\begin{proof}[Proof of Theorem~\ref{thm:certif_product_primes}]
		Recall that we assume that the input graph is a path $P$. 
		Let $\P$ be the property of being a path whose length is \emph{not} in~$S$.
		First, observe that $\P$ cannot be certified with constant-size certificates. Indeed, properties on paths that can be certified with constant size-certificates are paths whose length is in a set that is eventually periodic (the most simple proof for it uses Chrobak normal form, see Observation~\ref{obs:periodic}), and the set $\overline{S}$ is not.
		Now, let us show that $\P$ can be certified with certificates of size $O(\log \log n)$.

		Let $n \geqslant 1$. If $n \notin S$, the prover certifies that at least one of the three conditions of Proposition~\ref{prop:main} is satisfied. More precisely:
		\begin{itemize}
			\item if $n$ is odd, the prover certifies it. By Lemma~\ref{lem:certif_modulo}, this needs~$O(1)$ bits.
			\item if there exists $1 \leqslant \ell < k \leqslant c \log n$ such that $p_k$ divides~$n$ and $p_\ell$ does not divide~$n$, the prover writes $k$ and $\ell$ in the certificate of each vertex, and certifies that $p_k$ divides~$n$ and that $p_\ell$ does not divide~$n$. Since $k \leqslant c \log n$ and $p_k = \Theta(k \log k)$, by Lemma~\ref{lem:certif_modulo} and Remark~\ref{rem:certif_modulo}, this needs~$O(\log \log n)$~bits.
			\item if there exists $1 \leqslant k \leqslant c \log n$ and $1 \leqslant m \leqslant \lceil \log n \rceil$ such that $p_k$ divides~$n$, $p_{k+1}$ does not divide~$n$ and $n \not\equiv a_k \mod m$, the prover writes~$k$ and~$m$ in the certificate, certifies that $p_k$ divides~$n$, $p_{k+1}$ does not divides~$n$ and that $n \not\equiv a_k \mod m$. By Lemma~\ref{lem:certif_modulo} and Remark~\ref{rem:certif_modulo}, this needs~$O(\log \log n)$~bits.
		\end{itemize}

		The verification of the vertices just consists in checking that the condition given by the prover is indeed satisfied, with the verification procedure of Lemma~\ref{lem:certif_modulo}. Note that the vertices do not need to check the bounds on~$k$ and~$m$ for conditions~2. and~3., because if condition~2. or~3. is satisfied with larger~$k$ or~$m$, it also implies that $n \notin S$ (and then $P \in \P$ and $P$ can be also accepted with certificates of size $O(\log \log n)$).
		%\textcolor{red}{N. I am not sure to have really understood the previous sentence; What do you mean exactly?} \textcolor{blue}{S. : ce que je veux dire c'est que peut-être que pour certifier le point 3., le prover donne un $k$ et un $m$ trop grands (codés sur plus que $\log \log n$ bits), mais ce n'est pas grave car : si tous les sommets acceptent (même avec un trop gros $k$ et $m$) alors la propriété est vérifiée, et si la propriété est vérifiée il existe des petites valeurs de $k$ et $m$ qui font accepter tous les sommets}. 
		These bounds on~$k$ and~$m$ are only useful to get an upper bound on the size of the certificates.
	\end{proof}



