	\subsection{Proof of Theorem~\ref{thm:cycles}}

	All this subsection is devoted to the proof of Theorem~\ref{thm:cycles}.

	\medskip

	Let $c > 12$ and $N \in \N$. Let $S$ be the set of lengths of cycles in~$\P$.  Assume by contradiction that there exists a property $\P$ such that, for every integer $n \geqslant N$ satisfying $\P$, the cycle of length $n$ is accepted with certificates of size~$s(n)$, where $s(n) \leqslant \left\lfloor
	\frac{\log n}{c}\right\rfloor$, and that a constant number of certificates are not sufficient to certify~$\P$. 

	For every $k \geqslant 1$, let $C_k$ be the set of certificates of size~$k$, and let $S_k$ be the subset of $S$ corresponding to the cycles accepted with certificates in~$C_k$.
	Note that $|C_k| = 2^k$, and that we have $S = \bigcup_{k \in \N} S_k$.
	Let $\G_k = (V_k,E_k)$ be the directed graph where $V_k := C_k^2$ and for all $a, b, c \in C_k$, there is an edge in $E_k$ between $(a,b)$ and $(b,c)$ if and only if a degree-2 vertex with certificate $b$ has a neighbor with certificate~$a$ and another neighbor with certificate~$c$ accepts (and there are no other edges in~$E_k$, that is there is no edge between $(a,b)$ and $(c,d)$ if $b \ne c$). 
	The directed graph $\G_k$ has $2^{2k}$ vertices. 



	\begin{claim}
		\label{claim:setcycle}
		For every integer $n \geqslant 3$, $n \in S_k$ if and only there exists a closed walk of length~$n$ in $\G_k$.
	\end{claim}

	\begin{proof}
		If $n \in S_k$, there exists an assignment of certificates $c_1, \ldots, c_n$ to the vertices of a $n$-vertex cycle such that every vertex accepts. For every $i \in \{1, \ldots, n\}$, since the vertex with certificate~$c_i$ accepts and has two neighbors with certificates $c_{i-1}$ and $c_{i+1}$ (where $i-1$ and $i+1$ are taken modulo~$n$), by definition there is an edge in $\G_k$ from $(c_{i-1}, c_i)$ to $(c_i, c_{i+1})$. So this gives an closed walk of length $n$ in~$\G_k$. Conversely, if there exists a closed walk $(c_1, c_2), (c_2, c_3), \ldots, (c_n,c_1)$ in $\G_k$, by definition all the vertices of the cycle of length~$n$ with certificates $c_1, \ldots, c_n$ accept, so $n \in S_k$.
	\end{proof}

	By Corollary~\ref{cor:PNT}, there exists $k_0\in \N$ such that for all $k \geqslant k_0$, $\pi_c(k) > k 2^{2k}$.

	Since $S$ is not accepted with a constant number of certificates, the set $X \subseteq \N$ of integers $k \in \N$ such that $S_k \not \subseteq \bigcup_{1 \leqslant i < k}S_i$ is infinite. For $k \in X$, let $n_k$ be the smallest integer $S_k \setminus \bigcup_{1 \leqslant i < k}S_i$. Finally, let us fix an integer integer~$k \in X$, such that $k \geqslant k_0$ and $n_k \geqslant N$ (such an integer $k \in X$ exists because $X$ is infinite and for all distinct $k, k' \in X$ we have $n_k \neq n_{k'}$).

	\begin{claim}
		\label{claim:lower_bound_n}
		We have $n_k \geqslant 2^{ck}$.
	\end{claim}

	\begin{proof}
		By definition of $s(n_k)$, we have $n_k \in S_{s(n_k)}$. Since $n_k \in S_k \setminus \bigcup_{1 \leqslant i < k}S_i$, it follows that $s(n_k) \geqslant k$. Moreover, by assumption, $s(n_k) \leqslant \left \lfloor \frac{\log n_k}{c} \right \rfloor$. So $n_k \geqslant 2^{ck}$.
	\end{proof}

	Since $n_k \in S_k$, by Claim~\ref{claim:setcycle}, there is a closed walk of length~$n_k$ in $\G_k$. Let us consider the strongly connected component $\G_k'$ of $\G_k$ containing this closed walk. Let $t$ be the number of elementary cycles in $\G_k'$ that we denote by $\C_1, \ldots, \C_t$, and let $\ell_1, \ldots, \ell_t$ be their lengths. Let $d = \gcd(\ell_1, \ldots ,\ell_t)$. We have $d \leqslant 2^{2k}$, because we have $\ell_i \leqslant 2^{2k}$ for every $i \in \{1, \ldots, t\}$ (since $\G_k$ has size $2^{2k}$).

	\begin{claim}
		\label{claim:elementary}
		Let $\C$ be a closed walk in $\G_k'$, and let $\ell$ be its length. There exists $b_1, \ldots, b_t \in \N$ such that $\ell = \sum_{i=1}^{t} b_i \ell_i$. Thus, $d$ divides~$\ell$. In particular, $d$ divides~$n_k$.
	\end{claim}

	%\textcolor{teal}{C'est un peu troublant d'utiliser encore des $a_i$ alors que ce n'est pas une application du lemme 16.}

	\begin{proof}
		Let us prove this result by induction on the length of $\C$.
		The base case includes all elementary cycles: if $\C$ is an elementary cycle, there exists $j \in \{1, \ldots, t\}$ such that $\ell = \ell_j$, so the result is trivially true. Assume now that $\C$ is not an elementary cycle, and consider the shortest closed subwalk~$\C'$ of~$\C$. Then, $\C'$ is an elementary cycle (otherwise it would not be the shortest subwalk of~$\C$), so $\C' \in \{\C_1, \ldots, \C_t\}$ and its length is equal to $\ell_j$ for some $j \in \{1, \ldots, t\}$.
		Let us denote by $\C \setminus \C'$ the closed walk obtained  by removing from $\C$ the steps of $\C'$. The length of $\C \setminus \C'$ is $\ell - \ell_j$. Finally, apply the induction hypothesis to the closed walk $\C \setminus \C'$, to obtain integers $b_1, \ldots, b_t \in \N$ such that $\ell - \ell_j = \sum_{i=1}^t b_i \ell_i$. The result follows.
		%\textcolor{teal}{Petits soucis de fontes + trop rapide.}
	\end{proof}

	\begin{claim}
		\label{claim:lengthcycle}
		Let $m \in \N$ be such that $d$ divides~$m$, and $m \geqslant 2^{4k+1}$. Then, there exists a closed walk in $\G_k'$ of length~$m$. Thus, $m \in S_k$.
	\end{claim}

	\begin{proof}
		First, we construct greedily a closed walk~$\C_0$ in~$\G_k'$ that passes through all the vertices of $\G_k'$ (it exists, because $\G_k'$ is strongly connected).
		%Since $\G_k'$ has at most $2^{2k}$ vertices, there exists such a closed walk~$\C_0$ of length $\ell_0 \leqslant 2^{4k}$.
		For every $u, v \in V(\G_k')$, the shortest directed path from~$u$ to~$v$ has length at most the number of vertices of $\G_k$ which is $2^{2k}$. Thus, there exists a closed walk~$\C_0$ of length $\ell_0 \leqslant (2^{2k})^2 = 2^{4k}$ that passes through all the vertices.
		%\textcolor{teal}{Justifier}.    
		By Claim~\ref{claim:elementary}, $d$ divides~$\ell_0$, so $d$ divides $m-\ell_0$. Furthermore, $m-\ell_0 \geqslant 2^{4k}$. Since we have $\max_{1 \leqslant i \leqslant t} \ell_i \leqslant 2^{2k}$, we can apply Lemma~\ref{lem:bezout} to get the existence of integers $a_1, \ldots, a_t \in \N$ such that $m - \ell_0 = \sum_{i=1}^{t} a_i \ell_i$. Finally, to construct a closed walk in $\G_k'$ of length $m = \ell_0 + \sum_{i=1}^{t} a_i \ell_i$, we attach $a_i$ times the elementary cycle $\C_i$ to the closed walk $\C_0$ for every $i \in \{1, \ldots, t\}$ (this is possible, because $\C_0$ passes through all the vertices). By Claim~\ref{claim:setcycle}, we have $m \in S_k$.
	\end{proof}

	Let us now combine these arguments to prove Theorem~\ref{thm:cycles}. Before giving the technical details, let us explain the intuition. Let us denote by $d$ the $d:=gcd$ of all the lengths of cycles in $S_k$. Since $\mathcal{G}_k$ has size $2^{2k}$, Lemma~\ref{claim:lengthcycle} ensures that all the cycles of length $r \cdot d$ are in $\mathcal{P}$ when $r$ is large enough (but small compared to $n_k$). Thus there exist many prime numbers $p$ such that $pd$ are in $\mathcal{P}$ and $pd \le n_k$. By definition of $n_k$, at least two of them can be certified with the same set of bits and we can obtain a contradiction. Let us now formalize the argument.

	Recall that $k$ is an integer such that $k \geqslant k_0$ and $n_k \geqslant N$.
	Let $p$ be a prime number such that $2^{4k+1} < p \leqslant 2^{k(c/2-2)}$. By Claim~\ref{claim:lengthcycle}, we have $pd \in S_k$.
	Moreover, since $p \leqslant 2^{k(c/2-2)}$ and $d \leqslant 2^{2k}$, we have $pd \leqslant 2^{kc/2}$, that is, $pd \leq \sqrt{n_k}$ using Claim~\ref{claim:lower_bound_n}.
	Since $n_k$ is the smallest integer in $S_k \setminus \bigcup_{1 \leqslant i<k} S_i$, we have $pd \in \bigcup_{1 \leqslant i<k} S_i$. For every $i \in \{1, \ldots, k-1\}$, let $X_i$ be the set of prime numbers~$p \in \{2^{4k+1}+1, \ldots, 2^{k(c/2-2)}\}$ such that $pd \in S_i$.
	Since there are $\pi_c(k)$ prime numbers in $\{2^{4k+1}+1, \ldots, 2^{k(c/2-2)}\}$ and we have $\pi_c(k) > k2^{2k}$, by the pigeonhole principle there exists $i < k$ such that $|X_i| > 2^{2k}$. Let us fix this index~$i$.

	For every $p \in X_i$, since $pd \in S_i$, there exists a closed walk~$\C^{(p)}$ of length~$pd$ in $\G_i$. Since~$|X_i| > 2^{2k}$, and since $\G_i$ has $2^{2i}$ vertices and $i < k$, again by the pigeonhole principle there exist $p,q \in X_i$ such that $\C^{(p)}$ and $\C^{(q)}$ have a vertex in common. Since $\C^{(p)}$ has length $pd$, $\C^{(q)}$ has length $qd$, and these two cycles have a vertex in common, for every $a,b \in \N$, there exists a closed walk of length $apd + bqd$ in $\G_i$ (obtained by starting from a vertex $u \in \C^{(p)} \cap \C^{(q)}$, taking $a$ times $\C^{(p)}$ and then $b$ times $\C^{(q)}$).
	Thus, for every $a, b \in \N$, $apd + bqd \in S_i$.

	Finally, since $\gcd(pd,qd) = d$ (because $p$ and $q$ are two distinct prime numbers), since $pd, qd \leqslant \sqrt{n_k}$, and since $n_k$ is divisible by~$d$ by Claim~\ref{claim:elementary}, we can apply Lemma~\ref{lem:bezout} which states that there exists $a,b \in \N$ such that $apd + bpd = n_k$. So $n_k \in S_i$, which a contradiction, because by assumption $n_k \in S_k \setminus \bigcup_{1 \leqslant i < k} S_i$. This concludes the proof of Theorem~\ref{thm:cycles}.

