			Just by counting directly from the definition, the automaton $\A_k$ has at most $2r(2^k|\Sigma|)^{2r}$ states.
			Moreover, it accepts the language $S_k^{\geqslant 2r}$. Indeed, let us consider a labeled path having~$t \geqslant 2r$ vertices, which is in $S_k^{\geqslant 2r}$. Let $\ell_0, \ldots, \ell_{t-1}$ be the labels of the vertices, and let $c_0, \ldots, c_{t-1}$ be a certificate assignment that makes every vertex accept. Then, by definition of~$\A_k$:
			\begin{itemize}
				\item there are transitions from~$i$ to~$((c_0,\ell_0) \ldots ,(c_{2r-1},\ell_{2r-1}))$ labeled by $\ell_0, \ldots, \ell_{r-1}$
				\item for every $j \in \{0, \ldots, t-2r-1\}$, there is a transition from $((c_j, \ell_j), \ldots, (c_{j+2r-1}, \ell_{j+2r-1}))$ to $((c_{j+1}, \ell_{j+1}), \ldots, (c_{j+2r}, \ell_{j+2r}))$ labeled by $\ell_{j+r}$
				\item there are transitions from~$((c_{t-2r},\ell_{t-2r}), \ldots, (c_{t-1}, \ell_{t-1}))$ to~$f$ labeled by~$\ell_{t-r}, \ldots, \ell_{t-1}$
			\end{itemize}

			Thus, there is an accepting run in~$\A_k$ that accepts $\ell_0, \ldots, \ell_{t-1}$. And conversely, any accepting run in $\A_k$ can be converted in a path in $S_k^{\geqslant 2r}$ (an assignment of the certificates that makes every vertex accept is given by the states of the accepting run). 
		\end{proof}



		Now, let $X$ be the set of integers $k \in \N$ such that~$S_{k}^{\geqslant 2r} \setminus \bigcup_{1 \leqslant i<k}S_i^{\geqslant2r}$ is non-empty.
		The set~$X$ in infinite: indeed, assume by contradiction that~$X$ is finite. Then, there exists $k \in \N$ such that $S^{\geqslant 2r} = \bigcup_{i \leqslant k}S_i^{\geqslant 2r}$. In other words, it means that constant-size certificates are sufficient to accept all the labeled paths in~$S$ of length at least~$2r$. Since there is only a finite number of labeled paths in~$S$ of length at most~$2r$, it means that constant-size certificates are sufficient to certify~$S$, which is not the case by assumption. So~$X$ is infinite.

		For every $k \in X$, let $n_k$ be the length of a smallest word in $S_{k}^{\geqslant 2r} \setminus \bigcup_{1 \leqslant i<k}S_i^{\geqslant2r}$. Note that we have $\lim_{k \to +\infty, k \in X} n_k = +\infty$. Indeed, for every $n \in \N$, there is only a finite number of $k \in X$ such that $n_k = n$, because there are only a finite number of words of length~$n$.
		Let $k_0 \in \N$ be such that, for every $k \in X$ and $k \geqslant k_0$, we have $n_k \geqslant \max(N,2r)$. For such an integer~$k$, since $n_k \in S_{s(n_k)}^{\geqslant 2r}$, we have $s(n_k) \geqslant k$.

		Let $k \in X$ such that $k \geqslant k_0$. By Claim~\ref{claim:sk_regular}, the set $S_k^{\geqslant2r}$ is a regular language in $\Sigma^\ast$, recognized by an automaton~$\A_k$ that has $M_k \leqslant 2r(2^k|\Sigma|)^{2r}$ states.
		By Lemma~\ref{lem:automata}, there exists an automaton~$\A_k'$ that accepts $S_{k}^{\geqslant 2r} \setminus \bigcup_{1 \leqslant i<k}S_i^{\geqslant2r}$ and which has at most $M_k \cdot 2^{\left(\sum_{i=1}^{k-1}M_i\right)}$ states.
		Let us prove the following claim:

		\begin{claim}
			\label{claim:bound_k}
			We have $k \geqslant \frac{\log \log n_k}{2r} + O_{r, |\Sigma|}(1)$
		\end{claim}

		\begin{proof}
			Since $n_k$ is the smallest word accepted by~$\A_k'$, it is smaller than the number of states of $\A_k'$,  which is at most~$M_k \cdot 2^{\left(\sum_{i=1}^{k-1}M_i\right)}$. Moreover, we also know that $M_i \leqslant 2r(2^i|\Sigma|)^{2r}$ for every $i \in \N$, so we have $\sum_{i=1}^{k-1}M_i \leqslant 2r|\Sigma|^{2r}2^{2kr}$. Thus:
			\begin{align*}
				n_k 
				&\leqslant M_k \cdot 2^{\left(\sum_{i=1}^{k-1}M_i\right)} \\
				&\leqslant 2r|\Sigma|^{2r}2^{2kr+2r|\Sigma|^{2r}2^{2kr}}\\
				&\leqslant 2r|\Sigma|^{2r}2^{(2r+1)|\Sigma|^{2r}2^{2kr}}\\
			\end{align*}
			By taking the logarithm of the previous equation, we obtain:
			$$\log n_k \leqslant O_{r, |\Sigma|}(1) + O_{r,|\Sigma|}(1)2^{2kr}$$
			Finally, again by taking the logarithm, we obtain:
			$$2kr \geqslant \log\left(\frac{\log n_k + O_{r,|\Sigma|}(1)}{O_{r,|\Sigma|}(1)} \right)$$
			which finally gives $k \geqslant \frac{\log \log n_k}{2r} + O_{r,|\Sigma|}(1)$.
		\end{proof}

		We can finally combine Claim~\ref{claim:bound_k} with the inequality $s(n_k) \geqslant k$ to obtain that $s(n_k) \geqslant \frac{\log \log n_k}{2r} + O_{r,|\Sigma|}(1)$ for every $k \in X$ such that $k \geqslant k_0$. This is a contradiction with the fact that $c>2$ and $s(n_k) = \left\lfloor\frac{\log \log n_k}{cr}\right\rfloor$ since $n_k \geqslant N$.
		This concludes the proof and shows that $\P$ can be certified with constant-size certificates.
	\end{proof}


