	Let us now explain how we can define such an automaton with the certification procedure.
	Informally speaking, if a vertex $r$ accepts with two neighbors $u,v$ and a tree~$T$ rooted on~$r$, with certificates $c_1,c_2,c_3$ assigned to $u,r,v$ respectively (and some other certificates assigned to the vertices of~$T$), then we add a transition from the state~$(c_1,c_2)$ to the state~$(c_2,c_3)$ labeled $T$.
	Let us formalize this definition.

	For every $k \in \N$, we construct the following non-deterministic automaton $\A_k$. The set of states consists of all pairs of certificates of size~$k$ plus two additional states, $i$ and~$f$. So the set of states is: $C_k^2 \cup \{i,f\}$. There is a single initial state, which is~$i$, and a single final state, which is~$f$. The transitions\footnote{The three cases correspond to the fact that a node can be at the beginning, in the middle or at the end of a path going from a node to another.} are the following:
	\begin{itemize}
		\item \textit{(Middle node transitions)} for every $c_1, c_2, c_3 \in C_k$ and every rooted tree~$T$, consider the tree $T'$ obtained by taking a copy of $T$ and adding two additional neighbors~$u$ and~$v$ to the root~$r$ of~$T$ (and seeing $T'$ as a non-rooted tree). We create a transition from $(c_1,c_2)$ to $(c_2,c_3)$ labeled by~$T$ if and only if there exists a certificate assignment $c : V(T') \to C_k$ such that $c(u) = c_1$, $c(r) = c_2$, $c(v) = c_3$, and all the vertices in $V(T') \setminus \{u,v\}$ accept.

		\item \textit{(Initial node transitions)} for every $c_1, c_2 \in C_k$ and every rooted tree~$T$, consider the tree $T'$ obtained by taking a copy of~$T$ and adding one additional neighbor~$v$ to the root $r$ of $T$. We create a transition from $i$ to $(c_1, c_2)$ labeled by~$T$ if and only if there exists a certificate assignment $c : V(T') \to C_k$ such that $c(r) = c_1$, $c(v)=c_2$, and all the vertices in $V(T') \setminus \{v\}$ accept.

		\item \textit{(Final node transitions)} for every $c_1, c_2 \in C_k$ and every rooted tree~$T$, consider the tree $T'$ obtained by taking a copy of~$T$ and adding one additional neighbor~$u$ to the root $r$ of $T$. We create a transition from~$(c_1, c_2)$ to~$f$ labeled by~$T$ if and only if there exists a certificate assignment $c : V(T') \to C_k$ such that $c(u) = c_1$, $c(r)=c_2$, and all the vertices in $V(T') \setminus \{u\}$ accept.

		\item for every rooted tree~$T$, we put a transition from~$i$ to~$f$ labeled by~$T$ if and only if there exists a certificate assignment to the vertices of $T$ (seen as a non-rooted tree) such that all the vertices accept.
	\end{itemize}


	Now, we prove the following result:

	\begin{proposition}
		\label{prop:trees_accepted}
		Let $T$ be a tree. The following are equivalent:

		\begin{enumerate}[label=(\roman*)]
			\item $T \in S_k$
			\item For all $u,v \in V(T)$, $\sigma(T,u,v)$ is accepted by~$\A_k$.
			\item There exist $u,v \in V(T)$ such that $\sigma(T,u,v)$ is accepted by~$\A_k$.
		\end{enumerate}
	\end{proposition}

	\begin{proof}
		Let us first prove the implication $(i) \Rightarrow (ii)$. Assume that $T \in S_k$. Then, there exists an assignment of certificates in~$C_k$ to the vertices of~$T$ such that every vertex accepts. Let $u,v \in V(T)$, and let $T_1, \ldots, T_m := \sigma(T,u,v)$.
		If $u = v$, then $m=1$ and $T_1$ is the tree $T$ rooted at $u$. By definition of $\A_k$, there is a transition from~$i$ to~$f$ labeled by~$T_1$, and the result follows. If $u \neq v$, for every $i \in \{1, \ldots, m\}$, let~$w_i$ be the vertex in~$T$ corresponding to the root of~$T_i$ (with $w_1 = u$ and $w_m = v$), and let $c_i$ be the certificate assigned to~$w_i$. 
		By definition of~$\A_k$, there is a transition from $i$ to $(c_1, c_2)$ labeled by $T_1$ (since $w_1$ accepts), there is a transition from $(c_{m-1}, c_m)$ to $f$ labeled by $T_m$ (since $w_m$ accepts), and for every $i \in \{2, \ldots, m-1\}$ there is a transition from $(c_{i-1}, c_i)$ to $(c_i, c_{i+1})$ labeled by $T_i$ (since $w_i$ accepts). Thus, $\sigma(T,u,v)$ is accepted by $\A_k$.

		The implication $(ii) \Rightarrow (iii)$ is direct. 

		Let us finally prove $(iii) \Rightarrow (i)$. 
		Assume that there exist $u,v \in V(T)$ such that $\sigma(T,u,v) = T_1, \ldots, T_m$ is accepted by~$\A_k$. Let us show that there exists an assignment of certificates in~$C_k$ to the vertices of~$T$ such that each vertex accepts. If $m=1$, then $T_1$ is the tree~$T$ rooted at~$u$, and there is a transition $i \xrightarrow{T_1} f$ in $\A_k$. By definition of the transitions, there exists a certificate assignment to the vertices of~$T$ such that all the vertices accept. Assume now that $m \geqslant 2$. Since $\sigma(T,u,v)$ is accepted by~$\A_k$, there exists a sequence of transitions in $\A_k$ of the form:

		$$i \xrightarrow{T_1} (c_1, c_2) \xrightarrow{T_2} \;\ldots\; \xrightarrow{T_{m-1}} (c_{m-1}, c_m) \xrightarrow{T_m} f$$

		For every $i \in \{1, \ldots, m\}$, let $w_i$ be the vertex in~$T$ corresponding to the root of $T_i$.
		For every $i \in \{1, \ldots, m\}$, we assign the certificate $c_i$ to $w_i$. Then, since there is the transition $i \xrightarrow{T_1} (c_1,c_2)$ in~$\A_k$, there exists an assignment of certificates to the vertices of~$T_1$ such that $w_1$ and all the vertices in~$T_1$ accept. For every $i \in \{2, \ldots, m-1\}$, since there is the transition $(c_{i-1},c_i) \xrightarrow{T_i} (c_i, c_{i+1})$ in $\A_k$, there exists an assignment of certificates to the vertices of~$T_i$ such that $w_i$ and all the vertices in~$T_i$ accept. Finally, since there is the transition $(c_{m-1},c_m) \xrightarrow{T_m} f$ in $\A_k$, there exists an assignment of certificates to the vertices of~$T_m$ such that $w_m$ and all the vertices in~$T_m$ accept. So $T \in S_k$.
	\end{proof}


	\begin{corollary}
		\label{cor:trees_accepted}
		For every $k \in \N$, the language over the alphabet of rooted trees accepted by~$\A_k$ is equal to $\{\sigma(T,u,v) \; | \; T \in S_k, u,v \in V(T)\}$, that is, to the set of all the parsings of the trees in~$S_k$.
	\end{corollary}

	\begin{proof}
		If~$T \in S_k$, by Proposition~\ref{prop:trees_accepted} we know that $\sigma(T,u,v)$ is accepted by~$\A_k$. Conversely, let $T_1,\ldots, T_m$ be a sequence of rooted trees accepted by~$\A_k$. By Lemma~\ref{lem:parsing}, there exists two vertices $u,v$ of $\tau(T_1, \ldots, T_m)$ such that $T_1, \ldots, T_m = \sigma(\tau(T_1, \ldots, T_m),u,v)$. Finally, again by Proposition~\ref{prop:trees_accepted}, we get $\tau(T_1, \ldots, T_m) \in S_k$.
	\end{proof}


	%In the following, we say that a (non-rooted) tree~$T$ is \emph{accepted by~$\A_k$} if one of the three equivalent conditions of Proposition~\ref{prop:trees_accepted} is satisfied.

	\subsection{Proof of Theorem~\ref{thm:gap-tree-radius-1}}

	We prove Theorem~\ref{thm:gap-tree-radius-1} by contradiction. Assume that $\P$ can not be certified with constant-size certificates. Then, the set $X \subseteq \N$ of integers $k \in \N$ such that $S_k \not \subseteq \bigcup_{1 \leqslant i < k}S_i$ is infinite. For $k \in X$, let $d_k$ be the smallest diameter of a tree in $S_k \setminus \bigcup_{1 \leqslant i < k}S_i$. Since any tree that has diameter~$d_k$ is in the set $S_{s(d_k)}$, we have $s(d_k) \geqslant k$. Let us fix an integer $k \in X$ such that $k > \max_{d \in \{1, \ldots, D-1\}} s(d)$. Since $s(d_k) \geqslant k$ and $k > s(d)$ for all $d < D$, we have $d_k \geqslant D$. Moreover, since $s(d) = \lfloor (\log \log d) / c \rfloor$ for all $d \geqslant D$, the inequality $s(d_k) \geqslant k$ implies that $d_k \geqslant 2^{2^{ck}}$.



	By Corollary~\ref{cor:trees_accepted}, for every $i \in \N$, the language over the alphabet of rooted trees accepted by $\A_i$ is equal to the set of all the parsings of the trees in~$S_i$. Moreover, $\A_i$ has $M_i := 2^{2i}+2$ states. Thus, by Lemma~\ref{lem:automata}, there exists an automaton~$\A_k'$ that accepts the parsings of the trees in $S_k \setminus \bigcup_{i<k} S_i$ has at most $M_k \cdot 2^{\left(\sum_{i=1}^{k-1}M_i\right)} \leqslant 2^{2^{2k}}$ states. Let $T^{(k)} \in S_k \setminus \bigcup_{i < k}S_i$ be a tree such that $T^{(k)}$ has diameter~$d_k$, and among the trees in~$S_k \setminus \bigcup_{i < k}S_i$ having diameter~$d_k$, $T^{(k)}$ has the smallest number of vertices.
	To conclude the proof of Theorem~\ref{thm:gap-tree-radius-1}, it is sufficient to prove the following claim, that contradicts the inequality $d_k \geqslant 2^{2^{kc}}$.

	\begin{claim}
		\label{claim:bound d_k trees}
		We have $d_k \leqslant 2^{2^{2k}}$.
	\end{claim}

	\begin{proof}
		Let $u, v \in V(T^{(k)})$, and let us consider a run accepting $T_1, \ldots, T_m :=\sigma(T^{(k)},u,v)$ in~$\A_k'$. Let us prove that this run does not use the same state twice. Assume by contradiction that it uses the same state~$p$ twice. Then, consider the run obtained by deleting the part between the first and last times that~$p$ is visited. This run accepts another sequence of rooted trees $T'_1, \ldots, T'_{m'}$. By Lemma~\ref{lem:gluing_subsequence}, the diameter of~$\tau(T'_1, \ldots, T'_{m'})$ is less or equal than the diameter of~$T^{(k)}$ which is $d_k$. So the diameter of~$\tau(T'_1, \ldots, T'_{m'})$ is equal to $d_k$ because $T'_1, \ldots, T'_{m'}$ is accepted by~$\A_k$, so $\tau(T'_1, \ldots, T'_{m'}) \in S_k \setminus \bigcup_{i<k} S_i$ and $d_k$ is the smallest diameter of a tree in this set.
		Again by Lemma~\ref{lem:gluing_subsequence}, $\tau(T'_1, \ldots, T'_{m'})$ has strictly less vertices than~$T^{(k)}$, and this is a contradiction by definition of~$T^{(k)}$. Thus, the length of a run in $\A_k'$ accepting $\sigma(T^{(k)},u,v)$ is at most $2^{2^{2k}}$ for every $u,v \in V(T^{(k)})$.
		In particular, by considering $u, v \in V(T^{(k)})$ such that the distance from~$u$ to~$v$ in $T^{(k)}$ is~$d_k$, we obtain that $d_k \leqslant 2^{2^{2k}}$.
	\end{proof}



