	\section{Gap in bounded degree caterpillars with larger radius}
	\label{sec:gap-caterpillar-bounded-deg}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	\begin{theorem}
		\label{thm:gap_caterpillar_bounded_degree}
		Let $\Delta, r \geqslant 1$. Assume that the vertices can see at distance~$r$. Let $\P$ be a property on caterpillars of maximum degree at most~$\Delta$, that can be certified with certificates of size $s(n)$, with $s(n)=o(\log \log n)$. Then, $\P$ can be certified with certificates of size~$O(1)$.
	\end{theorem}


	\begin{remark}
		There exists a constant $c_{r,\Delta}$ such that Theorem~\ref{thm:gap_caterpillar_bounded_degree} remains true by replacing $s(n) = o(\log \log n)$ by $s(n) = \left\lfloor\frac{\log \log n}{c_{r,\Delta}}\right\rfloor$ (because such a constant exists in Theorem~\ref{thm:gap_labeled_distance>1}, and the proof of Theorem~\ref{thm:gap_caterpillar_bounded_degree} is a reduction to Theorem~\ref{thm:gap_labeled_distance>1}), but we did not try to determine and optimize this constant (it depends on the encoding used in the reduction, see the proof of Theorem~\ref{thm:gap_caterpillar_bounded_degree}).
		Moreover, the statement of Theorem~\ref{thm:gap_caterpillar_bounded_degree} also holds if we replace~$n$ by~$d$, the diameter: indeed, in caterpillars of maximum degree~$\Delta$, we have $d \leqslant n \leqslant \Delta (d+1)$.
	\end{remark}

	\begin{proof}
		We will use Theorem~\ref{thm:gap_labeled_distance>1}.
		Let $P$ be a path labeled by $\Sigma:=\{0, \ldots, \Delta\}$, and $G$ be a caterpillar of maximum degree~$\Delta$. For every $u \in V(P)$, let $\ell(u)$ be its label. Let $f(P)$ be the (unlabeled) caterpillar obtained by adding $\ell(u)$ degree-1 neighbors to every $u \in V(P)$. Let $h(G)$ be the labeled path $P$, where~$P$ is the central path of~$G$ and for every $u \in V(P)$ the label of~$u$ is its number of degree-1 neighbors in~$G$. See Figure~\ref{fig:f_caterpillar_bounded_degree} for an example. The following claim is straightforward from the definition of $f$ and $h$:

		\begin{claim}
			\label{claim:fg}
			For every caterpillar~$G$ of maximum degree~$\Delta$, we have $f(h(G))=G$. 
		\end{claim}


