	\section{No gap in $n$ in caterpillars with radius 1}
	\label{sec:no-gap-in-n-caterpillars}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


	%A \emph{caterpillar} is a graph $G$ such that the deletion of all the degree one vertices leaves a path, called the \emph{central path}.
	The goal of this section is to prove the following: 

	%%%%%%%%%%%%%%
	\ThmCaterpillarNoGapinNRadiusOne*
	%%%%%%%%%%%%%%

	To prove this result, we will need the following technical lemma, which basically says that for the function $f$ of the theorem, we can define a sequence of integers such that $f$ applied to the sums of the $d$ first elements is close to $\log d$.  

	\begin{lemma}
		\label{lem:sequence a_i}
		Let $f : \N \to \mathbb{R}$ be a non-decreasing function such that $\lim_{n \rightarrow +\infty}f(n) = +\infty$, $f(2)=1$ and for all integers $1 \leqslant s \leqslant t$ we have $f(t)-f(s) \leqslant \frac{\log t - \log s}{2}$.
		Then, there exists an unbounded sequence of positive integers $(a_i)_{i \geqslant 1}$ such that $a_1=2$ and:

		\begin{equation}
			\label{eq:lemma a_i}
			\forall d \geqslant 1, \;\; \log d \leqslant f\left(\sum_{i=1}^d a_i\right) \leqslant \log d + 1. 
		\end{equation}
	\end{lemma}

	\begin{proof}
		Let us construct the sequence $(a_i)_{i\geqslant 1}$ iteratively: first, we set $a_1 = 2$. Now, let $d \geqslant 2$ and assume that we already defined $a_1, \ldots, a_{d-1}$. We define $a_d$ as being the smallest positive integer such that $\log d \leqslant f\left(\sum_{i=1}^{d} a_i\right)$, which exists because $\lim_{n \rightarrow +\infty}f(n) = +\infty$. Let us prove that this sequence satisfies both inequalities in~(\ref{eq:lemma a_i}).

		The first inequality of~(\ref{eq:lemma a_i}) holds by definition of $(a_i)_{i \geqslant 1}$. Let us prove the second inequality by induction on $d$. It trivially holds for $d=1$ because $f(2)=1$. Now, assume that $d \geqslant 2$, and that it holds for $d-1$. There are two cases:

		\begin{itemize}
			\item If $a_d = 1$, then we have:
			\begin{align*}
				f\left(\sum_{i=1}^d a_i\right)
				& \leqslant f\left(\sum_{i=1}^{d-1} a_i\right) + \log \left(\sum_{i=1}^d a_i\right) - \log \left(\sum_{i=1}^{d-1} a_i\right) \\
				& \leqslant \log(d-1) + 1 + \log \left(1 + \frac{1}{\sum_{i=1}^{d-1}a_i}\right) \quad \text{\footnotesize{(by~(\ref{eq:lemma a_i}) with the induction hypothesis)}}\\
				& \leqslant \log (d-1) + 1 + \log\left(1 + \frac{1}{d-1}\right) \\
				& \leqslant \log d + 1
			\end{align*}

			\item If $a_d \geqslant 2$, by definition of~$a_d$ we know that $f\left(\sum_{i=1}^{d}a_i - 1\right) < \log d$. In this case, we have:
			\begin{align*}
				f\left(\sum_{i=1}^d a_i\right)
				& \leqslant f\left(\sum_{i=1}^{d} a_i - 1\right) + \log \left(\sum_{i=1}^d a_i\right) - \log \left(\sum_{i=1}^{d} a_i - 1\right) \\
				& \leqslant \log d + \log \left(1 + \frac{1}{\sum_{i=1}^{d}a_i - 1}\right) \\
				& \leqslant \log d + 1
			\end{align*}
		\end{itemize}

		Thus, the sequence $(a_i)_{i \geqslant 1}$ satisfies indeed both inequalities of~(\ref{eq:lemma a_i}). Let us prove that this sequence is unbounded. By contradiction, assume that there exists $M > 0$ such that $a_i \leqslant M$ for every $i \geqslant 1$. By plugging $s=2$ in the assumption made on~$f$, we have $f(t) \leqslant \frac{\log t}{2}$ for all integer $t \geqslant 2$, and since $f$ is non-decreasing, we get for all $d \geqslant 1$:
		$$\log d \leqslant f\left(\sum_{i=1}^d a_i\right) \leqslant f(Md) \leqslant \frac{\log (Md)}{2}$$
		which finally gives us $d \leqslant \sqrt{Md}$ for every integer~$d \geqslant 1$ and this is a contradiction. Thus, $(a_i)_{i \geqslant 1}$ is unbounded.
	\end{proof}


	We are now able to prove Theorem~\ref{thm:caterpillars-no-gap-in-n}.

	\begin{proof}[Proof of Theorem~\ref{thm:caterpillars-no-gap-in-n}]
		Without loss of generality, we can assume that $f(2) = 1$ and for all integers $1 \leqslant s \leqslant t$, we have $f(t)-f(s) \leqslant (\log t - \log s)/2$ (else, we can consider the function~$g$ such that $g(n) := (f(n) - f(2))/2+1$ which satisfies it). Let $(a_i)_{i \geqslant 1}$ be the sequence given by Lemma~\ref{lem:sequence a_i}.

		%Let $(a_n)_{n \geqslant 1}$ be a sequence of positive integers, increasing, and such that:

		%$$\forall d \in \N, \;\; \log d \leqslant f\left(d + \sum_{i=1}^d a_i\right)$$

		%Note that such a sequence exists: indeed, it can be constructed iteratively, because if $a_1, \ldots, a_{d-1}$ are already defined, it is possible to define $a_d > a_{d-1}$ such that the inequality above is satisfied, since  $\lim_{n \rightarrow +\infty}f(n) = +\infty$.


