\section{Inversion of $\hat{A}$}\label{inversion}
\begin{align*}
    \hat{A} &= A+u\cdot v^T,\text{ where}\\
    A&=\frac{\gamma}{\beta_0}\cdot 
    diag(\frac{1}{\kappa_1 \overline{S}_1},
    \frac{1}{\kappa_2 \overline{S}_2},\cdots,
