\subsection{Linear Interpolation $\widehat X^N(t)$ of Population State $X^N(t)$} \label{sec:interpolation}
Let $\mathbb T$ denote the set of arrival times of the Poisson processes that govern the timing of strategy revisions for all agents. For any $t \in [t_1, t_2)$, where $t_1, t_2 \in \mathbb T$ are two consecutive arrival times with $t_1 < t_2$, we define a piecewise linear interpolation $\widehat X^N (t)$ of $X^N(t)$ as follows:
\begin{align} \label{eq:x_hat_definition}
  \widehat X^N(t) = X^N(t_1) + \frac{t - t_1}{t_2-t_1} \left( X^N (t_2) - X^N (t_1) \right).
\end{align}
Hence, for each $i \in \{1, \cdots, n\}$ and $t \in (t_1, t_2)$, we can deduce that\footnote{By definition \eqref{eq:x_hat_definition}, $\widehat X^N(t)$ is differentiable at all $t \notin \mathbb T$.}
\begin{align}
  \dot {\widehat{X}}_i^N(t)
  &= \frac{1}{t_2-t_1} \left( X_i^N (t_2) - X_i^N (t_1) \right) \nonumber \\
  &= \lambda (C_i^{\eta, \theta} (\hat p(t-d)) - {\widehat X}_i^N(t)) + \lambda \epsilon_i^N(t),
\end{align}
where $\epsilon_i^N(t) = \frac{1}{\lambda(t_2-t_1)} (X_i^N (t_2) - X_i^N (t_1)) - (C_i^{\eta, \theta} (\hat p(t-d)) - {\widehat X}_i^N(t))$, which is bounded for all $t \in (t_1, t_2)$.

\subsection{Proof of Theorem~\ref{theorem:effect_of_noise}}
We provide a two-part proof.

\paragraph{Derivation of \eqref{eq:effect_of_noise}}
The $\delta$-passivity with surplus $\eta$ (see Definition~\ref{def:delta_passivity_kld_rl}) of EDM \eqref{eq:edm} implies that the $\delta$-storage function $\mathcal S$ satisfies the following relations for all $(p,x) \in \mathbb R^n \times \mathbb X$:
\begin{subequations} \label{eq:delta_passivity_algebraic}
  \begin{align}
    &\nabla_x' \mathcal S (p, x) \mathcal V^{\eta, \theta} (p, x) \leq - \eta \mathcal {V^{\eta, \theta}}' (p, x) \mathcal V^{\eta, \theta} (p, x) \\
    &\nabla_p \mathcal S (p, x) = \mathcal V^{\eta, \theta} (p, x),
  \end{align}
\end{subequations}
where $\mathcal V^{\eta, \theta} (p,x) = C^{\eta, \theta} (p) - x$.
Additionally, by the $\delta$-antipassivity of the game model \eqref{eq:task_allocation_games} (see Definition~\ref{def:delta_antipassivity_task_allocation_game}), the $\delta$-antistorage function $\mathcal L$ satisfies, for all $(q, x) \in \mathbb R_{\geq 0}^n \times \mathbb X$:
\begin{subequations} \label{eq:delta_antipassivity_algebraic}
  \begin{align} 
    &\nabla_q' \mathcal L (q, x) (-\mathcal F(q, x) + w) \leq 0 \label{eq:delta_antipassivity_algebraic_a} \\
    &\nabla_x \mathcal L(q,x) = \mathcal F(q,x) - w.
  \end{align}
\end{subequations}
% where equality in \eqref{eq:delta_antipassivity_algebraic_a} holds if and only if $\mathcal F(q, x) = w$.

Consider time-varying trajectories $q(t) \in \mathbb R_{\geq 0}^n$ and $x(t) \in \mathbb X$, which evolve according to the closed-loop model \eqref{eq:closed_loop_model}, with $x(t) = \widehat X^N(t)$. Using \eqref{eq:delta_passivity_algebraic} and \eqref{eq:delta_antipassivity_algebraic}, the time derivative of the composite Lyapunov-like function $\lambda \mathcal S(p, x) + \mathcal L (q, x)$ is computed as:\footnote{For brevity, we omit the time variable $t$ in the derivation.}
\begin{align*}
  &\frac{\mathrm d}{\mathrm dt} \left( \lambda \mathcal S(p, x) + \mathcal L (q, x) \right) \\
  &= \lambda \nabla_x' \mathcal S(p, x) (\lambda \mathcal V^{\eta, \theta} (p, x) + \lambda (\epsilon^N+\tilde v) ) + \lambda \nabla_p' \mathcal S(p, x) \dot p \\
  &\qquad + \nabla_q' \mathcal L(q, x) (-\mathcal F(q, x) + w + \tilde w^N) + \nabla_x' \mathcal L(q,x) \dot x \\
  &= \lambda^2 \nabla_x' \mathcal S(p, x) \mathcal V^{\eta, \theta} (p, x) + \lambda^2 \nabla_x' \mathcal S(p, x) (\epsilon^N+\tilde v)  \\
  &\qquad + (\dot x - \lambda (\epsilon^N+\tilde v))' \dot p + \nabla_q' \mathcal L(q, x) (-\mathcal F(q, x) + w) \nonumber \\
  &\qquad + \nabla_q' \mathcal L(q, x) \tilde w^N - (\dot p + \tilde w^N)' \dot x \\
  &= \lambda^2 \underbrace{\nabla_x' \mathcal S(p, x) \mathcal V^{\eta, \theta} (p, x)}_{\leq -\eta \mathcal {V^{\eta, \theta}}' (p,x) \mathcal V^{\eta, \theta} (p,x)} + \underbrace{\nabla_q' \mathcal L(q, x) (-\mathcal F(q, x) + w)}_{\leq 0} \\
  &\qquad + \lambda (\lambda \nabla_x \mathcal S(p, x) + \mathcal F(q,x) - w )' (\epsilon^N+\tilde v) \\
  &\qquad + (\nabla_q \mathcal L(q, x) - \lambda \mathcal V^{\eta, \theta}(p,x))' \tilde w^N - 2 \lambda (\epsilon^N+\tilde v)' \tilde w^N.
\end{align*}

Let us define $\alpha_\lambda = \lambda \mathcal S(p(0), x(0)) + \mathcal L (q(0), x(0))$. Then, we obtain the following inequality:
\begin{align*}
  \frac{\int_0^T \mathcal {V^{\eta, \theta}}' (p(t),x(t)) \mathcal V^{\eta, \theta} (p(t),x(t)) \,\mathrm dt}{\alpha_\lambda+\int_0^T |g_\lambda (p(t), x(t), \tilde w^N(t), \epsilon^N(t), \tilde v(t))| \,\mathrm dt}  \leq (\lambda^2 \eta)^{-1},
\end{align*}
where $g_{\lambda}$ is defined as in the statement of the theorem. Substituting $x(t)$ with $\widehat X^N(t)$ completes the derivation.

\paragraph{Derivation of \eqref{eq:choice_function_lipschitz_continuity}}
Following the analysis in \cite{gao2018propertiessoftmaxfunctionapplication}, define the log-sum-exp function $\mathrm{lse}^{\eta, \theta}: \mathbb R^n \to \mathbb R$ associated with \eqref{eq:kld_rl_i} as:
\begin{align*}
  \mathrm{lse}^{\eta, \theta} (p) = \textstyle \eta \ln \left( \sum_{j=1}^n \theta_j \exp (\eta^{-1} p_j) \right), ~ p \in \mathbb R^n.
\end{align*}
The first- and second-order partial derivatives of $\mathrm{lse}^{\eta, \theta} (p)$ with respect to $p$ are given by:
\begin{align*}
  \frac{\partial}{\partial p_i} \mathrm{lse}^{\eta, \theta} (p) = \frac{\theta_i \exp (\eta^{-1} p_i)}{\sum_{j=1}^n \theta_j \exp (\eta^{-1} p_j)} = C_i^{\eta, \theta}(p)
\end{align*}
and
\begin{multline*}
  \frac{\partial^2}{\partial p_i^2} \mathrm{lse}^{\eta, \theta} (p) = \frac{\eta^{-1} \theta_i \exp (\eta^{-1} p_i) }{\sum_{j=1}^n \theta_j \exp (\eta^{-1} p_j)} \\
  - \frac{\eta^{-1} \theta_i^2 \exp (2 \eta^{-1} p_i)}{\left( \sum_{j=1}^n \theta_j \exp (\eta^{-1} p_j) \right)^2}
\end{multline*}
\begin{align*}
  \frac{\partial^2}{\partial p_k \partial p_i} \mathrm{lse}^{\eta, \theta} (p) \!=\! \frac{-\eta^{-1} \theta_k \theta_i \exp (\eta^{-1} p_k) \exp (\eta^{-1} p_i)}{\left( \sum_{j=1}^n \theta_j \exp (\eta^{-1} p_j) \right)^2}, \forall i \neq k.
\end{align*}
Hence, the gradient and Hessian of $\mathrm{lse}^{\eta, \theta} (p)$, respectively, become
\begin{align*}
  \nabla \mathrm{lse}^{\eta, \theta} (p) = C^{\eta, \theta}(p)
\end{align*}
and
\begin{align*}
  \nabla^2 \mathrm{lse}^{\eta, \theta} (p) = \eta^{-1} \left( \mathrm{diag} (C^{\eta, \theta} (p)) - C^{\eta, \theta} (p) {C^{\eta, \theta}}'(p) \right),
\end{align*}
where $\mathrm{diag} (C^{\eta, \theta} (p))$ denotes the diagonal matrix whose diagonal entries are given by the components of $C^{\eta, \theta} (p)$. Consequently, by following similar steps as in the proof of \cite[Proposition~4]{gao2018propertiessoftmaxfunctionapplication}, it holds for any $p,v \in \mathbb R^n$ that
\begin{align*}
  0 \leq v' \nabla^2 \mathrm{lse}^{\eta, \theta} (p) v \leq \eta^{-1} \|v\|_2^2.
\end{align*}
Using \cite[Lemma~5]{gao2018propertiessoftmaxfunctionapplication}, we conclude the function $C^{\eta, \theta}$ is Lipschitz continuous:
\begin{align*}
  \| C^{\eta, \theta} (p) - C^{\eta, \theta} (\hat p) \|_2 \leq \eta^{-1} \|p - \hat p\|_2,
\end{align*}
which yields \eqref{eq:choice_function_lipschitz_continuity}.
\hfill\QED

\subsection{Proof of Proposition~\ref{proposition:mean_variance_of_stationary_distribution}}
To compute the expectation $\mathrm E(X^N(t))$, using $\mu_y^N = \sum_{x \in \mathbb X^N} \mu_x^N P_{xy}^N$, we proceed as follows:
\begin{align*}
  &\sum_{y \in \mathbb X^N} y \mu_y^N \nonumber \\
  &= \sum_{y \in \mathbb X^N} \sum_{x \in \mathbb X^N} y \mu_x^N P_{xy}^N \nonumber \\
  &= \sum_{x \in \mathbb X^N} \! x \mu_x^N \sum_{i=1}^n x_i x_i^\ast \!+\! \sum_{x \in \mathbb X^N} \sum_{j=1}^n \sum_{\substack{i=1 \\ i \neq j}}^n (x \!+\! \frac{1}{N} (e_j \!-\! e_i)) \mu_{x}^N x_i x_j^\ast \nonumber \\
  &= \sum_{x \in \mathbb X^N} \! x \mu_x^N \underbrace{\sum_{i=1}^n \sum_{j=1}^n x_i x_j^\ast}_{=1} \!+\! \frac{1}{N} \sum_{x \in \mathbb X^N} \sum_{j=1}^n \sum_{\substack{i=1 \\ i \neq j}}^n (e_j \!-\! e_i) \mu_{x}^N x_i x_j^\ast
\end{align*}
which implies
\begin{align*}
  \sum_{x \in \mathbb X^N} \sum_{i=1}^n \sum_{j=1}^n e_j \mu_{x}^N x_i x_j^\ast &= \sum_{x \in \mathbb X^N} \sum_{i=1}^n \sum_{j=1}^n e_i \mu_{x}^N x_i x_j^\ast.
\end{align*}
Consequently, we conclude that
\begin{align}
  \sum_{x \in \mathbb X^N} \mu_{x}^N x^\ast = \sum_{x \in \mathbb X^N} \mu_{x}^N x \implies x^\ast = \mathrm E (X^N(t)).
\end{align}

Next, to compute $\sum_{i=1}^n \mathrm{Var}(X_i^N(t))$, we analyze:
\begin{align*}
  &\sum_{y \in \mathbb X^N} (y - x^\ast)'(y - x^\ast) \mu_y^N \nonumber \\
  &= \sum_{y \in \mathbb X^N} \sum_{x \in \mathbb X^N} (y - x^\ast)'(y - x^\ast) \mu_x^N P_{xy}^N \nonumber \\
  &= \sum_{x \in \mathbb X^N} (x - x^\ast)'(x - x^\ast) \mu_x^N \sum_{i=1}^n x_i x_i^\ast \nonumber \\
  &\qquad + \sum_{x \in \mathbb X^N} \sum_{j=1}^n \sum_{\substack{i=1 \\ i \neq j}}^n (x - x^\ast + \frac{1}{N} (e_j - e_i))' \nonumber \\
  &\qquad\qquad\qquad\qquad\qquad (x - x^\ast + \frac{1}{N} (e_j - e_i)) \mu_{x}^N x_i x_j^\ast \nonumber \\
  &= \sum_{x \in \mathbb X^N} (x - x^\ast)'(x - x^\ast) \mu_x^N \nonumber \\
  &\qquad + \frac{1}{N^2} \sum_{x \in \mathbb X^N} \sum_{i=1}^n \sum_{\substack{j=1 \\ j \neq i}}^n \underbrace{(e_j - e_i)'(e_j - e_i)}_{=2} \mu_{x}^N x_i x_j^\ast \nonumber \\
  &\qquad + \frac{2}{N} \sum_{x \in \mathbb X^N} \sum_{i=1}^n \sum_{j=1}^n (x - x^\ast)' (e_j - e_i) \mu_{x}^N x_i x_j^\ast \nonumber \\
  &= \sum_{x \in \mathbb X^N} (x - x^\ast)'(x - x^\ast) \mu_x^N + \frac{2}{N^2} \sum_{x \in \mathbb X^N} (1 - \sum_{i=1}^n x_i x_i^\ast) \mu_{x}^N \nonumber \\
  &\qquad + \frac{2}{N} \sum_{x \in \mathbb X^N} \sum_{i=1}^n \sum_{j=1}^n (x - x^\ast)' (e_j - e_i) \mu_{x}^N x_i x_j^\ast
\end{align*}
which implies
\begin{multline*}
  \frac{2}{N} \sum_{x \in \mathbb X^N} (x - x^\ast)' x \mu_{x}^N - \frac{2}{N} \sum_{x \in \mathbb X^N}  (x - x^\ast)' x^\ast \mu_{x}^N \\
  = \frac{2}{N^2} (1 - {x^\ast}'x^\ast)
\end{multline*}
and we conclude that
\begin{align*}
  &\sum_{x \in \mathbb X^N} (x - x^\ast)'(x - x^\ast) \mu_{x}^N = \frac{1}{N} (1 - {x^\ast}'x^\ast) \\
  \implies& \sum_{i=1}^n \mathrm{Var}(X_i^N(t)) = \frac{1}{N} (1 - {x^\ast}'x^\ast).
\end{align*}
This completes the proof. \hfill\QED

