We now define some functions for the forthcoming result, Proposition~\ref{p.SINR-conditional}, on the successful coverage probability.
%, which we define as the probability that a transmitter is transmitting a message \emph{and} its receiver successfully receives it based on its SINR larger than $\tau>0$. 
For $\kappa$ and $\beta$ parameters of the signal propagation model, as well as the noise power $W$ and SINR threshold  $\tau>0$  (see Section~\ref{s.Network}), we define the functions
\begin{align}\label{e.h1}
h(s,r)&:=1-\frac{1}{\frac{1}{\threshold}(s/r)^{\beta}+1}\quad s,r\ge0,\\
w(s)&:= e^{- (\threshold \noise) (\kappa s)^{\beta}}\quad s\ge0.\label{e.w1}, 
\end{align} 
where  of $s,r>0$. These functions come from a  result that we presented in a previous paper~\cite[Lemma II.1]{blaszczyszyn2020coverage}. %~\ref{l.successprob}; see appendix Section~\ref{s.successprob} for more details. 
%These functions, originally defined in~\cite{linearNN},
They are useful for expressing the SINR coverage probability in deterministic network models with Rayleigh fading and power-law path loss function. 
Furthermore, for a  point $x_i\in\statespace$ define the  functions
\begin{equation}
h_{x_i}(x_j):=h(|x_j-y_i|,|x_i-y_i|),\quad x_j\in\statespace\setminus\{x_i\}
\end{equation}
and constants $W_{x_i}:=w(|x_i-y_i|)$.

%\subsection{SINR coverage probability}
Now consider determinantal scheduler $\Psi$ with kernel~$K$ on the network configuration $\statespace$. We now present a corresponding result, which we first presented in the paper~\cite[Proposition IV.1.]{blaszczyszyn2020coverage} with the proof~\cite[Appendix A]{blaszczyszyn2020coverage}.
\begin{Proposition}\label{p.SINR-conditional}
For given $x_i\in\statespace$ and $\tau\ge0$, the distribution of the SINR  at $y_i$ for a signal coming from $x_i$, given $x_i$ is selected by the scheduler, 
is obtained with expression
\begin{equation}
\Prob\{\,\SINR(x_i,y_i,\Psi)>\tau\,|\,x_i\in\Psi\,\}=
\det(I-K^!_{x_i}\{h_{x_i}\})W_{x_i},
\end{equation}
where the probability above also incorporates the random fading conditions and scheduler decisions.
\end{Proposition}

We now consider the unconditional SINR (tail) distribution at $y_i$ from $x_i\in\statespace$, namely 
\begin{equation}
\calP_i(\tau):= \Prob\{\,x_i\in\Psi\text{\ and\ \ } \SINR(x_i,y_i,\Psi)>\tau\,\},\quad \tau>0. 
\end{equation}
Then we have an expression for the coverage probability $\calP_i$.
\begin{Corollary}
%The unconditional SINR distribution at $y_i$ from $x_i\in\statespace$, is given by
The coverage probability is given by
\begin{equation}\label{e.covprob}
\calP_i(\tau)=[K]_{x_i,x_i}\det(I-K^!_{x_i}\{h_{x_i}\})W_{x_i}.
\end{equation}
\end{Corollary}
\begin{proof}
Note that $\Prob\{x_i\in\Psi\}=
\det(K_{\{x_i\}})=[K]_{x_i,x_i}$. Then we use Proposition~\ref{p.SINR-conditional} by conditioning on $x_i\in\Psi$.
\end{proof}
The matrix $(I-K^!_{x_i})\{h_{x_i}\}$ on the right-hand-side of~\eqref{e.covprob} is indexed by the elements of $\statespace\setminus\{x_i\}$. We extend it to the full configuration $\statespace$
by setting
\begin{equation}\label{e.Kt}    
[K_{x_i}(\tau)]_{x_j,x_k} := \left\{
	\begin{array}{ll}
		[I - K_{x_i}^!\{h_{x_i}\}]_{x_j,x_k}  & \mbox{if } j,k\not=i \\
				W_{x_i} [K]_{x_i,x_i}  & \mbox{if } j=k=i,\\
		0 &\mbox{if $j=i$ and $k\not=i$}\\
             0 &\mbox{if $k=i$ and $j\not=i$}\,  
			\end{array}
	\right. 
\end{equation}
This allows us to express $\calP_i(\tau)$ in a more compact way
\begin{equation}\label{e.covprob-det}
\calP_i(\tau)=\det(K_{x_i}(\tau)).     
\end{equation}

