% \end{equation}
% where matrix $L$ has  the   elements
% \begin{equation}
%     [L]_{x_i,x_j}=q(x_i)[S]_{x_i,x_j}q(x_j)\label{e.LofSq}
% \end{equation}
% for some symmetric, positive semi-definite matrix $L$ indexed by $x_i\in\statespace$ and a non-negative function $q(\cdot)$ defined on $\statespace$. 
We recall that an $L$-ensemble $\Psi$ with matrix $L$ satisfies $\Prob\{\,\Psi=\psi\,\}={\det L_{\psi}}/{\det(L+I)}$. Consequently, the probability of the configuration  $\psi=\{x_{i_1},\ldots,x_{i_k}\}\in\statespace$ being scheduled for the transmission is equal to 
\begin{equation}\label{e.quality-diversity}
\Prob\{\,\psi=\Psi\,\}=
\frac{1}{\det(L+I)}
\prod_{x_{i}\in\psi} q^2(x_i)\det(S_\psi).
\end{equation}
In expression~\eqref{e.quality-diversity}, the quality-squared term
$q^2(x_i)$ controls the medium access probability of each node $x_i$, whereas the matrix $S$ controls the separation of 
different transmissions. The term 
$\det(L+I)$ is just the normalizing constant.
%In particular, taking the identity  matrix $S=I$ corresponds to adaptive Aloha, so the  transmission scheduling happens independently with probabilities proportional to $p(x_i)\propto q^2(x_i)$.

For the matrix $S$, we can use, 
for example, the {\em Gaussian kernel} 
\begin{equation}\label{eq.SGauss}
    [S]_{x_i,x_j}:= e^{-|x_i-x_j|^2/\sigma^2},
\end{equation}
where the scale parameter $\sigma$ controls separation of transmitting nodes.  
%This is a so-called hyperparameter, so it is not used to fit a model, but just to control it. 
As $\sigma\rightarrow0$, the matrix $S$ converges to the identity matrix, giving the (adaptive) Aloha model. 
%Of course other kernels exist, such as the Cauchy and Bessel ones, but we found no significant differences in performance.

